def _continuous_principal_axis_body_frame(
    coordinates_angstrom: np.ndarray,
    masses: np.ndarray,
) -> np.ndarray:
    """Mass-center a geometry and align its inertia axes without frame jumps.

    The input geometry is already expressed in the body frame from the
    preceding optimization point. Among the equivalent permutations and
    signs of the instantaneous inertia eigenvectors, select the proper
    rotation closest to the identity. This is the discrete parallel-
    transport step needed to keep a fixed ellipsoid and its cluster in one
    continuous frame.
    """

    coords = np.asarray(coordinates_angstrom, dtype=float)
    weights = np.asarray(masses, dtype=float).reshape(-1)
    if coords.ndim != 2 or coords.shape != (weights.size, 3):
        raise ValueError("body-frame coordinates and masses have incompatible shapes")
    center = np.average(coords, axis=0, weights=weights)
    centered = coords - center
    inertia = sum(
        weight * (float(vector @ vector) * np.eye(3, dtype=float) - np.outer(vector, vector))
        for vector, weight in zip(centered, weights, strict=True)
    )
    _moments, eigenvectors = np.linalg.eigh(inertia)
    best_frame = None
    best_score = -np.inf
    for order in permutations(range(3)):
        ordered = eigenvectors[:, order]
        for signs in product((-1.0, 1.0), repeat=3):
            candidate = ordered * np.asarray(signs, dtype=float)
            if np.linalg.det(candidate) <= 0.0:
                continue
            score = float(np.trace(candidate))
            if score > best_score:
                best_score = score
                best_frame = candidate
    if best_frame is None:
        raise RuntimeError("failed to construct a proper principal-axis frame")
    return centered @ best_frame


