def _is_interfragment_coordinate_family(family: str) -> bool:
    normalized = str(family).strip().upper()
    return bool(
        normalized.startswith("FRAG_")
        or normalized.startswith("FRAGMENT_")
        or normalized.startswith("PSEUDO_BOND_")
        or normalized in INTERFRAGMENT_COORDINATE_FAMILIES
    )


class ElectronicStateResolutionError(RuntimeError):
    """APOC could not establish one unambiguous state after root expansion."""


def _follow_transferable_state_fingerprint(
    reference,
    candidates,
    *,
    minimum_overlap: float,
    ambiguity_margin: float,
    strict: bool,
):
    """Follow a state using the metric required by its fingerprint representation."""

    candidates = tuple(candidates)
    if reference.representation == "gaussian-td-transition-density-ao-v1":
        from matrix_gaussian.td_tracking import follow_td_ao_fingerprint

        return follow_td_ao_fingerprint(reference, candidates,
            minimum_overlap=minimum_overlap, ambiguity_margin=ambiguity_margin, strict=strict)
    if reference.representation != "orca-tda-transition-density-ao":
        from matrix_apoc import follow_state_fingerprint

        return follow_state_fingerprint(
            reference,
            candidates,
            minimum_overlap=minimum_overlap,
            ambiguity_margin=ambiguity_margin,
            strict=strict,
        )
    if not reference.source or not candidates or not candidates[0].source:
        raise ValueError("ORCA AO transition-density tracking requires Molden sources")
    from matrix_apoc import (
        ExcitedState,
        cross_ao_overlap_from_molden,
        electronic_state_from_molden,
        follow_excited_state,
    )

    size = int(round(math.sqrt(reference.vector.size)))
    if size * size != reference.vector.size:
        raise ValueError("ORCA AO transition-density fingerprint is not square")
    reference_wavefunction = electronic_state_from_molden(reference.source)
    candidate_wavefunction = electronic_state_from_molden(candidates[0].source)
    cross_overlap = cross_ao_overlap_from_molden(reference.source, candidates[0].source)
    reference_state = ExcitedState(
        reference.state_id,
        reference.vector.reshape((size, size)),
        energy_hartree=reference.energy_hartree,
        label=reference.label,
    )
    candidate_states = tuple(
        ExcitedState(
            item.state_id,
            item.vector.reshape((size, size)),
            energy_hartree=item.energy_hartree,
            label=item.label,
        )
        for item in candidates
    )
    selected_state, match = follow_excited_state(
        reference_state,
        candidate_states,
        cross_overlap,
        overlap_reference=reference_wavefunction.overlap_ao,
        overlap_candidate=candidate_wavefunction.overlap_ao,
        minimum_overlap=minimum_overlap,
        ambiguity_margin=ambiguity_margin,
        strict=strict,
    )
    selected = next(item for item in candidates if item.state_id == selected_state.state_id)
    return selected, match


def _normalize_state_irrep(label: object) -> str:
    return str(label).strip().replace("′", "'").replace("″", "''").upper()


def _state_irreps_from_transition_dipoles(
    symmetry,
    dipoles: Mapping[object, object],
) -> dict[int, str]:
    """Assign one-dimensional excited-state irreps from transition dipoles.

    This is an exact symmetry test for an allowed transition from a totally
    symmetric reference state.  Dark states remain deliberately unassigned,
    causing the caller to retain the overlap-based safety path.
    """

    if symmetry is None:
        return {}
    point_group = str(symmetry.point_group).strip().upper()
    if point_group in {"", "UNKNOWN"}:
        return {}
    if point_group == "C1":
        return {int(state_id): "A" for state_id in dipoles}
    from matrix_smith import irrep_characters_for_operations, irrep_dimension

    operation_labels = [operation.label for operation in symmetry.operations]
    operation_matrices = [operation.rotation for operation in symmetry.operations]
    character_table = irrep_characters_for_operations(
        operation_labels,
        point_group=symmetry.point_group,
        operation_matrices=operation_matrices,
    )
    one_dimensional = tuple(
        (label, np.asarray(characters, dtype=float))
        for label, characters in character_table
        if irrep_dimension(label) == 1
    )
    assigned: dict[int, str] = {}
    for state_id, raw_dipole in dipoles.items():
        vector = np.asarray(raw_dipole, dtype=float).reshape(-1)
        norm2 = float(vector @ vector)
        if vector.shape != (3,) or not np.all(np.isfinite(vector)) or norm2 <= 1.0e-12:
            continue
        observed: list[float] = []
        residual = 0.0
        for operation in symmetry.operations:
            transformed = np.asarray(operation.rotation, dtype=float) @ vector
            character = float(vector @ transformed / norm2)
            observed.append(character)
            residual = max(
                residual,
                float(np.linalg.norm(transformed - character * vector) / math.sqrt(norm2)),
            )
        if residual > 1.0e-5:
            continue
        observed_array = np.asarray(observed, dtype=float)
        matches = [
            (float(np.max(np.abs(observed_array - characters))), label)
            for label, characters in one_dimensional
        ]
        if not matches:
            continue
        error, label = min(matches)
        if error <= 1.0e-5:
            assigned[int(state_id)] = str(label)
    return assigned


