def _validate_final_transition_state(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    model: OptimizerCoordinateModel,
    approximate_hessian: np.ndarray,
    settings: OptimizerSettings,
    tracked_mode: TransitionModeReference | None,
    root: Path,
    irc_target_geometries: Sequence[np.ndarray] = (),
) -> tuple[
    np.ndarray,
    bool,
    Path | None,
    tuple[float, ...],
    dict[str, object] | None,
    Path | None,
    dict[str, bool],
]:
    """Require an exact first-order saddle and verify both IRC branches."""

    validation = {
        "exact_hessian": not settings.require_exact_final_hessian,
        "one_imaginary_frequency": not settings.require_exact_final_hessian,
        "exact_mode_overlap": not settings.require_exact_final_hessian,
        "irc": not settings.verify_irc,
    }
    # Reduced-coordinate TS searches (RAMA rigid torsions, PIC/SONIC scans)
    # deliberately certify the updated internal Hessian without requesting a
    # Cartesian backend Hessian.  This is distinct from the normal exact TS
    # path, which continues below unchanged.
    if not settings.require_exact_final_hessian and not settings.verify_irc:
        return (
            approximate_hessian,
            False,
            None,
            (),
            {
                "schema": TRANSITION_STATE_VALIDATION_SCHEMA,
                "status": "reduced_coordinate_validation",
                "hessian_space": model.kind,
                "exact_cartesian_hessian": False,
            },
            None,
            validation,
        )
    exact = _evaluate_final_cartesian_hessian(
        service,
        current,
        q,
        tag="final-transition-state-hessian",
    )
    cartesian = exact.result.hessian_hartree_per_bohr2
    if cartesian is None:
        return (
            approximate_hessian,
            False,
            None,
            (),
            {
                "schema": TRANSITION_STATE_VALIDATION_SCHEMA,
                "status": "missing_exact_cartesian_hessian",
            },
            None,
            validation,
        )
    cartesian_matrix = np.asarray(cartesian, dtype=float)
    expected = current.coordinates_angstrom.size
    if cartesian_matrix.shape != (expected, expected):
        raise ValueError(
            "final Cartesian Hessian has shape "
            f"{cartesian_matrix.shape}, expected {(expected, expected)}"
        )
    cartesian_gradient = exact.gradient_hartree_per_bohr
    if model.kind == "sonic" and cartesian_gradient is None:
        raise RuntimeError(
            "a physical final Hessian requires the Cartesian gradient for "
            "the exact B-prime transformation"
        )
    cartesian_path = root / "final_cartesian_hessian.json"
    cartesian_path.write_text(
        json.dumps(
            {
                "schema": "matrix.link.final_cartesian_hessian.v1",
                "units": "hartree/bohr^2",
                "atoms": list(service.atoms),
                "coordinates_angstrom": exact.coordinates_angstrom.tolist(),
                "gradient_hartree_per_bohr": (
                    None if cartesian_gradient is None else cartesian_gradient.tolist()
                ),
                "hessian": cartesian_matrix.tolist(),
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )
    _write_final_matrix_gfn2_scaling_observables(
        service,
        exact.coordinates_angstrom,
        root,
    )
    exact_optimizer_hessian = (
        optimizer_hessian_from_cartesian(
            cartesian_matrix,
            model,
            cartesian_gradient_hartree_per_bohr=cartesian_gradient,
            coordinates_angstrom=exact.coordinates_angstrom,
        )
        if model.kind == "sonic"
        else optimizer_hessian_from_cartesian(cartesian_matrix, model)
    )
    physical_modes = _exact_cartesian_normal_modes(
        service.atoms,
        exact.coordinates_angstrom,
        cartesian_matrix,
    )
    frequencies = tuple(float(value) for value in physical_modes.frequencies_cm)
    imaginary_count = int(np.count_nonzero(np.asarray(frequencies) < -1.0e-6))
    validation["exact_hessian"] = True
    validation["one_imaginary_frequency"] = imaginary_count == 1
    if imaginary_count != 1:
        validation["exact_mode_overlap"] = False
        validation["irc"] = False
        return (
            exact_optimizer_hessian,
            True,
            cartesian_path,
            frequencies,
            None,
            None,
            validation,
        )
    exact_mode, mode_overlap, _selected_frequencies = _select_exact_cartesian_transition_mode(
        service.atoms,
        exact.coordinates_angstrom,
        cartesian_matrix,
        tracked_mode,
    )
    active_mode_fraction = _cartesian_mode_active_subspace_fraction(
        exact_mode,
        service.coordinate_directions(exact.coordinates_angstrom),
    )
    symmetry_forbidden_active_mode = bool(
        _is_totally_symmetric_restricted_model(model) and active_mode_fraction < 1.0e-4
    )
    tracked_exact_mode_overlap = bool(
        mode_overlap >= settings.transition_mode_overlap_threshold or symmetry_forbidden_active_mode
    )
    validation["exact_mode_overlap"] = tracked_exact_mode_overlap
    irc_report: dict[str, object] | None = None
    irc_path: Path | None = None
    if settings.verify_irc:
        irc_report, irc_path = _verify_transition_state_irc(
            service,
            exact,
            q,
            exact_optimizer_hessian,
            exact_mode,
            settings,
            root,
            irc_target_geometries,
        )
        validation["irc"] = bool(irc_report.get("verified", False))
        # A bidirectional path to the declared distinct minima is a stronger
        # physical identity test than overlap with an approximate seed mode.
        # Keep the overlap in the report, but do not reject an exact index-one
        # saddle whose validated IRC supplies that identity independently.
        irc_report["tracked_exact_mode_overlap"] = float(mode_overlap)
        irc_report["tracked_exact_mode_overlap_passed"] = bool(tracked_exact_mode_overlap)
        irc_report["exact_mode_active_subspace_fraction"] = float(active_mode_fraction)
        irc_report["exact_mode_symmetry_forbidden_in_active_chart"] = bool(
            symmetry_forbidden_active_mode
        )
        validation["exact_mode_overlap"] = bool(tracked_exact_mode_overlap or validation["irc"])
        irc_path.write_text(
            json.dumps(irc_report, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
    return (
        exact_optimizer_hessian,
        True,
        cartesian_path,
        frequencies,
        irc_report,
        irc_path,
        validation,
    )


def _validate_final_minimum(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    model: OptimizerCoordinateModel,
    approximate_hessian: np.ndarray,
    root: Path,
) -> tuple[np.ndarray, bool, Path | None, tuple[float, ...], dict[str, bool]]:
    """Require an exact Cartesian Hessian with no imaginary vibration."""

    validation = {
        "exact_hessian": False,
        "zero_imaginary_frequencies": False,
    }
    exact = _evaluate_final_cartesian_hessian(
        service,
        current,
        q,
        tag="final-minimum-hessian",
    )
    cartesian = exact.result.hessian_hartree_per_bohr2
    if cartesian is None:
        return approximate_hessian, False, None, (), validation
    cartesian_matrix = np.asarray(cartesian, dtype=float)
    expected = current.coordinates_angstrom.size
    if cartesian_matrix.shape != (expected, expected):
        raise ValueError(
            "final Cartesian Hessian has shape "
            f"{cartesian_matrix.shape}, expected {(expected, expected)}"
        )
    cartesian_gradient = exact.gradient_hartree_per_bohr
    if model.kind == "sonic" and cartesian_gradient is None:
        raise RuntimeError(
            "a physical final Hessian requires the Cartesian gradient for "
            "the exact B-prime transformation"
        )
    cartesian_path = root / "final_cartesian_hessian.json"
    cartesian_path.write_text(
        json.dumps(
            {
                "schema": "matrix.link.final_cartesian_hessian.v1",
                "units": "hartree/bohr^2",
                "atoms": list(service.atoms),
                "coordinates_angstrom": exact.coordinates_angstrom.tolist(),
                "gradient_hartree_per_bohr": (
                    None if cartesian_gradient is None else cartesian_gradient.tolist()
                ),
                "hessian": cartesian_matrix.tolist(),
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )
    _write_final_matrix_gfn2_scaling_observables(
        service,
        exact.coordinates_angstrom,
        root,
    )
    exact_optimizer_hessian = (
        optimizer_hessian_from_cartesian(
            cartesian_matrix,
            model,
            cartesian_gradient_hartree_per_bohr=cartesian_gradient,
            coordinates_angstrom=exact.coordinates_angstrom,
        )
        if model.kind == "sonic"
        else optimizer_hessian_from_cartesian(cartesian_matrix, model)
    )
    frequencies = _exact_cartesian_frequencies_cm(
        service.atoms,
        exact.coordinates_angstrom,
        cartesian_matrix,
    )
    validation["exact_hessian"] = True
    validation["zero_imaginary_frequencies"] = not any(
        frequency < -1.0e-6 for frequency in frequencies
    )
    return exact_optimizer_hessian, True, cartesian_path, frequencies, validation


def _write_final_matrix_gfn2_scaling_observables(
    service: GeometryEvaluationService,
    coordinates_angstrom: np.ndarray,
    root: Path,
) -> Path | None:
    """Persist native SCC/Mayer descriptors inside the KeyMaker calculation."""

    backend = getattr(service, "backend", None)
    backend_name = _normalized_backend_name(backend.name) if backend is not None else ""
    session = getattr(service, "_matrix_gfn2_session", None)
    if backend_name != "matrix_gfn2" or session is None:
        return None
    target = root / "gfn2_scaling_observables.json"
    if target.is_file():
        try:
            existing = json.loads(target.read_text(encoding="utf-8"))
            stored = np.asarray(existing.get("coordinates_angstrom", ()), dtype=float)
            requested = np.asarray(coordinates_angstrom, dtype=float)
            if stored.shape == requested.shape and np.allclose(
                stored, requested, rtol=0.0, atol=1.0e-12
            ):
                return target
        except (OSError, TypeError, ValueError, json.JSONDecodeError):
            pass
    return session.write_scaling_observables(target, coordinates_angstrom)


def _evaluate_final_cartesian_hessian(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    *,
    tag: str,
) -> OptimizerEvaluation:
    """Prefer the backend Hessian; difference gradients only when unavailable.

    MATRIX-GFN2 ground states expose their analytic Cartesian Hessian through
    the resident session. Calculation failures propagate rather than silently
    replacing a failed analytic calculation with finite differences.
    """

    backend = getattr(service, "backend", None)
    backend_name = _normalized_backend_name(backend.name) if backend is not None else ""
    gradient_only_backend = backend_name in {
        "std2",
        "gfnff",
        "gfnff_reference",
        "openmm",
        "pyfock",
    } or (backend_name == "pyscf" and getattr(service, "_pyscf_session", None) is not None)
    gradient_only_backend = gradient_only_backend or (
        backend_name == "matrix_gfn2" and int(backend.electronic_state) > 0
    )
    if backend_name == "capped_subtractive":
        gradient_only_backend = any(
            _normalized_backend_name(term.backend.name) in {"gfnff", "gfnff_reference"}
            for term in backend.composite_terms)
    if not gradient_only_backend:
        exact = service.evaluate(
            q,
            tag=tag,
            use_cache=False,
            persist_cache=True,
            requested_properties=("energy", "gradient", "hessian"),
        )
        if exact.result.hessian_hartree_per_bohr2 is not None:
            return exact
    return _finite_difference_final_cartesian_hessian(
        service,
        current,
        q,
        tag=tag,
    )


def _finite_difference_final_cartesian_hessian(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    *,
    tag: str,
) -> OptimizerEvaluation:
    """Build a physical Cartesian Hessian from central gradient differences."""

    coordinates = np.asarray(current.coordinates_angstrom, dtype=float)
    if getattr(service, "_std2_session", None) is not None:
        # Both Hessian sides follow the same central state; no displaced trial
        # may promote the session's accepted APOC reference.
        service._std2_session.accept(current.result)
    flat = coordinates.reshape(-1)
    ncart = flat.size
    point_backend = getattr(service, "backend", None)
    step_bohr = (
        point_backend.std2_hessian_step_bohr
        if point_backend is not None and _normalized_backend_name(point_backend.name) == "std2"
        else FINAL_CARTESIAN_HESSIAN_FD_STEP_BOHR
    )
    if not math.isfinite(step_bohr) or step_bohr <= 0:
        raise ValueError("Cartesian Hessian gradient-difference step must be positive and finite")
    step_angstrom = step_bohr / ANGSTROM_TO_BOHR
    hessian = np.zeros((ncart, ncart), dtype=float)
    backend = getattr(service, "backend", None)
    backend_name = _normalized_backend_name(backend.name) if backend is not None else ""
    direct_matrix_gfn2 = backend_name == "matrix_gfn2" and not bool(
        getattr(getattr(service, "settings", None), "include_cv_exponential_field", False)
    )
    center_gradient = current.gradient_hartree_per_bohr
    gradient_evaluations = 2 * ncart
    if direct_matrix_gfn2:
        # Use an independent SCF calculation for every displaced point.
        # Reusing the central SCF state in finite-displacement calculations
        # amplifies the antisymmetric Hessian error and can change the sign of
        # soft modes at the standard 1e-3 bohr step.
        from .resident_calculators import create_resident_calculator

        reference_session = create_resident_calculator(
            "matrix_gfn2",
            tuple(service.atoms),
            coordinates,
            charge=backend.charge,
            multiplicity=backend.multiplicity,
            method=backend.method or "GFN2-xTB",
        )
        center = reference_session.evaluate(coordinates)
        center_gradient = np.asarray(center.gradient_hartree_per_bohr, dtype=float).reshape(-1)
        for column in range(ncart):
            plus = flat.copy()
            minus = flat.copy()
            plus[column] += step_angstrom
            minus[column] -= step_angstrom
            plus_gradient = (
                create_resident_calculator(
                    "matrix_gfn2",
                    tuple(service.atoms),
                    plus.reshape(coordinates.shape),
                    charge=backend.charge,
                    multiplicity=backend.multiplicity,
                    method=backend.method or "GFN2-xTB",
                )
                .evaluate(plus.reshape(coordinates.shape))
                .gradient_hartree_per_bohr
            )
            minus_gradient = (
                create_resident_calculator(
                    "matrix_gfn2",
                    tuple(service.atoms),
                    minus.reshape(coordinates.shape),
                    charge=backend.charge,
                    multiplicity=backend.multiplicity,
                    method=backend.method or "GFN2-xTB",
                )
                .evaluate(minus.reshape(coordinates.shape))
                .gradient_hartree_per_bohr
            )
            hessian[:, column] = (
                np.asarray(plus_gradient, dtype=float).reshape(-1)
                - np.asarray(minus_gradient, dtype=float).reshape(-1)
            ) / (2.0 * step_bohr)
        gradient_evaluations += 1
        lock = getattr(service, "_lock", None)
        if lock is None:
            service.qm_evaluations += gradient_evaluations
            service.final_hessian_energy_evaluations += gradient_evaluations
            service.gradient_evaluations += gradient_evaluations
            service.fd_displacements += 2 * ncart
        else:
            with lock:
                service.qm_evaluations += gradient_evaluations
                service.final_hessian_energy_evaluations += gradient_evaluations
                service.gradient_evaluations += gradient_evaluations
                service.fd_displacements += 2 * ncart
    else:
        for column in range(ncart):
            plus = flat.copy()
            minus = flat.copy()
            plus[column] += step_angstrom
            minus[column] -= step_angstrom
            plus_evaluation = service.evaluate(
                q,
                tag=f"{tag}-fd-plus-{column + 1}",
                use_cache=False,
                persist_cache=False,
                requested_properties=("energy", "gradient"),
                realized_coordinates_angstrom=plus.reshape(coordinates.shape),
                enforce_gradient_symmetry=False,
            )
            minus_evaluation = service.evaluate(
                q,
                tag=f"{tag}-fd-minus-{column + 1}",
                use_cache=False,
                persist_cache=False,
                requested_properties=("energy", "gradient"),
                realized_coordinates_angstrom=minus.reshape(coordinates.shape),
                enforce_gradient_symmetry=False,
            )
            plus_gradient = plus_evaluation.gradient_hartree_per_bohr
            minus_gradient = minus_evaluation.gradient_hartree_per_bohr
            if plus_gradient is None or minus_gradient is None:
                raise RuntimeError(
                    "final Cartesian Hessian finite differences require Cartesian gradients"
                )
            hessian[:, column] = (plus_gradient - minus_gradient) / (2.0 * step_bohr)
    raw_antisymmetric_max = float(np.max(np.abs(hessian - hessian.T)))
    hessian = 0.5 * (hessian + hessian.T)
    symmetry = getattr(service, "_assigned_cartesian_symmetry", None)
    operations = tuple(getattr(symmetry, "operations", ()))
    if operations:
        hessian = _point_group_average_cartesian_hessian(
            hessian,
            operations=operations,
            natoms=len(service.atoms),
        )
    if hasattr(service, "hessian_evaluations"):
        lock = getattr(service, "_lock", None)
        if lock is None:
            service.hessian_evaluations += 1
        else:
            with lock:
                service.hessian_evaluations += 1
    execution = dict(current.result.execution)
    if backend_name == "std2":
        execution["final_cartesian_hessian_raw_antisymmetric_max"] = raw_antisymmetric_max
    execution.update(
        {
            "final_cartesian_hessian_source": ("central_finite_difference_cartesian_gradients"),
            "final_cartesian_hessian_fd_step_bohr": step_bohr,
            "final_cartesian_hessian_gradient_evaluations": gradient_evaluations,
            "final_cartesian_hessian_independent_displaced_scf": direct_matrix_gfn2,
            "hessian_evaluations": 1,
        }
    )
    return replace(
        current,
        result=replace(
            current.result,
            gradient_hartree_per_bohr=center_gradient,
            hessian_hartree_per_bohr2=hessian,
            execution=execution,
        ),
    )


def _exact_cartesian_frequencies_cm(
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    cartesian_hessian: np.ndarray,
) -> tuple[float, ...]:
    modes = _exact_cartesian_normal_modes(
        atoms,
        coordinates_angstrom,
        cartesian_hessian,
    )
    return tuple(float(value) for value in modes.frequencies_cm)


def _exact_cartesian_normal_modes(
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    cartesian_hessian: np.ndarray,
):
    """Return physical vibrational modes after Cartesian T/R projection."""

    from matrix_chem import atomic_mass
    from matrix_chem.topology.elements import atomic_number
    from matrix_gf import cartesian_normal_modes_from_hessian

    masses = np.asarray(
        [atomic_mass(int(atomic_number(atom) or 0)) for atom in atoms],
        dtype=float,
    )
    try:
        modes = cartesian_normal_modes_from_hessian(
            cartesian_hessian,
            masses,
            np.asarray(coordinates_angstrom, dtype=float) * ANGSTROM_TO_BOHR,
            project_external=True,
            source="LINK exact final TS Hessian",
        )
    except ValueError as exc:
        if len(atoms) > 1 or "no vibrational Cartesian subspace" not in str(exc):
            raise
        modes = cartesian_normal_modes_from_hessian(
            cartesian_hessian,
            masses,
            np.asarray(coordinates_angstrom, dtype=float) * ANGSTROM_TO_BOHR,
            project_external=False,
            source="LINK exact final TS Hessian (unprojected atom)",
        )
    return modes


def _select_exact_cartesian_transition_mode(
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    cartesian_hessian: np.ndarray,
    reference: TransitionModeReference | None,
) -> tuple[np.ndarray, float, tuple[float, ...]]:
    """Select the unique physical downhill mode, including non-total irreps.

    A symmetry-preserving saddle revalidation can deliberately use only the
    totally symmetric SONIC block.  The reaction mode of the exact saddle may
    then belong to another irrep and be absent from the optimizer Hessian.
    IRC initiation is a physical Cartesian operation, so its index and tangent
    must come from the translation/rotation-projected Cartesian Hessian.
    """

    coordinates = np.asarray(coordinates_angstrom, dtype=float)
    modes = _exact_cartesian_normal_modes(atoms, coordinates, cartesian_hessian)
    values = np.asarray(modes.eigenvalues, dtype=float).reshape(-1)
    negative = np.flatnonzero(values < -1.0e-12)
    if negative.size != 1:
        raise ValueError(
            "exact IRC initiation requires one negative Cartesian vibrational "
            f"mode; found {negative.size}"
        )
    vector = np.asarray(modes.cartesian_directions[int(negative[0])], dtype=float).reshape(-1)
    vector /= max(float(np.linalg.norm(vector)), 1.0e-30)
    overlap, selected = _gdv_first_mode_reference(
        vector.reshape((-1, 1)),
        np.ones((1, 1), dtype=float),
        coordinates,
        reference,
    )
    frequencies = tuple(float(value) for value in modes.frequencies_cm)
    return selected.cartesian_vector, float(overlap), frequencies


def _cartesian_mode_active_subspace_fraction(
    cartesian_mode: np.ndarray,
    coordinate_directions: np.ndarray,
) -> float:
    """Return the norm fraction represented by the current optimizer chart."""

    vector = np.asarray(cartesian_mode, dtype=float).reshape(-1)
    rows = np.asarray(coordinate_directions, dtype=float)
    if rows.ndim != 2 or rows.shape[1] != vector.size:
        raise ValueError("active coordinate directions do not match Cartesian mode")
    norm = float(np.linalg.norm(vector))
    if norm <= 1.0e-30 or rows.shape[0] == 0:
        return 0.0
    _left, singular, right = np.linalg.svd(rows, full_matrices=False)
    if singular.size == 0 or singular[0] <= 0.0:
        return 0.0
    rank = int(np.count_nonzero(singular > singular[0] * 1.0e-10))
    basis = right[:rank].T
    return float(np.linalg.norm(basis @ (basis.T @ vector)) / norm)


def _is_totally_symmetric_restricted_model(model: OptimizerCoordinateModel) -> bool:
    """Identify a complete SONIC definition restricted to its total irrep."""

    definition = model.sonic_definition
    if model.kind != "sonic" or definition is None or not definition.symmetrize:
        return False
    from matrix_smith.symmetry_labels import irrep_sequence

    totally_symmetric = irrep_sequence(definition.point_group)[0]
    labels_to_irreps = {str(gic.name or gic.identifier): str(gic.irrep) for gic in definition.gics}
    return bool(
        len(model.labels) < len(definition.gics)
        and model.labels
        and all(labels_to_irreps.get(label) == totally_symmetric for label in model.labels)
    )


def _verify_transition_state_irc(
    service: GeometryEvaluationService,
    saddle: OptimizerEvaluation,
    saddle_q: np.ndarray,
    hessian: np.ndarray,
    cartesian_mode: np.ndarray,
    settings: OptimizerSettings,
    root: Path,
    target_geometries: Sequence[np.ndarray] = (),
) -> tuple[dict[str, object], Path]:
    """Follow both physical IRC branches with a predictor-corrector integrator.

    SONIC supplies the non-redundant chart used to locate and classify the
    saddle.  The IRC itself is, by definition, steepest descent in
    mass-weighted Cartesian coordinates.  Integrating it in that physical
    space also avoids making the path depend on a particular nonsingular
    recombination of the SONIC rows.
    """

    from matrix_chem import atomic_mass
    from matrix_chem.topology.elements import atomic_number

    masses = np.asarray(
        [atomic_mass(int(atomic_number(atom) or 0)) for atom in service.atoms],
        dtype=float,
    )
    mass_sqrt = np.sqrt(np.repeat(masses, 3))
    saddle_coordinates = np.asarray(saddle.coordinates_angstrom, dtype=float)
    saddle_mass_coordinates = _irc_mass_weighted_cartesian_coordinates(
        saddle_coordinates,
        mass_sqrt,
    )
    cartesian_hessian = saddle.result.hessian_hartree_per_bohr2
    if cartesian_hessian is None:
        raise RuntimeError("predictor-corrector IRC requires the exact saddle Hessian")
    saddle_mass_hessian = _irc_mass_weighted_cartesian_hessian(
        np.asarray(cartesian_hessian, dtype=float),
        mass_sqrt,
    )
    saddle_mass_gradient = _irc_mass_weighted_cartesian_gradient(
        saddle.gradient_hartree_per_bohr,
        mass_sqrt,
    )

    cartesian_direction_angstrom = np.asarray(cartesian_mode, dtype=float).reshape(-1)
    if cartesian_direction_angstrom.shape != (saddle_coordinates.size,):
        raise ValueError("exact Cartesian transition mode has the wrong dimension")
    mass_direction = cartesian_direction_angstrom * ANGSTROM_TO_BOHR * mass_sqrt
    direction_norm = float(np.linalg.norm(mass_direction))
    if not np.isfinite(direction_norm) or direction_norm <= 1.0e-30:
        raise RuntimeError("exact transition mode has no Cartesian IRC tangent")
    mass_direction /= direction_norm

    targets = tuple(np.asarray(item, dtype=float) for item in target_geometries)
    if targets and (
        len(targets) != 2 or any(item.shape != saddle_coordinates.shape for item in targets)
    ):
        raise ValueError("IRC target geometries must contain two n_atoms x 3 structures")
    target_permutations = tuple(
        _irc_target_topology_permutations(service.atoms, target) for target in targets
    )
    if settings.irc_continuation_report:
        return _continue_transition_state_irc(
            service,
            saddle,
            settings,
            root,
            targets,
            target_permutations,
            masses,
            mass_sqrt,
            mass_direction,
        )

    def target_rmsds(coordinates: np.ndarray) -> tuple[float, ...]:
        return tuple(
            _minimum_permutation_aligned_rmsd(coordinates, target, permutations)
            for target, permutations in zip(targets, target_permutations, strict=True)
        )

    def evaluate_mass_point(
        mass_coordinates: np.ndarray,
        *,
        tag: str,
    ) -> tuple[OptimizerEvaluation, np.ndarray, np.ndarray]:
        coordinates = _irc_cartesian_coordinates_from_mass_weighted(
            mass_coordinates,
            mass_sqrt,
            saddle_coordinates.shape,
        )
        coordinates = _mass_weighted_kabsch_align(
            coordinates,
            saddle_coordinates,
            masses,
        )
        realized_mass_coordinates = _irc_mass_weighted_cartesian_coordinates(
            coordinates,
            mass_sqrt,
        )
        q = service.actual_q(coordinates)
        evaluation = service.evaluate(
            q,
            tag=tag,
            use_cache=False,
            persist_cache=True,
            requested_properties=("energy", "gradient"),
            realized_coordinates_angstrom=coordinates,
            enforce_gradient_symmetry=False,
        )
        gradient = _irc_mass_weighted_cartesian_gradient(
            evaluation.gradient_hartree_per_bohr,
            mass_sqrt,
        )
        return evaluation, realized_mass_coordinates, gradient

    initial_states: list[tuple[str, OptimizerEvaluation, np.ndarray, np.ndarray]] = []
    for sign, label in ((-1.0, "reverse"), (1.0, "forward")):
        initial_mass_coordinates = (
            saddle_mass_coordinates + sign * settings.irc_step_size * mass_direction
        )
        evaluation, mass_coordinates, mass_gradient = evaluate_mass_point(
            initial_mass_coordinates,
            tag=f"irc-{label}-000",
        )
        initial_states.append((label, evaluation, mass_coordinates, mass_gradient))
    if targets:
        _initial_rmsds, target_assignment = _irc_distinct_target_assignment(
            tuple(
                np.asarray(state[1].coordinates_angstrom, dtype=float) for state in initial_states
            ),
            targets,
            target_permutations,
        )
    else:
        target_assignment = (None, None)

    branches: list[dict[str, object]] = []
    endpoint_coordinates: list[np.ndarray] = []
    for branch_index, (label, evaluation, mass_coordinates, mass_gradient) in enumerate(
        initial_states
    ):
        assigned_target = target_assignment[branch_index]
        branch_hessian, _initial_update = _bofill_update(
            saddle_mass_hessian,
            mass_coordinates - saddle_mass_coordinates,
            mass_gradient - saddle_mass_gradient,
        )
        points: list[dict[str, object]] = []
        converged = False
        target_reached = False
        termination = "SEGMENT_STEP_BOUND"
        cumulative_arc = float(settings.irc_step_size)
        peak_gradient_norm = float(np.linalg.norm(mass_gradient))
        initial_gradient_norm = peak_gradient_norm
        last_correction_error = 0.0
        last_subdivisions = 0
        last_accepted_arc = 0.0
        for step_index in range(settings.irc_max_steps + 1):
            cartesian_gradient = evaluation.gradient_hartree_per_bohr
            gradient_inf_norm = (
                0.0 if cartesian_gradient is None else float(np.max(np.abs(cartesian_gradient)))
            )
            mass_weighted_gradient_norm = float(np.linalg.norm(mass_gradient))
            peak_gradient_norm = max(peak_gradient_norm, mass_weighted_gradient_norm)
            target_rmsd = None
            all_target_rmsds: tuple[float, ...] = ()
            if targets:
                all_target_rmsds = target_rmsds(evaluation.coordinates_angstrom)
                if assigned_target is None:
                    raise RuntimeError("IRC branch lacks its distinct target assignment")
                target_rmsd = all_target_rmsds[assigned_target]
            points.append(
                {
                    "step": step_index,
                    "q": np.asarray(evaluation.q, dtype=float).tolist(),
                    "energy_hartree": evaluation.energy_hartree,
                    "gradient_inf_norm": gradient_inf_norm,
                    "gradient_mass_weighted_norm": mass_weighted_gradient_norm,
                    "target_rmsd_angstrom": target_rmsd,
                    "target_rmsds_angstrom": list(all_target_rmsds),
                    "assigned_target_index": assigned_target,
                    "cumulative_mass_weighted_arc": cumulative_arc,
                    "accepted_mass_weighted_arc": last_accepted_arc,
                    "corrector_error": last_correction_error,
                    "corrector_subdivisions": last_subdivisions,
                }
            )
            if target_rmsd is not None and target_rmsd <= settings.irc_target_rmsd_tolerance:
                converged = True
                target_reached = True
                termination = "TARGET_REACHED"
                break
            if _irc_minimum_convergence_ready(
                gradient_norm=mass_weighted_gradient_norm,
                peak_gradient_norm=peak_gradient_norm,
                initial_gradient_norm=initial_gradient_norm,
                cumulative_arc=cumulative_arc,
                nominal_step=settings.irc_step_size,
                tolerance=settings.irc_gradient_tolerance,
            ):
                converged = True
                termination = "MINIMUM_CONVERGED"
                break
            if step_index == settings.irc_max_steps:
                break
            step_limit = settings.irc_step_size
            if target_rmsd is not None:
                # Use long IRC strides far from a known minimum and taper them
                # continuously near the RMSD identification threshold.
                step_limit = min(
                    2.0 * settings.irc_step_size,
                    settings.irc_step_size
                    * max(1.0, target_rmsd / settings.irc_target_rmsd_tolerance),
                )
            accepted = None
            accepted_mass_coordinates = None
            accepted_mass_gradient = None
            accepted_hessian = None
            for reduction in range(7):
                trial_arc = step_limit * (0.5**reduction)
                predictor_mass_coordinates, predictor_subdivisions = _irc_local_quadratic_predictor(
                    mass_coordinates,
                    mass_gradient,
                    branch_hessian,
                    trial_arc,
                )
                try:
                    predictor, predictor_mass_coordinates, predictor_gradient = evaluate_mass_point(
                        predictor_mass_coordinates,
                        tag=(f"irc-{label}-{step_index + 1:03d}-pc{reduction}-predictor"),
                    )
                except RuntimeError:
                    continue
                predictor_hessian, _predictor_update = _bofill_update(
                    branch_hessian,
                    predictor_mass_coordinates - mass_coordinates,
                    predictor_gradient - mass_gradient,
                )
                corrected_mass_coordinates, correction_error, corrector_subdivisions = (
                    _irc_dwi_corrector(
                        mass_coordinates,
                        evaluation.energy_hartree,
                        mass_gradient,
                        branch_hessian,
                        predictor_mass_coordinates,
                        predictor.energy_hartree,
                        predictor_gradient,
                        predictor_hessian,
                        trial_arc,
                    )
                )
                try:
                    candidate, candidate_mass_coordinates, candidate_gradient = evaluate_mass_point(
                        corrected_mass_coordinates,
                        tag=(f"irc-{label}-{step_index + 1:03d}-pc{reduction}-corrected"),
                    )
                except RuntimeError:
                    continue
                if candidate.energy_hartree >= evaluation.energy_hartree - 1.0e-14:
                    continue
                candidate_hessian, _accepted_update = _bofill_update(
                    branch_hessian,
                    candidate_mass_coordinates - mass_coordinates,
                    candidate_gradient - mass_gradient,
                )
                accepted = candidate
                accepted_mass_coordinates = candidate_mass_coordinates
                accepted_mass_gradient = candidate_gradient
                accepted_hessian = candidate_hessian
                last_accepted_arc = trial_arc
                last_correction_error = correction_error
                last_subdivisions = max(
                    predictor_subdivisions,
                    corrector_subdivisions,
                )
                break
            if (
                accepted is None
                or accepted_mass_coordinates is None
                or accepted_mass_gradient is None
                or accepted_hessian is None
            ):
                termination = "STEP_FAILURE"
                break
            evaluation = accepted
            mass_coordinates = accepted_mass_coordinates
            mass_gradient = accepted_mass_gradient
            branch_hessian = accepted_hessian
            cumulative_arc += last_accepted_arc
        endpoint_coordinates.append(np.asarray(evaluation.coordinates_angstrom, dtype=float))
        branches.append(
            {
                "direction": label,
                "converged_minimum": converged,
                "target_reached": target_reached,
                "assigned_target_index": assigned_target,
                "termination": termination,
                "initial_energy_below_saddle": bool(
                    points and float(points[0]["energy_hartree"]) < saddle.energy_hartree
                ),
                "endpoint_energy_hartree": evaluation.energy_hartree,
                "endpoint_q": np.asarray(evaluation.q, dtype=float).tolist(),
                "cumulative_mass_weighted_arc": cumulative_arc,
                "peak_mass_weighted_gradient_norm": peak_gradient_norm,
                "continuation_checkpoint": {
                    "schema": IRC_BRANCH_CHECKPOINT_SCHEMA,
                    "coordinates_angstrom": np.asarray(
                        evaluation.coordinates_angstrom, dtype=float
                    ).tolist(),
                    "mass_coordinates": np.asarray(mass_coordinates, dtype=float).tolist(),
                    "mass_gradient": np.asarray(mass_gradient, dtype=float).tolist(),
                    "mass_hessian": np.asarray(branch_hessian, dtype=float).tolist(),
                    "initial_mass_weighted_gradient_norm": initial_gradient_norm,
                    "peak_mass_weighted_gradient_norm": peak_gradient_norm,
                    "cumulative_mass_weighted_arc": cumulative_arc,
                    "last_step": int(points[-1]["step"]),
                    "endpoint_energy_hartree": evaluation.energy_hartree,
                },
                "points": points,
            }
        )
    endpoint_separation_rmsd = (
        _aligned_rmsd(endpoint_coordinates[0], endpoint_coordinates[1])
        if len(endpoint_coordinates) == 2
        else 0.0
    )
    separated = bool(endpoint_separation_rmsd > 1.0e-3)
    target_matches: dict[str, object] = {}
    target_ok = True
    if targets:
        rmsds, assignment = _irc_distinct_target_assignment(
            tuple(endpoint_coordinates),
            targets,
            target_permutations,
        )
        target_ok = all(value <= settings.irc_target_rmsd_tolerance for value in rmsds)
        target_matches = {
            "verified": target_ok,
            "rmsd_angstrom": list(rmsds),
            "target_assignment": list(assignment),
            "threshold_angstrom": settings.irc_target_rmsd_tolerance,
            "atom_mapping": "ORACLE_TARGET_TOPOLOGY_AUTOMORPHISMS",
        }
    verified = bool(
        separated
        and all(bool(branch["converged_minimum"]) for branch in branches)
        and all(bool(branch["initial_energy_below_saddle"]) for branch in branches)
        and target_ok
    )
    report: dict[str, object] = {
        "schema": IRC_VERIFICATION_SCHEMA,
        "verified": verified,
        "endpoints_distinct": separated,
        "endpoint_separation_rmsd_angstrom": endpoint_separation_rmsd,
        "symmetry_contract": "SADDLE_GROUP_RELEASED_ALONG_EXACT_NEGATIVE_MODE",
        "path_metric": "MASS_WEIGHTED_CARTESIAN",
        "integrator": "EULER_PREDICTOR_CORRECTOR_DWI_BOFILL",
        "saddle_coordinate_model": "SONIC",
        "continuation_contract": {
            "schema": IRC_CONTINUATION_CONTRACT_SCHEMA,
            "atoms": list(service.atoms),
            "saddle_coordinates_angstrom": saddle_coordinates.tolist(),
            "exact_negative_mass_direction": mass_direction.tolist(),
            "irc_step_size": settings.irc_step_size,
            "irc_gradient_tolerance": settings.irc_gradient_tolerance,
            "irc_target_rmsd_tolerance": settings.irc_target_rmsd_tolerance,
            "target_geometries_angstrom": [target.tolist() for target in targets],
            "segment_index": 0,
            "segment_step_bound": settings.irc_max_steps,
        },
        "branches": branches,
        "target_minima": target_matches,
    }
    path = root / "irc_verification.json"
    path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return report, path


def _continue_transition_state_irc(
    service: GeometryEvaluationService,
    saddle: OptimizerEvaluation,
    settings: OptimizerSettings,
    root: Path,
    targets: tuple[np.ndarray, ...],
    target_permutations: tuple[tuple[tuple[int, ...], ...], ...],
    masses: np.ndarray,
    mass_sqrt: np.ndarray,
    mass_direction: np.ndarray,
) -> tuple[dict[str, object], Path]:
    """Continue only step-bound IRC branches from protected full-state checkpoints."""

    source = Path(str(settings.irc_continuation_report)).expanduser().resolve()
    previous = json.loads(source.read_text(encoding="utf-8"))
    if not isinstance(previous, Mapping) or previous.get("schema") != IRC_VERIFICATION_SCHEMA:
        raise ValueError("IRC continuation requires a supported verification report")
    if previous.get("verified") is True:
        raise ValueError("a verified IRC has no incomplete branch to continue")
    contract = previous.get("continuation_contract")
    if not isinstance(contract, Mapping) or contract.get("schema") != (
        IRC_CONTINUATION_CONTRACT_SCHEMA
    ):
        raise ValueError("IRC continuation report lacks a full-state contract")
    if tuple(str(atom) for atom in contract.get("atoms", ())) != tuple(service.atoms):
        raise ValueError("IRC continuation atom ordering changed")
    saddle_coordinates = np.asarray(saddle.coordinates_angstrom, dtype=float)
    protected_saddle = np.asarray(contract.get("saddle_coordinates_angstrom", ()), dtype=float)
    if protected_saddle.shape != saddle_coordinates.shape or not np.allclose(
        protected_saddle, saddle_coordinates, rtol=0.0, atol=1.0e-8
    ):
        raise ValueError("IRC continuation saddle geometry changed")
    protected_direction = np.asarray(
        contract.get("exact_negative_mass_direction", ()), dtype=float
    ).reshape(-1)
    if protected_direction.shape != mass_direction.shape:
        raise ValueError("IRC continuation negative-mode dimension changed")
    protected_norm = float(np.linalg.norm(protected_direction))
    if (
        protected_norm <= 1.0e-30
        or abs(float(np.dot(protected_direction / protected_norm, mass_direction))) < 1.0 - 1.0e-8
    ):
        raise ValueError("IRC continuation exact negative mode changed")
    for key, actual in (
        ("irc_step_size", settings.irc_step_size),
        ("irc_gradient_tolerance", settings.irc_gradient_tolerance),
        ("irc_target_rmsd_tolerance", settings.irc_target_rmsd_tolerance),
    ):
        if float(contract.get(key, float("nan"))) != float(actual):
            raise ValueError(f"IRC continuation changed {key}")
    protected_targets = tuple(
        np.asarray(value, dtype=float) for value in contract.get("target_geometries_angstrom", ())
    )
    if len(protected_targets) != len(targets) or any(
        old.shape != new.shape or not np.allclose(old, new, rtol=0.0, atol=1.0e-12)
        for old, new in zip(protected_targets, targets, strict=True)
    ):
        raise ValueError("IRC continuation target minima changed")
    raw_branches = previous.get("branches")
    if not isinstance(raw_branches, list) or len(raw_branches) != 2:
        raise ValueError("IRC continuation requires two prior branches")
    prior_by_direction = {
        str(branch.get("direction")): branch
        for branch in raw_branches
        if isinstance(branch, Mapping)
    }
    if set(prior_by_direction) != {"reverse", "forward"}:
        raise ValueError("IRC continuation branch identities changed")
    raw_target_matches = previous.get("target_minima")
    legacy_assignment = (
        raw_target_matches.get("target_assignment")
        if isinstance(raw_target_matches, Mapping)
        else None
    )
    assigned_targets: dict[str, int | None] = {}
    for branch_index, label in enumerate(("reverse", "forward")):
        branch = prior_by_direction[label]
        raw_assigned = branch.get("assigned_target_index")
        if (
            raw_assigned is None
            and isinstance(legacy_assignment, list)
            and len(legacy_assignment) == 2
        ):
            raw_assigned = legacy_assignment[branch_index]
        assigned_targets[label] = None if raw_assigned is None else int(raw_assigned)
    if targets and set(assigned_targets.values()) != {0, 1}:
        raise ValueError("IRC continuation lacks a distinct branch-to-target assignment")

    def target_rmsds(coordinates: np.ndarray) -> tuple[float, ...]:
        return tuple(
            _minimum_permutation_aligned_rmsd(coordinates, target, permutations)
            for target, permutations in zip(targets, target_permutations, strict=True)
        )

    def evaluate_mass_point(
        mass_coordinates: np.ndarray,
        *,
        tag: str,
    ) -> tuple[OptimizerEvaluation, np.ndarray, np.ndarray]:
        coordinates = _irc_cartesian_coordinates_from_mass_weighted(
            mass_coordinates,
            mass_sqrt,
            saddle_coordinates.shape,
        )
        coordinates = _mass_weighted_kabsch_align(
            coordinates,
            saddle_coordinates,
            masses,
        )
        realized_mass_coordinates = _irc_mass_weighted_cartesian_coordinates(
            coordinates,
            mass_sqrt,
        )
        evaluation = service.evaluate(
            service.actual_q(coordinates),
            tag=tag,
            use_cache=False,
            persist_cache=True,
            requested_properties=("energy", "gradient"),
            realized_coordinates_angstrom=coordinates,
            enforce_gradient_symmetry=False,
        )
        gradient = _irc_mass_weighted_cartesian_gradient(
            evaluation.gradient_hartree_per_bohr,
            mass_sqrt,
        )
        return evaluation, realized_mass_coordinates, gradient

    segment_index = int(contract.get("segment_index", 0)) + 1
    branches: list[dict[str, object]] = []
    endpoint_coordinates: list[np.ndarray] = []
    for label in ("reverse", "forward"):
        prior = prior_by_direction[label]
        assigned_target = assigned_targets[label]
        checkpoint = prior.get("continuation_checkpoint")
        if not isinstance(checkpoint, Mapping) or checkpoint.get("schema") != (
            IRC_BRANCH_CHECKPOINT_SCHEMA
        ):
            raise ValueError(f"IRC {label} branch lacks a full-state checkpoint")
        checkpoint_coordinates = np.asarray(checkpoint.get("coordinates_angstrom", ()), dtype=float)
        if checkpoint_coordinates.shape != saddle_coordinates.shape:
            raise ValueError(f"IRC {label} checkpoint geometry has an invalid shape")
        points = [dict(value) for value in prior.get("points", ())]
        if not points:
            raise ValueError(f"IRC {label} checkpoint lacks path history")
        previous_last_step = int(checkpoint.get("last_step", -1))
        if int(points[-1].get("step", -2)) != previous_last_step:
            raise ValueError(f"IRC {label} checkpoint step index changed")
        if (
            abs(
                float(prior.get("endpoint_energy_hartree", float("nan")))
                - float(checkpoint.get("endpoint_energy_hartree", float("nan")))
            )
            > 1.0e-12
        ):
            raise ValueError(f"IRC {label} checkpoint energy history changed")
        resume_premature_target = False
        if prior.get("converged_minimum") is True:
            termination = str(prior.get("termination", ""))
            if termination == "TARGET_REACHED":
                if not targets or assigned_target is None:
                    raise ValueError(f"IRC {label} carried endpoint lacks its assigned target")
                assigned_rmsd = target_rmsds(checkpoint_coordinates)[assigned_target]
                resume_premature_target = bool(assigned_rmsd > settings.irc_target_rmsd_tolerance)
            elif termination == "MINIMUM_CONVERGED":
                if (
                    float(points[-1].get("gradient_mass_weighted_norm", float("inf")))
                    > settings.irc_gradient_tolerance
                ):
                    raise ValueError(
                        f"IRC {label} carried minimum no longer satisfies its gradient"
                    )
            else:
                raise ValueError(f"IRC {label} has an invalid converged termination")
            if not resume_premature_target:
                carried = dict(prior)
                carried["assigned_target_index"] = assigned_target
                carried["continued_in_segment"] = False
                branches.append(carried)
                endpoint_coordinates.append(checkpoint_coordinates)
                continue
        if not resume_premature_target and prior.get("termination") != "SEGMENT_STEP_BOUND":
            raise ValueError(
                f"IRC {label} stopped by {prior.get('termination')}; "
                "only a step-bound or wrongly target-assigned branch can be continued"
            )
        mass_coordinates = np.asarray(checkpoint.get("mass_coordinates", ()), dtype=float).reshape(
            -1
        )
        stored_mass_gradient = np.asarray(checkpoint.get("mass_gradient", ()), dtype=float).reshape(
            -1
        )
        branch_hessian = np.asarray(checkpoint.get("mass_hessian", ()), dtype=float)
        dimension = saddle_coordinates.size
        if (
            mass_coordinates.shape != (dimension,)
            or stored_mass_gradient.shape != (dimension,)
            or branch_hessian.shape != (dimension, dimension)
            or not np.all(np.isfinite(branch_hessian))
            or not np.allclose(branch_hessian, branch_hessian.T, rtol=0.0, atol=1.0e-10)
        ):
            raise ValueError(f"IRC {label} checkpoint state is invalid")
        evaluation, realized_mass_coordinates, mass_gradient = evaluate_mass_point(
            mass_coordinates,
            tag=f"irc-{label}-continuation-{segment_index:03d}-000",
        )
        if not np.allclose(
            evaluation.coordinates_angstrom,
            checkpoint_coordinates,
            rtol=0.0,
            atol=1.0e-8,
        ) or not np.allclose(
            realized_mass_coordinates,
            mass_coordinates,
            rtol=0.0,
            atol=1.0e-8,
        ):
            raise ValueError(f"IRC {label} checkpoint could not be reproduced")
        if not np.allclose(mass_gradient, stored_mass_gradient, rtol=1.0e-7, atol=1.0e-10):
            raise ValueError(f"IRC {label} checkpoint gradient changed")
        previous_energy = float(checkpoint["endpoint_energy_hartree"])
        if abs(float(evaluation.energy_hartree) - previous_energy) > 1.0e-9:
            raise ValueError(f"IRC {label} checkpoint energy changed")

        cumulative_arc = float(checkpoint["cumulative_mass_weighted_arc"])
        initial_gradient_norm = float(checkpoint["initial_mass_weighted_gradient_norm"])
        peak_gradient_norm = max(
            float(checkpoint["peak_mass_weighted_gradient_norm"]),
            float(np.linalg.norm(mass_gradient)),
        )
        converged = False
        target_reached = False
        termination = "SEGMENT_STEP_BOUND"
        last_accepted_arc = 0.0
        last_correction_error = 0.0
        last_subdivisions = 0
        for additional_step in range(1, settings.irc_max_steps + 1):
            target_rmsd_before = (
                None
                if not targets or assigned_target is None
                else target_rmsds(evaluation.coordinates_angstrom)[assigned_target]
            )
            step_limit = settings.irc_step_size
            if target_rmsd_before is not None:
                step_limit = min(
                    2.0 * settings.irc_step_size,
                    settings.irc_step_size
                    * max(
                        1.0,
                        target_rmsd_before / settings.irc_target_rmsd_tolerance,
                    ),
                )
            accepted = None
            accepted_mass_coordinates = None
            accepted_mass_gradient = None
            accepted_hessian = None
            step_index = previous_last_step + additional_step
            for reduction in range(7):
                trial_arc = step_limit * (0.5**reduction)
                predictor_mass_coordinates, predictor_subdivisions = _irc_local_quadratic_predictor(
                    realized_mass_coordinates,
                    mass_gradient,
                    branch_hessian,
                    trial_arc,
                )
                try:
                    predictor, predictor_mass_coordinates, predictor_gradient = evaluate_mass_point(
                        predictor_mass_coordinates,
                        tag=(
                            f"irc-{label}-{step_index:03d}-"
                            f"continuation-{segment_index:03d}-pc{reduction}-predictor"
                        ),
                    )
                except RuntimeError:
                    continue
                predictor_hessian, _predictor_update = _bofill_update(
                    branch_hessian,
                    predictor_mass_coordinates - realized_mass_coordinates,
                    predictor_gradient - mass_gradient,
                )
                corrected, correction_error, corrector_subdivisions = _irc_dwi_corrector(
                    realized_mass_coordinates,
                    evaluation.energy_hartree,
                    mass_gradient,
                    branch_hessian,
                    predictor_mass_coordinates,
                    predictor.energy_hartree,
                    predictor_gradient,
                    predictor_hessian,
                    trial_arc,
                )
                try:
                    candidate, candidate_coordinates, candidate_gradient = evaluate_mass_point(
                        corrected,
                        tag=(
                            f"irc-{label}-{step_index:03d}-"
                            f"continuation-{segment_index:03d}-pc{reduction}-corrected"
                        ),
                    )
                except RuntimeError:
                    continue
                if candidate.energy_hartree >= evaluation.energy_hartree - 1.0e-14:
                    continue
                candidate_hessian, _accepted_update = _bofill_update(
                    branch_hessian,
                    candidate_coordinates - realized_mass_coordinates,
                    candidate_gradient - mass_gradient,
                )
                accepted = candidate
                accepted_mass_coordinates = candidate_coordinates
                accepted_mass_gradient = candidate_gradient
                accepted_hessian = candidate_hessian
                last_accepted_arc = trial_arc
                last_correction_error = correction_error
                last_subdivisions = max(predictor_subdivisions, corrector_subdivisions)
                break
            if (
                accepted is None
                or accepted_mass_coordinates is None
                or accepted_mass_gradient is None
                or accepted_hessian is None
            ):
                termination = "STEP_FAILURE"
                break
            evaluation = accepted
            realized_mass_coordinates = accepted_mass_coordinates
            mass_gradient = accepted_mass_gradient
            branch_hessian = accepted_hessian
            cumulative_arc += last_accepted_arc
            cartesian_gradient = evaluation.gradient_hartree_per_bohr
            gradient_inf_norm = (
                0.0 if cartesian_gradient is None else float(np.max(np.abs(cartesian_gradient)))
            )
            mass_gradient_norm = float(np.linalg.norm(mass_gradient))
            peak_gradient_norm = max(peak_gradient_norm, mass_gradient_norm)
            target_rmsd = (
                None
                if not targets or assigned_target is None
                else target_rmsds(evaluation.coordinates_angstrom)[assigned_target]
            )
            points.append(
                {
                    "step": step_index,
                    "q": np.asarray(evaluation.q, dtype=float).tolist(),
                    "energy_hartree": evaluation.energy_hartree,
                    "gradient_inf_norm": gradient_inf_norm,
                    "gradient_mass_weighted_norm": mass_gradient_norm,
                    "target_rmsd_angstrom": target_rmsd,
                    "target_rmsds_angstrom": (
                        [] if not targets else list(target_rmsds(evaluation.coordinates_angstrom))
                    ),
                    "assigned_target_index": assigned_target,
                    "cumulative_mass_weighted_arc": cumulative_arc,
                    "accepted_mass_weighted_arc": last_accepted_arc,
                    "corrector_error": last_correction_error,
                    "corrector_subdivisions": last_subdivisions,
                    "continuation_segment": segment_index,
                }
            )
            if target_rmsd is not None and target_rmsd <= settings.irc_target_rmsd_tolerance:
                converged = True
                target_reached = True
                termination = "TARGET_REACHED"
                break
            if _irc_minimum_convergence_ready(
                gradient_norm=mass_gradient_norm,
                peak_gradient_norm=peak_gradient_norm,
                initial_gradient_norm=initial_gradient_norm,
                cumulative_arc=cumulative_arc,
                nominal_step=settings.irc_step_size,
                tolerance=settings.irc_gradient_tolerance,
            ):
                converged = True
                termination = "MINIMUM_CONVERGED"
                break
        endpoint = np.asarray(evaluation.coordinates_angstrom, dtype=float)
        endpoint_coordinates.append(endpoint)
        branches.append(
            {
                "direction": label,
                "converged_minimum": converged,
                "target_reached": target_reached,
                "assigned_target_index": assigned_target,
                "termination": termination,
                "initial_energy_below_saddle": bool(
                    prior.get("initial_energy_below_saddle", False)
                ),
                "endpoint_energy_hartree": evaluation.energy_hartree,
                "endpoint_q": np.asarray(evaluation.q, dtype=float).tolist(),
                "cumulative_mass_weighted_arc": cumulative_arc,
                "peak_mass_weighted_gradient_norm": peak_gradient_norm,
                "continued_in_segment": True,
                "continuation_checkpoint": {
                    "schema": IRC_BRANCH_CHECKPOINT_SCHEMA,
                    "coordinates_angstrom": endpoint.tolist(),
                    "mass_coordinates": np.asarray(realized_mass_coordinates, dtype=float).tolist(),
                    "mass_gradient": np.asarray(mass_gradient, dtype=float).tolist(),
                    "mass_hessian": np.asarray(branch_hessian, dtype=float).tolist(),
                    "initial_mass_weighted_gradient_norm": initial_gradient_norm,
                    "peak_mass_weighted_gradient_norm": peak_gradient_norm,
                    "cumulative_mass_weighted_arc": cumulative_arc,
                    "last_step": int(points[-1]["step"]),
                    "endpoint_energy_hartree": evaluation.energy_hartree,
                },
                "points": points,
            }
        )

    endpoint_separation_rmsd = _aligned_rmsd(endpoint_coordinates[0], endpoint_coordinates[1])
    separated = bool(endpoint_separation_rmsd > 1.0e-3)
    target_matches: dict[str, object] = {}
    target_ok = True
    if targets:
        rmsds, assignment = _irc_distinct_target_assignment(
            tuple(endpoint_coordinates),
            targets,
            target_permutations,
        )
        target_ok = all(value <= settings.irc_target_rmsd_tolerance for value in rmsds)
        target_matches = {
            "verified": target_ok,
            "rmsd_angstrom": list(rmsds),
            "target_assignment": list(assignment),
            "threshold_angstrom": settings.irc_target_rmsd_tolerance,
            "atom_mapping": "ORACLE_TARGET_TOPOLOGY_AUTOMORPHISMS",
        }
    verified = bool(
        separated
        and all(bool(branch["converged_minimum"]) for branch in branches)
        and all(bool(branch["initial_energy_below_saddle"]) for branch in branches)
        and target_ok
    )
    report: dict[str, object] = {
        "schema": IRC_VERIFICATION_SCHEMA,
        "verified": verified,
        "endpoints_distinct": separated,
        "endpoint_separation_rmsd_angstrom": endpoint_separation_rmsd,
        "symmetry_contract": "SADDLE_GROUP_RELEASED_ALONG_EXACT_NEGATIVE_MODE",
        "path_metric": "MASS_WEIGHTED_CARTESIAN",
        "integrator": "EULER_PREDICTOR_CORRECTOR_DWI_BOFILL",
        "saddle_coordinate_model": "SONIC",
        "continued_from": str(source),
        "continuation_contract": {
            "schema": IRC_CONTINUATION_CONTRACT_SCHEMA,
            "atoms": list(service.atoms),
            "saddle_coordinates_angstrom": saddle_coordinates.tolist(),
            "exact_negative_mass_direction": mass_direction.tolist(),
            "irc_step_size": settings.irc_step_size,
            "irc_gradient_tolerance": settings.irc_gradient_tolerance,
            "irc_target_rmsd_tolerance": settings.irc_target_rmsd_tolerance,
            "target_geometries_angstrom": [target.tolist() for target in targets],
            "segment_index": segment_index,
            "segment_step_bound": settings.irc_max_steps,
        },
        "branches": branches,
        "target_minima": target_matches,
    }
    path = root / "irc_verification.json"
    path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return report, path


def _irc_mass_weighted_cartesian_coordinates(
    coordinates_angstrom: np.ndarray,
    mass_sqrt: np.ndarray,
) -> np.ndarray:
    coordinates = np.asarray(coordinates_angstrom, dtype=float).reshape(-1)
    return coordinates * ANGSTROM_TO_BOHR * np.asarray(mass_sqrt, dtype=float)


def _irc_cartesian_coordinates_from_mass_weighted(
    mass_coordinates: np.ndarray,
    mass_sqrt: np.ndarray,
    shape: tuple[int, ...],
) -> np.ndarray:
    coordinates_bohr = np.asarray(mass_coordinates, dtype=float) / np.asarray(
        mass_sqrt,
        dtype=float,
    )
    return (coordinates_bohr / ANGSTROM_TO_BOHR).reshape(shape)


def _irc_mass_weighted_cartesian_gradient(
    gradient_hartree_per_bohr: np.ndarray | None,
    mass_sqrt: np.ndarray,
) -> np.ndarray:
    if gradient_hartree_per_bohr is None:
        raise RuntimeError("predictor-corrector IRC requires analytic Cartesian gradients")
    return np.asarray(gradient_hartree_per_bohr, dtype=float).reshape(-1) / np.asarray(
        mass_sqrt,
        dtype=float,
    )


def _irc_mass_weighted_cartesian_hessian(
    hessian_hartree_per_bohr2: np.ndarray,
    mass_sqrt: np.ndarray,
) -> np.ndarray:
    weights = 1.0 / np.asarray(mass_sqrt, dtype=float)
    hessian = np.asarray(hessian_hartree_per_bohr2, dtype=float)
    expected = weights.size
    if hessian.shape != (expected, expected):
        raise ValueError("Cartesian IRC Hessian has an invalid shape")
    weighted = hessian * weights[:, None] * weights[None, :]
    return 0.5 * (weighted + weighted.T)


def _mass_weighted_kabsch_align(
    moving: np.ndarray,
    reference: np.ndarray,
    masses: np.ndarray,
) -> np.ndarray:
    """Remove overall translation and rotation without changing the structure."""

    left = np.asarray(moving, dtype=float)
    right = np.asarray(reference, dtype=float)
    weights = np.asarray(masses, dtype=float).reshape(-1)
    if left.shape != right.shape or left.shape != (weights.size, 3):
        raise ValueError("mass-weighted alignment inputs are incompatible")
    left_center = np.average(left, axis=0, weights=weights)
    right_center = np.average(right, axis=0, weights=weights)
    left_shifted = left - left_center
    right_shifted = right - right_center
    covariance = (left_shifted * weights[:, None]).T @ right_shifted
    u_matrix, _singular, vh = np.linalg.svd(covariance)
    correction = np.eye(3)
    if np.linalg.det(u_matrix @ vh) < 0.0:
        correction[-1, -1] = -1.0
    rotation = u_matrix @ correction @ vh
    return left_shifted @ rotation + right_center


def _irc_stable_subdivision_count(
    step_length: float,
    gradient: np.ndarray,
    hessian: np.ndarray,
    *,
    minimum: int = 32,
    maximum: int = 8192,
) -> int:
    """Choose an Euler microstep below the local stiffness scale."""

    gradient_norm = max(float(np.linalg.norm(gradient)), 1.0e-14)
    spectral_norm = float(np.linalg.norm(hessian, ord=2))
    required = max(minimum, int(math.ceil(4.0 * step_length * spectral_norm / gradient_norm)))
    subdivisions = 1 << int(math.ceil(math.log2(max(required, 1))))
    return int(min(maximum, subdivisions))


def _irc_integrate_normalized_gradient(
    initial: np.ndarray,
    step_length: float,
    subdivisions: int,
    gradient_function,
) -> np.ndarray:
    coordinates = np.asarray(initial, dtype=float).copy()
    microstep = float(step_length) / int(subdivisions)
    for _index in range(int(subdivisions)):
        gradient = np.asarray(gradient_function(coordinates), dtype=float).reshape(-1)
        norm = float(np.linalg.norm(gradient))
        if not np.isfinite(norm) or norm <= 1.0e-30:
            break
        coordinates -= microstep * gradient / norm
    return coordinates


def _irc_local_quadratic_predictor(
    coordinates: np.ndarray,
    gradient: np.ndarray,
    hessian: np.ndarray,
    step_length: float,
) -> tuple[np.ndarray, int]:
    """Integrate the local quadratic surface with stiffness-safe microsteps."""

    origin = np.asarray(coordinates, dtype=float)
    base_gradient = np.asarray(gradient, dtype=float)
    model_hessian = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    subdivisions = _irc_stable_subdivision_count(
        step_length,
        base_gradient,
        model_hessian,
    )

    def local_gradient(at: np.ndarray) -> np.ndarray:
        return base_gradient + model_hessian @ (np.asarray(at, dtype=float) - origin)

    predicted = _irc_integrate_normalized_gradient(
        origin,
        step_length,
        subdivisions,
        local_gradient,
    )
    return predicted, subdivisions


def _irc_dwi_gradient(
    coordinates: np.ndarray,
    first_coordinates: np.ndarray,
    first_energy: float,
    first_gradient: np.ndarray,
    first_hessian: np.ndarray,
    second_coordinates: np.ndarray,
    second_energy: float,
    second_gradient: np.ndarray,
    second_hessian: np.ndarray,
) -> np.ndarray:
    """Gradient of the two-anchor fourth-power distance-weighted surface."""

    at = np.asarray(coordinates, dtype=float)
    first_delta = at - np.asarray(first_coordinates, dtype=float)
    second_delta = at - np.asarray(second_coordinates, dtype=float)
    first_distance = float(np.linalg.norm(first_delta))
    second_distance = float(np.linalg.norm(second_delta))
    if first_distance <= 1.0e-14:
        return np.asarray(first_gradient, dtype=float).copy()
    if second_distance <= 1.0e-14:
        return np.asarray(second_gradient, dtype=float).copy()
    first_power = first_distance**4
    second_power = second_distance**4
    denominator = first_power + second_power
    first_weight = second_power / denominator
    second_weight = first_power / denominator
    first_taylor = (
        float(first_energy)
        + first_delta @ first_gradient
        + 0.5 * first_delta @ first_hessian @ first_delta
    )
    second_taylor = (
        float(second_energy)
        + second_delta @ second_gradient
        + 0.5 * second_delta @ second_hessian @ second_delta
    )
    first_taylor_gradient = first_gradient + first_hessian @ first_delta
    second_taylor_gradient = second_gradient + second_hessian @ second_delta
    first_power_gradient = 4.0 * first_distance**2 * first_delta
    second_power_gradient = 4.0 * second_distance**2 * second_delta
    first_weight_gradient = (
        second_power_gradient * first_power - first_power_gradient * second_power
    ) / denominator**2
    return (
        first_weight_gradient * (first_taylor - second_taylor)
        + first_weight * first_taylor_gradient
        + second_weight * second_taylor_gradient
    )


def _irc_dwi_corrector(
    first_coordinates: np.ndarray,
    first_energy: float,
    first_gradient: np.ndarray,
    first_hessian: np.ndarray,
    second_coordinates: np.ndarray,
    second_energy: float,
    second_gradient: np.ndarray,
    second_hessian: np.ndarray,
    step_length: float,
) -> tuple[np.ndarray, float, int]:
    """Correct one IRC predictor on a local distance-weighted surface."""

    subdivisions = max(
        _irc_stable_subdivision_count(
            step_length,
            first_gradient,
            first_hessian,
        ),
        _irc_stable_subdivision_count(
            step_length,
            second_gradient,
            second_hessian,
        ),
    )

    def interpolated_gradient(at: np.ndarray) -> np.ndarray:
        return _irc_dwi_gradient(
            at,
            first_coordinates,
            first_energy,
            first_gradient,
            first_hessian,
            second_coordinates,
            second_energy,
            second_gradient,
            second_hessian,
        )

    coarse = _irc_integrate_normalized_gradient(
        first_coordinates,
        step_length,
        subdivisions,
        interpolated_gradient,
    )
    fine_subdivisions = min(8192, 2 * subdivisions)
    fine = _irc_integrate_normalized_gradient(
        first_coordinates,
        step_length,
        fine_subdivisions,
        interpolated_gradient,
    )
    error = float(np.linalg.norm(fine - coarse))
    return fine, error, fine_subdivisions


def _irc_minimum_convergence_ready(
    *,
    gradient_norm: float,
    peak_gradient_norm: float,
    initial_gradient_norm: float,
    cumulative_arc: float,
    nominal_step: float,
    tolerance: float,
) -> bool:
    """Reject the formally small gradient in the immediate saddle region."""

    left_saddle_region = peak_gradient_norm >= max(
        3.0 * tolerance,
        3.0 * initial_gradient_norm,
    )
    return bool(
        left_saddle_region and cumulative_arc >= 4.0 * nominal_step and gradient_norm <= tolerance
    )


def _irc_target_topology_permutations(
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
) -> tuple[tuple[int, ...], ...]:
    """Return ORACLE graph automorphisms admitted by one declared minimum."""

    from matrix_chem import geometry_labelled_graph_automorphisms

    return geometry_labelled_graph_automorphisms(
        atoms,
        coordinates_angstrom,
    )


def _irc_distinct_target_assignment(
    branch_coordinates: Sequence[np.ndarray],
    targets: Sequence[np.ndarray],
    target_permutations: Sequence[Sequence[Sequence[int]]],
) -> tuple[tuple[float, float], tuple[int, int]]:
    """Assign two IRC branches bijectively to two declared target minima."""

    if len(branch_coordinates) != 2 or len(targets) != 2 or len(target_permutations) != 2:
        raise ValueError("distinct IRC target assignment requires two branches and two minima")
    scores: list[tuple[float, tuple[float, float], tuple[int, int]]] = []
    for assignment in ((0, 1), (1, 0)):
        rmsds = tuple(
            _minimum_permutation_aligned_rmsd(
                np.asarray(branch_coordinates[branch_index], dtype=float),
                np.asarray(targets[target_index], dtype=float),
                target_permutations[target_index],
            )
            for branch_index, target_index in enumerate(assignment)
        )
        scores.append((sum(rmsds), (rmsds[0], rmsds[1]), assignment))
    _score, rmsds, assignment = min(scores, key=lambda item: item[0])
    return rmsds, assignment


def _minimum_permutation_aligned_rmsd(
    moving: np.ndarray,
    reference: np.ndarray,
    permutations: Sequence[Sequence[int]],
) -> float:
    """Return the best rigid RMSD over declared topology automorphisms."""

    coordinates = np.asarray(moving, dtype=float)
    target = np.asarray(reference, dtype=float)
    if coordinates.shape != target.shape:
        raise ValueError("permutation RMSD geometries have incompatible shapes")
    values = []
    for permutation in permutations:
        mapping = np.asarray(permutation, dtype=int)
        if mapping.shape != (len(coordinates),) or tuple(sorted(mapping.tolist())) != tuple(
            range(len(coordinates))
        ):
            raise ValueError("target topology automorphism is not a complete permutation")
        values.append(_aligned_rmsd(coordinates[mapping], target))
    if not values:
        raise ValueError("target topology has no identity automorphism")
    return float(min(values))


def _release_irc_gradient_symmetry(
    result: PointEvaluationResult,
) -> PointEvaluationResult:
    """Mark an unprojected gradient used after leaving a symmetric saddle."""

    return replace(
        result,
        execution={
            **dict(result.execution),
            "gradient_symmetry_contract": "released_for_irc_descent",
        },
    )


def _normalized_irc_descent(
    gradient: np.ndarray,
    *,
    metric: np.ndarray,
    step_limit: float,
    settings: OptimizerSettings,
) -> np.ndarray | None:
    """Return a coordinate-invariant mass-weighted IRC tangent."""

    covector = np.asarray(gradient, dtype=float).reshape(-1)
    if covector.size == 0 or float(np.max(np.abs(covector))) <= 1.0e-30:
        return None
    metric_matrix = _positive_metric_matrix(
        np.asarray(metric, dtype=float),
        settings.min_abs_metric_diagonal,
    )
    descent = -np.linalg.solve(metric_matrix, covector)
    arc_norm = float(np.sqrt(descent @ metric_matrix @ descent))
    if not np.isfinite(arc_norm) or arc_norm <= 1.0e-30:
        return None
    # The gradient is a covector.  Raising its index with the mass-weighted
    # Wilson metric makes the path invariant under any nonsingular linear
    # reparameterization of the same SONIC tangent space.
    return descent * (float(step_limit) / arc_norm)


def _irc_gradient_norm(
    gradient: np.ndarray,
    *,
    metric: np.ndarray,
    settings: OptimizerSettings,
) -> float:
    """Return the invariant norm of an IRC energy-gradient covector."""

    covector = np.asarray(gradient, dtype=float).reshape(-1)
    if covector.size == 0:
        return 0.0
    metric_matrix = _positive_metric_matrix(
        np.asarray(metric, dtype=float),
        settings.min_abs_metric_diagonal,
    )
    raised = np.linalg.solve(metric_matrix, covector)
    value = float(covector @ raised)
    return float(np.sqrt(max(value, 0.0)))


def _irc_mass_weighted_optimizer_metric(
    service: GeometryEvaluationService,
    coordinates_angstrom: np.ndarray,
    settings: OptimizerSettings,
) -> np.ndarray:
    """Return ``(dx/dq)^T M (dx/dq)`` in bohr and atomic-mass units."""

    from matrix_chem import atomic_mass
    from matrix_chem.topology.elements import atomic_number

    masses = np.asarray(
        [atomic_mass(int(atomic_number(atom) or 0)) for atom in service.atoms],
        dtype=float,
    )
    if np.any(~np.isfinite(masses)) or np.any(masses <= 0.0):
        raise ValueError("IRC mass metric requires positive finite atomic masses")
    directions = (
        np.asarray(service.coordinate_directions(coordinates_angstrom), dtype=float)
        * ANGSTROM_TO_BOHR
    )
    mass_cartesian = np.repeat(masses, 3)
    metric = (directions * mass_cartesian[None, :]) @ directions.T
    return _positive_metric_matrix(metric, settings.min_abs_metric_diagonal)


def _aligned_rmsd(moving: np.ndarray, reference: np.ndarray) -> float:
    from matrix_chem.geometry_alignment import kabsch_rotation

    left = np.asarray(moving, dtype=float)
    right = np.asarray(reference, dtype=float)
    if left.shape != right.shape:
        raise ValueError("IRC endpoint and target geometries must have matching shapes")
    left_centered = left - np.mean(left, axis=0)
    right_centered = right - np.mean(right, axis=0)
    rotation = kabsch_rotation(left_centered, right_centered)
    return float(np.sqrt(np.mean((left_centered @ rotation - right_centered) ** 2)))


def _optimizer_diagnostics(iterations: Sequence[OptimizerIteration]) -> dict[str, object]:
    records = tuple(iterations)
    accepted = sum(1 for item in records if item.status.startswith("accepted"))
    rejected_trials = sum(item.rejected_trial_count for item in records)
    trust_limited = sum(1 for item in records if "trust_limited" in item.step_policy)
    component_limited = sum(1 for item in records if "component_limited" in item.step_policy)
    hessian_updates: dict[str, int] = {}
    for item in records:
        hessian_updates[item.hessian_update_status] = (
            hessian_updates.get(item.hessian_update_status, 0) + 1
        )
    return {
        "accepted_macro_steps": accepted,
        "rejected_trial_count": rejected_trials,
        "trust_limited_steps": trust_limited,
        "component_limited_steps": component_limited,
        "hessian_update_status_counts": hessian_updates,
    }


def read_optimizer_hessian(
    path: Path | str,
    *,
    expected_labels: Sequence[str] | None = None,
) -> np.ndarray:
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    schema = payload.get("schema")
    if schema != OPTIMIZER_HESSIAN_SCHEMA:
        raise ValueError(f"unsupported optimizer Hessian schema: {schema}")
    labels = tuple(str(item) for item in payload.get("labels", ()))
    if (
        expected_labels is not None
        and labels
        and labels != tuple(str(item) for item in expected_labels)
    ):
        raise ValueError("optimizer Hessian labels do not match the active coordinate model")
    matrix = np.asarray(payload["hessian"], dtype=float)
    if matrix.ndim != 2 or matrix.shape[0] != matrix.shape[1]:
        raise ValueError("optimizer Hessian must be a square matrix")
    if labels and matrix.shape != (len(labels), len(labels)):
        raise ValueError("optimizer Hessian shape does not match stored labels")
    if not np.all(np.isfinite(matrix)):
        raise ValueError("optimizer Hessian contains non-finite values")
    return 0.5 * (matrix + matrix.T)


def read_cartesian_gradient(path: Path | str) -> np.ndarray:
    """Read a Cartesian gradient vector in hartree/bohr for a B-prime transform."""

    target = Path(path)
    if target.suffix.casefold() == ".npy":
        values = np.load(target)
    elif target.suffix.casefold() == ".json":
        payload = json.loads(target.read_text(encoding="utf-8"))
        if isinstance(payload, dict):
            for key in (
                "cartesian_gradient_hartree_per_bohr",
                "gradient_hartree_per_bohr",
                "gradient",
            ):
                if key in payload:
                    payload = payload[key]
                    break
            else:
                raise ValueError("Cartesian-gradient JSON contains no supported gradient key")
        values = np.asarray(payload, dtype=float)
    else:
        values = np.loadtxt(target, dtype=float)
    gradient = np.asarray(values, dtype=float).reshape(-1)
    if gradient.size == 0 or not np.all(np.isfinite(gradient)):
        raise ValueError("Cartesian gradient must be a non-empty finite vector")
    return gradient


def write_optimizer_hessian(
    path: Path | str,
    hessian: np.ndarray,
    model: OptimizerCoordinateModel,
    *,
    source: str,
    q: Sequence[float] | np.ndarray | None = None,
    coordinates_angstrom: np.ndarray | None = None,
) -> Path:
    target = Path(path)
    matrix = _validate_optimizer_hessian(hessian, len(model.labels))
    payload: dict[str, object] = {
        "schema": OPTIMIZER_HESSIAN_SCHEMA,
        "coordinate_kind": model.kind,
        "labels": list(model.labels),
        "source": str(source),
        "units": "hartree per optimizer-coordinate squared",
        "hessian": matrix.tolist(),
    }
    if q is not None:
        payload["q"] = np.asarray(q, dtype=float).reshape(-1).tolist()
    payload["reference_coordinate_directions_angstrom"] = model.directions_angstrom.tolist()
    if coordinates_angstrom is not None:
        geometry = np.asarray(coordinates_angstrom, dtype=float)
        if geometry.shape != (model.directions_angstrom.shape[1] // 3, 3) or not np.all(np.isfinite(geometry)):
            raise ValueError("optimizer Hessian checkpoint geometry has invalid shape or values")
        payload["coordinates_angstrom"] = geometry.tolist()
    target.parent.mkdir(parents=True, exist_ok=True)
    _atomic_json_write(target, payload)
    return target


def optimizer_hessian_from_cartesian(
    cartesian_hessian_hartree_per_bohr2: np.ndarray,
    model: OptimizerCoordinateModel,
    *,
    cartesian_gradient_hartree_per_bohr: np.ndarray | None = None,
    coordinates_angstrom: np.ndarray | None = None,
    b_prime_parallel_workers: int = 0,
) -> np.ndarray:
    """Transform a Cartesian Hessian into optimizer coordinates.

    External initial guesses use the linear congruence by default. Passing a
    Cartesian gradient explicitly requests the more expensive exact
    curvilinear transformation with ARCHITECT's B-prime tensor; this is
    diagnostic-only for a seed and mandatory for a physical final Hessian.
    """

    cart = np.asarray(cartesian_hessian_hartree_per_bohr2, dtype=float)
    ncart = model.directions_angstrom.shape[1]
    if cart.shape != (ncart, ncart):
        raise ValueError(f"Cartesian Hessian shape must be {(ncart, ncart)}, got {cart.shape}")
    directions_bohr = np.asarray(model.directions_angstrom, dtype=float) * ANGSTROM_TO_BOHR
    if (
        coordinates_angstrom is not None
        and model.kind == "sonic"
        and model.sonic_definition is not None
    ):
        directions_bohr = _optimizer_directions_at_geometry(
            model,
            model.sonic_definition,
            np.asarray(coordinates_angstrom, dtype=float),
        )
    if cartesian_gradient_hartree_per_bohr is not None:
        if model.kind != "sonic" or model.sonic_definition is None:
            raise ValueError("B-prime Hessian transformation requires a frozen SONIC model")
        from matrix_zaff import curvilinear_internal_hessian_from_cartesian

        definition = model.sonic_definition
        definition_labels = tuple(gic.identifier for gic in definition.gics)
        definition_names = tuple(gic.name for gic in definition.gics)
        source_labels = tuple(model.sonic_labels or model.labels)
        coordinate_indices = tuple(
            _coordinate_index(label, definition_labels, definition_names) for label in source_labels
        )
        result = curvilinear_internal_hessian_from_cartesian(
            definition,
            cart,
            cartesian_gradient_hartree_per_bohr,
            coordinates_angstrom=coordinates_angstrom,
            cartesian_from_internal_bohr=directions_bohr.T,
            coordinate_indices=coordinate_indices,
            parallel_workers=b_prime_parallel_workers,
        )
        return _validate_optimizer_hessian(result.hessian_internal, len(model.labels))
    projected = directions_bohr @ (0.5 * (cart + cart.T)) @ directions_bohr.T
    return _validate_optimizer_hessian(projected, len(model.labels))


def _initial_qm_b_prime_correction(
    model: OptimizerCoordinateModel,
    coordinates_angstrom: np.ndarray,
    cartesian_gradient_hartree_per_bohr: np.ndarray | None,
    *,
    optimizer_gradient: np.ndarray | None = None,
    workers: int = 0,
) -> np.ndarray | None:
    """Return the exact geometric-curvature correction for a QM seed.

    The Cartesian Hessian is first imported by linear congruence.  Once LINK
    has evaluated the initial gradient, ARCHITECT adds the exact ``B'`` term
    without another QM call.  Analytic Cartesian gradients are used directly;
    for an energy-only surface the initial SONIC finite-difference gradient is
    lifted to the unique minimum-norm Cartesian tangent covector.
    """

    if model.kind != "sonic" or model.sonic_definition is None:
        return None
    gradient = cartesian_gradient_hartree_per_bohr
    if gradient is None:
        if optimizer_gradient is None:
            return None
        directions_bohr = _optimizer_directions_at_geometry(
            model,
            model.sonic_definition,
            np.asarray(coordinates_angstrom, dtype=float),
        )
        internal = np.asarray(optimizer_gradient, dtype=float).reshape(-1)
        if internal.shape != (directions_bohr.shape[0],):
            raise ValueError("initial optimizer gradient does not match the SONIC model")
        metric = _positive_metric_matrix(
            directions_bohr @ directions_bohr.T,
            1.0e-12,
        )
        gradient = directions_bohr.T @ np.linalg.solve(metric, internal)
    ncart = int(np.asarray(model.directions_angstrom, dtype=float).shape[1])
    return optimizer_hessian_from_cartesian(
        np.zeros((ncart, ncart), dtype=float),
        model,
        cartesian_gradient_hartree_per_bohr=np.asarray(gradient, dtype=float),
        coordinates_angstrom=np.asarray(coordinates_angstrom, dtype=float),
        b_prime_parallel_workers=workers,
    )


def optimizer_hessian_from_force_field_cartesian(
    cartesian_hessian_hartree_per_bohr2: np.ndarray,
    model: OptimizerCoordinateModel,
    *,
    xyzin_path: Path | str,
    coordinates_angstrom: np.ndarray | None = None,
    fragment_context: str | None = None,
) -> np.ndarray:
    """Project an FF Hessian through a full pseudo-bond SONIC source basis.

    Force-field Hessians have one immutable source-coordinate contract:
    intermolecular connectivity is represented by SMITH pseudo-bonds even
    when the subsequent optimization uses exponential mappings.  The source
    Hessian is reconstructed in its physical Cartesian tangent space and only
    then transformed to the active optimizer SONIC.  QM Hessians must use
    :func:`optimizer_hessian_from_cartesian` directly instead.
    """

    if model.kind == "typed_onic":
        runtime = model.typed_onic_runtime
        if runtime is None:
            raise ValueError("typed-ONIC force-field Hessians require a compiled runtime")
        geometry = np.asarray(
            runtime.definition.reference_coordinates_angstrom
            if coordinates_angstrom is None
            else coordinates_angstrom,
            dtype=float,
        )
        target_directions_bohr = _typed_onic_directions_at_geometry(
            runtime,
            geometry,
        )
        target_definition = None
    elif model.kind == "sonic" and model.sonic_definition is not None:
        target_definition = model.sonic_definition
        geometry = (
            np.asarray(target_definition.reference_coordinates_angstrom, dtype=float)
            if coordinates_angstrom is None
            else np.asarray(coordinates_angstrom, dtype=float)
        )
        target_directions_bohr = _optimizer_directions_at_geometry(
            model, target_definition, geometry
        )
    else:
        raise ValueError(
            "force-field Hessians require a frozen SONIC or typed-ONIC optimizer model"
        )
    from matrix_chem import (
        ATLAS_TASK_TRANSITION_STATE,
        read_oracle_coordinate_atlas_contract,
    )
    from matrix_smith import build_gic_b_matrix, build_gic_definition_from_xyzin

    if model.kind == "typed_onic" and coordinates_angstrom is None:
        geometry = np.asarray(
            model.typed_onic_runtime.definition.reference_coordinates_angstrom, dtype=float
        )
    symmetry_group = (
        str(target_definition.point_group)
        if target_definition is not None
        else next(
            (
                str(block.exact_retained_group)
                for block in model.typed_onic_runtime.definition.blocks
                if str(block.exact_retained_group).strip()
            ),
            "C1",
        )
    )
    source_context = str(fragment_context or "").strip().lower().replace("-", "_")
    if not source_context:
        atlas = read_oracle_coordinate_atlas_contract(Path(xyzin_path))
        source_context = (
            "transition_state"
            if atlas.task_regime == ATLAS_TASK_TRANSITION_STATE
            else "optimization"
        )
    source_definition = build_gic_definition_from_xyzin(
        Path(xyzin_path),
        symmetrize=bool(symmetry_group.upper() not in {"", "C1", "UNKNOWN"}),
        symmetry_group=symmetry_group,
        fragment_context=source_context,
    )
    source_b_angstrom = np.asarray(
        build_gic_b_matrix(
            source_definition,
            coordinates_angstrom=geometry,
        ).rows,
        dtype=float,
    )
    source_rank = int(np.linalg.matrix_rank(source_b_angstrom, tol=1.0e-9))
    if source_rank != int(source_definition.target_rank):
        raise ValueError(
            "ORACLE-atlas source SONIC is rank deficient: "
            f"rank {source_rank}, target {source_definition.target_rank}"
        )
    source_cartesian_from_internal_bohr = (
        cartesian_from_internal_jacobian(source_b_angstrom, rcond=1.0e-8) * ANGSTROM_TO_BOHR
    )
    return _project_cartesian_hessian_through_internal_source(
        cartesian_hessian_hartree_per_bohr2,
        source_cartesian_from_internal_bohr,
        target_directions_bohr,
    )


def _project_cartesian_hessian_through_internal_source(
    cartesian_hessian_hartree_per_bohr2: np.ndarray,
    source_cartesian_from_internal_bohr: np.ndarray,
    target_directions_bohr: np.ndarray,
) -> np.ndarray:
    """Apply the source-internal/tangent/target congruence without B-prime."""

    cartesian = np.asarray(cartesian_hessian_hartree_per_bohr2, dtype=float)
    source_j = np.asarray(source_cartesian_from_internal_bohr, dtype=float)
    target_j_rows = np.asarray(target_directions_bohr, dtype=float)
    if source_j.ndim != 2 or target_j_rows.ndim != 2:
        raise ValueError("source and target Hessian Jacobians must be two-dimensional")
    ncart = source_j.shape[0]
    if cartesian.shape != (ncart, ncart) or target_j_rows.shape[1] != ncart:
        raise ValueError("Cartesian Hessian and source/target Jacobian dimensions differ")
    if not all(np.all(np.isfinite(item)) for item in (cartesian, source_j, target_j_rows)):
        raise ValueError("Hessian source transformation contains non-finite values")
    cartesian = 0.5 * (cartesian + cartesian.T)
    source_hessian = source_j.T @ cartesian @ source_j
    source_b_bohr = internal_from_cartesian_jacobian(source_j, rcond=1.0e-8)
    source_tangent_cartesian = source_b_bohr.T @ source_hessian @ source_b_bohr
    target = target_j_rows @ source_tangent_cartesian @ target_j_rows.T
    return _validate_optimizer_hessian(target, target_j_rows.shape[0])


def _typed_onic_directions_at_geometry(
    runtime: object, coordinates_angstrom: np.ndarray
) -> np.ndarray:
    """Return typed-ONIC Cartesian tangent rows in bohr at one geometry."""

    evaluation = runtime.evaluate(np.asarray(coordinates_angstrom, dtype=float))
    cartesian_from_q = cartesian_from_internal_jacobian(
        evaluation.b_matrix.to_dense(),
        rcond=1.0e-8,
    )
    return np.asarray(cartesian_from_q.T, dtype=float) * ANGSTROM_TO_BOHR


def _optimizer_directions_at_geometry(
    model: OptimizerCoordinateModel,
    definition: object,
    coordinates_angstrom: np.ndarray,
) -> np.ndarray:
    """Return ``dx/dq`` rows at the imported-Hessian geometry."""

    from matrix_smith import build_gic_b_matrix

    b_matrix = np.asarray(
        build_gic_b_matrix(
            definition,
            coordinates_angstrom=np.asarray(coordinates_angstrom, dtype=float),
        ).rows,
        dtype=float,
    )
    from .fragment_backtransform import direct_fragment_rigid_tangent

    cartesian_from_all = cartesian_from_internal_jacobian(b_matrix, rcond=1.0e-8)
    fragment_tangent = direct_fragment_rigid_tangent(
        definition,
        np.asarray(coordinates_angstrom, dtype=float),
        b_matrix,
    )
    for handled_index in fragment_tangent.handled_indices:
        cartesian_from_all[:, handled_index] = fragment_tangent.cartesian_from_q[:, handled_index]
    labels = tuple(gic.identifier for gic in definition.gics)
    names = tuple(gic.name for gic in definition.gics)
    source_labels = tuple(model.sonic_labels or model.labels)
    indices = tuple(_coordinate_index(label, labels, names) for label in source_labels)
    selected = cartesian_from_all[:, indices]
    transform = model.sonic_from_coordinates
    if transform is not None:
        selected = selected @ np.asarray(transform, dtype=float)
    return np.asarray(selected.T, dtype=float) * ANGSTROM_TO_BOHR


def chemical_optimizer_hessian(
    model: OptimizerCoordinateModel,
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    *,
    xyzin_path: Path | str,
    settings: OptimizerSettings | None = None,
) -> np.ndarray:
    """Return the production chemical initial Hessian for an active model."""

    return _initial_optimizer_hessian(
        model,
        settings or OptimizerSettings(),
        initial_hessian=None,
        atoms=tuple(atoms),
        coordinates_angstrom=np.asarray(coordinates_angstrom, dtype=float),
        xyzin_path=xyzin_path,
    )


def optimizer_hessian_from_gaussian_hessian(
    path: Path | str,
    model: OptimizerCoordinateModel,
) -> np.ndarray:
    return optimizer_hessian_from_engine_hessian("gaussian", path, model)


def hessian_input_from_engine_hessian(
    engine: str,
    path: Path | str,
    *,
    grd: Path | str | None = None,
    output: Path | str | None = None,
    geometry: Path | str | None = None,
    spectrum: Path | str | None = None,
    input_path: Path | str | None = None,
):
    """Compatibility wrapper around the canonical ``matrix_qm`` dispatcher."""

    from matrix_qm.hessians import hessian_input_from_engine

    return hessian_input_from_engine(
        engine,
        path,
        grd=grd,
        output=output,
        geometry=geometry,
        spectrum=spectrum,
        input_path=input_path,
    )


def cartesian_vibrational_hessian_index_from_engine(
    engine: str,
    path: Path | str,
    *,
    grd: Path | str | None = None,
    output: Path | str | None = None,
) -> int:
    """Return the vibrational inertia of an imported Cartesian Hessian.

    Translation and rotation are projected in the canonical mass-weighted
    Cartesian space.  This is the pre-optimization basin test; it is not
    inferred from the reduced optimizer-coordinate Hessian.
    """
    from matrix_qm.normal_modes import cartesian_normal_modes_from_hessian

    data = hessian_input_from_engine_hessian(engine, path, grd=grd, output=output)
    modes = cartesian_normal_modes_from_hessian(
        data.cartesian_hessian,
        data.masses_amu,
        data.cartesian_coordinates_bohr,
        source=f"{engine} initial Cartesian Hessian {path}",
    )
    return int(np.count_nonzero(np.asarray(modes.eigenvalues, dtype=float) < -1.0e-12))


def optimizer_hessian_from_engine_hessian(
    engine: str,
    path: Path | str,
    model: OptimizerCoordinateModel,
    *,
    grd: Path | str | None = None,
    output: Path | str | None = None,
    cartesian_gradient_hartree_per_bohr: np.ndarray | None = None,
    use_b_prime: bool = False,
    b_prime_parallel_workers: int = 0,
    hessian_kind: str = "qm",
    xyzin_path: Path | str | None = None,
) -> np.ndarray:
    normalized_kind = str(hessian_kind).strip().lower().replace("-", "_")
    if normalized_kind not in {"qm", "force_field"}:
        raise ValueError("hessian_kind must be 'qm' or 'force_field'")
    if normalized_kind == "force_field" and xyzin_path is None:
        raise ValueError("force-field Hessian import requires xyzin_path")
    if normalized_kind == "force_field" and use_b_prime:
        raise ValueError("B-prime is not part of the force-field seed contract")
    data = hessian_input_from_engine_hessian(engine, path, grd=grd, output=output)
    hessian = np.asarray(data.cartesian_hessian, dtype=float)
    gradient = (
        None
        if cartesian_gradient_hartree_per_bohr is None
        else np.asarray(cartesian_gradient_hartree_per_bohr, dtype=float).reshape(-1)
    )
    coordinates_angstrom = (
        np.asarray(data.cartesian_coordinates_bohr, dtype=float) / ANGSTROM_TO_BOHR
    )
    if model.kind == "sonic" and model.sonic_definition is not None:
        reference = np.asarray(model.sonic_definition.reference_coordinates_angstrom, dtype=float)
        if coordinates_angstrom.shape != reference.shape:
            raise ValueError("Imported Hessian geometry does not match the SONIC atom count")
        rotation = kabsch_rotation(coordinates_angstrom, reference)
        rotation_gradient = (
            np.zeros(coordinates_angstrom.size, dtype=float) if gradient is None else gradient
        )
        rotated_gradient, rotated_hessian = rotate_cartesian_derivatives(
            rotation_gradient,
            rotation,
            hessian,
        )
        assert rotated_hessian is not None
        hessian = rotated_hessian
        gradient = None if gradient is None else rotated_gradient
        coordinates_angstrom = kabsch_align(coordinates_angstrom, reference)
    if use_b_prime and gradient is None:
        raise ValueError("B-prime Hessian transformation requires a Cartesian gradient")
    if normalized_kind == "force_field":
        assert xyzin_path is not None
        return optimizer_hessian_from_force_field_cartesian(
            hessian,
            model,
            xyzin_path=xyzin_path,
            coordinates_angstrom=coordinates_angstrom,
        )
    return optimizer_hessian_from_cartesian(
        hessian,
        model,
        cartesian_gradient_hartree_per_bohr=(gradient if use_b_prime else None),
        coordinates_angstrom=coordinates_angstrom,
        b_prime_parallel_workers=b_prime_parallel_workers,
    )


def build_optimizer_hessian_from_gaussian_job(
    xyzin_path: Path | str,
    model: OptimizerCoordinateModel,
    *,
    run_dir: Path | str,
    route: str = "#p HF/STO-3G Freq",
    charge: int = 0,
    multiplicity: int = 1,
    executable: str | None = None,
    timeout: float | None = None,
    use_b_prime: bool = False,
    route_override=None,
) -> tuple[np.ndarray, Path]:
    """Run a Gaussian frequency job and project its Cartesian Hessian into optimizer coordinates."""

    from matrix_gaussian import (
        formchk_checkpoint,
        hessian_input_from_gaussian_log,
        read_gaussian_fchk,
        run_gaussian_job,
        write_gaussian_point_input,
    )

    geometry = read_xyzin_geometry(Path(xyzin_path))
    root = Path(run_dir).expanduser().resolve()
    root.mkdir(parents=True, exist_ok=True)
    checkpoint_path = root / "optimizer_hessian_seed.chk"
    input_path = write_gaussian_point_input(
        root / "gauin.gjf",
        tuple(geometry.atoms),
        np.asarray(geometry.coordinates_angstrom, dtype=float),
        route=route,
        title="MATRIX optimizer Hessian seed",
        charge=charge,
        multiplicity=multiplicity,
        ensure_force=False,
        link0=(f"%chk={checkpoint_path.name}",),
        route_override=route_override,
    )
    started = time.perf_counter()
    run = run_gaussian_job(
        root,
        executable=executable,
        input_path=input_path,
        timeout=timeout,
        route_overrides=(() if route_override is None else (route_override,)),
    )
    if run.success is not True:
        raise RuntimeError(run.message)
    elapsed = time.perf_counter() - started
    cartesian_gradient = None
    hessian_coordinates_angstrom = np.asarray(geometry.coordinates_angstrom, dtype=float)
    if checkpoint_path.is_file():
        fchk_path = formchk_checkpoint(
            checkpoint_path,
            root / "optimizer_hessian_seed.fchk",
            timeout=timeout,
        )
        fchk = read_gaussian_fchk(fchk_path)
        cartesian_hessian = fchk.to_hessian_input().cartesian_hessian
        target_coordinates = np.asarray(geometry.coordinates_angstrom, dtype=float)
        candidate_gradient = np.asarray(
            getattr(fchk, "cartesian_gradient_hartree_per_bohr", ()), dtype=float
        ).reshape(-1)
        if candidate_gradient.shape == (target_coordinates.size,):
            cartesian_gradient = candidate_gradient
        fchk_coordinates_angstrom = (
            np.asarray(fchk.cartesian_coordinates_bohr, dtype=float) * 0.529177210903
        )
        # A linear geometry does not define rotations about its molecular
        # axis.  LAPACK is therefore free to return different, but equally
        # valid, Kabsch representatives on different architectures.  Preserve
        # the existing Cartesian frame when Gaussian already returned the
        # requested coordinates; otherwise such an arbitrary representative
        # would rotate an anisotropic Cartesian Hessian.
        if np.allclose(
            fchk_coordinates_angstrom,
            target_coordinates,
            rtol=0.0,
            atol=1.0e-10,
        ):
            rotation = np.eye(3, dtype=float)
        else:
            rotation = kabsch_rotation(fchk_coordinates_angstrom, target_coordinates)
        rotated_gradient, rotated_hessian = rotate_cartesian_derivatives(
            (
                np.zeros(target_coordinates.size, dtype=float)
                if cartesian_gradient is None
                else cartesian_gradient
            ),
            rotation,
            cartesian_hessian,
        )
        assert rotated_hessian is not None
        cartesian_hessian = rotated_hessian
        if cartesian_gradient is not None:
            cartesian_gradient = rotated_gradient
        hessian_coordinates_angstrom = kabsch_align(fchk_coordinates_angstrom, target_coordinates)
    else:
        # Minimal test doubles may not implement Gaussian checkpoints. Keep the
        # log archive as their compatibility path; production GDV/G16 jobs use
        # the full-precision checkpoint branch above.
        data = hessian_input_from_gaussian_log(run.log_path)
        cartesian_hessian = data.cartesian_hessian
        hessian_coordinates_angstrom = (
            np.asarray(data.cartesian_coordinates_bohr, dtype=float) / ANGSTROM_TO_BOHR
        )
    if use_b_prime and cartesian_gradient is None:
        raise RuntimeError(
            "Gaussian Hessian seed requires its same-level Cartesian gradient for B-prime"
        )
    metadata_path = root / "hessian_seed_metadata.json"
    metadata_path.write_text(
        json.dumps(
            {
                "schema": "matrix.link.initial_hessian.gaussian.v1",
                "engine": "gaussian",
                "route": route,
                "wall_time_seconds": elapsed,
                "process_launches": 1,
                "cartesian_gradient_included": cartesian_gradient is not None,
                "b_prime_included": bool(use_b_prime),
                "log": str(run.log_path),
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )
    return optimizer_hessian_from_cartesian(
        cartesian_hessian,
        model,
        cartesian_gradient_hartree_per_bohr=(cartesian_gradient if use_b_prime else None),
        coordinates_angstrom=hessian_coordinates_angstrom,
    ), run.log_path


def _build_matrix_gfn2_optimizer_hessian_seed(
    xyzin_path: Path | str,
    model: OptimizerCoordinateModel,
    *,
    run_dir: Path,
    method: str,
    charge: int,
    multiplicity: int,
    hessian_kind: str = "qm",
    parallel_workers: int = 1,
) -> tuple[np.ndarray, Path]:
    """Build a MATRIX-GFN2 Hessian from autonomous in-process calculations."""

    from .resident_calculators import create_resident_calculator

    geometry = read_xyzin_geometry(Path(xyzin_path))
    coordinates = np.asarray(geometry.coordinates_angstrom, dtype=float)
    ncart = coordinates.size
    step_bohr = 1.0e-3
    step_angstrom = step_bohr / ANGSTROM_TO_BOHR
    center_session = create_resident_calculator(
        "matrix_gfn2",
        tuple(geometry.atoms),
        coordinates,
        charge=charge,
        multiplicity=multiplicity,
        method=method or "GFN2-xTB",
    )
    started = time.perf_counter()
    center = center_session.evaluate(coordinates)
    hessian = np.zeros((ncart, ncart), dtype=float)
    flat = coordinates.reshape(-1)
    effective_workers = min(max(1, int(parallel_workers)), max(1, ncart))

    def displaced_column(column: int) -> tuple[int, np.ndarray]:
        plus = flat.copy()
        minus = flat.copy()
        plus[column] += step_angstrom
        minus[column] -= step_angstrom
        # Independent cold starts avoid path-dependent SCF restart noise in
        # the antisymmetric part of the numerical Hessian, especially for its
        # softest vibrational modes.
        plus_gradient = (
            create_resident_calculator(
                "matrix_gfn2",
                tuple(geometry.atoms),
                plus.reshape(coordinates.shape),
                charge=charge,
                multiplicity=multiplicity,
                method=method or "GFN2-xTB",
            )
            .evaluate(plus.reshape(coordinates.shape))
            .gradient_hartree_per_bohr
        )
        minus_gradient = (
            create_resident_calculator(
                "matrix_gfn2",
                tuple(geometry.atoms),
                minus.reshape(coordinates.shape),
                charge=charge,
                multiplicity=multiplicity,
                method=method or "GFN2-xTB",
            )
            .evaluate(minus.reshape(coordinates.shape))
            .gradient_hartree_per_bohr
        )
        return column, (
            np.asarray(plus_gradient, dtype=float).reshape(-1)
            - np.asarray(minus_gradient, dtype=float).reshape(-1)
        ) / (2.0 * step_bohr)

    if effective_workers == 1:
        columns = (displaced_column(column) for column in range(ncart))
    else:

        def parallel_column(column: int) -> tuple[int, np.ndarray]:
            return displaced_column(column)

        pool = ThreadPoolExecutor(max_workers=effective_workers)
        columns = pool.map(parallel_column, range(ncart))

    try:
        for column, values in columns:
            hessian[:, column] = values
    finally:
        if effective_workers > 1:
            pool.shutdown(wait=True)
    calculator_sessions = 1 + 2 * ncart
    hessian = 0.5 * (hessian + hessian.T)
    cartesian_gradient = np.asarray(center.gradient_hartree_per_bohr, dtype=float).reshape(-1)
    point_group = (
        str(getattr(getattr(model, "sonic_definition", None), "point_group", "C1")).strip() or "C1"
    )
    symmetry_operations: tuple[object, ...] = ()
    if model.kind == "sonic" and point_group.upper() != "C1":
        from matrix_smith import construct_gic_definition_from_xyzin

        _definition, source_atoms, symmetry_operations = construct_gic_definition_from_xyzin(
            Path(xyzin_path),
            symmetry_group=point_group,
            fragment_context=_frozen_smith_fragment_context(Path(xyzin_path)),
            retain_candidate_primitives=False,
        )
        if tuple(source_atoms) != tuple(geometry.atoms):
            raise RuntimeError("xTB Hessian symmetry operations do not match the frozen atom order")
    unsymmetrized_hessian = hessian.copy()
    if symmetry_operations:
        hessian = _point_group_average_cartesian_hessian(
            hessian,
            operations=symmetry_operations,
            natoms=len(geometry.atoms),
        )
        cartesian_gradient = _point_group_average_cartesian_gradient(
            cartesian_gradient,
            operations=symmetry_operations,
            natoms=len(geometry.atoms),
        )
    molecular_symmetry_change = float(np.max(np.abs(hessian - unsymmetrized_hessian), initial=0.0))
    elapsed = time.perf_counter() - started
    artifact = run_dir / "matrix_gfn2_cartesian_hessian.json"
    artifact.write_text(
        json.dumps(
            {
                "schema": "matrix.link.initial_hessian.matrix_gfn2.v1",
                "engine": "matrix_gfn2",
                "method": method or "GFN2-xTB",
                "units": "hartree/bohr^2",
                "gradient_units": "hartree/bohr",
                "finite_difference_step_bohr": step_bohr,
                "gradient_evaluations": 2 * ncart + 1,
                "process_launches": 0,
                "parallel_workers": effective_workers,
                "calculator_sessions": calculator_sessions,
                "point_group": point_group,
                "symmetry_operation_count": max(1, len(symmetry_operations)),
                "molecular_symmetry_projection": bool(symmetry_operations),
                "molecular_symmetry_max_abs_change": molecular_symmetry_change,
                "initial_guess_transform": "linear_congruence_without_B_prime",
                "wall_time_seconds": elapsed,
                "coordinates_angstrom": coordinates.tolist(),
                "gradient_hartree_per_bohr": cartesian_gradient.tolist(),
                "hessian": hessian.tolist(),
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )
    projected = (
        optimizer_hessian_from_force_field_cartesian(
            hessian,
            model,
            xyzin_path=xyzin_path,
            coordinates_angstrom=coordinates,
        )
        if hessian_kind == "force_field"
        else optimizer_hessian_from_cartesian(
            hessian,
            model,
            coordinates_angstrom=coordinates,
        )
    )
    return projected, artifact


def _frozen_composite_initial_hessian_route_override(
    *,
    selector: str,
    protocol_id: str,
    protocol_sha256: str,
    engine: str,
    route: str,
):
    """Authorize only the exact initial-Hessian route pinned by KeyMaker."""

    if not str(selector).strip():
        return None
    from .composite_protocol import load_composite_protocol

    if not str(protocol_id).strip() and not str(protocol_sha256).strip():
        try:
            load_composite_protocol(selector)
        except ValueError:
            return None
    protocol = load_composite_protocol(selector)
    if str(protocol_id).strip() != protocol.protocol_id:
        raise RuntimeError("initial Hessian composite protocol identifier changed")
    if str(protocol_sha256).strip() != protocol.sha256:
        raise RuntimeError("initial Hessian composite protocol hash changed")
    initialization = protocol.payload["initialization"]
    if _normalized_hessian_engine(engine) != _normalized_hessian_engine(
        str(initialization["backend"])
    ):
        raise RuntimeError("initial Hessian backend differs from the frozen composite protocol")
    if " ".join(str(route).split()) != " ".join(str(initialization["route"]).split()):
        raise RuntimeError("initial Hessian route differs from the frozen composite protocol")
    if _normalized_hessian_engine(engine) not in {"gdv", "gaussian", "g16"}:
        return None
    from matrix_gaussian import gaussian_route_violations

    violations = gaussian_route_violations(route)
    if not violations:
        return None
    raise RuntimeError(
        "frozen composite initial Hessian contains an unauthorized Gaussian route rule"
    )


def build_optimizer_hessian_seed(
    xyzin_path: Path | str,
    model: OptimizerCoordinateModel,
    *,
    engine: str,
    run_dir: Path | str,
    route: str = "",
    method: str = "",
    basis: str = "",
    charge: int = 0,
    multiplicity: int = 1,
    executable: str | None = None,
    timeout: float | None = None,
    engine_command: str = "",
    hessian_path: Path | str | None = None,
    hessian_kind: str = "qm",
    parallel_workers: int = 1,
    processors: int | None = None,
    memory_gb: float | None = None,
    composite_protocol_selector: str = "",
    composite_protocol_id: str = "",
    composite_protocol_sha256: str = "",
) -> tuple[np.ndarray, Path]:
    """Build a low-level Hessian seed, then project it into optimizer coordinates.

    ``hessian_kind`` is an explicit scientific source declaration. ``qm``
    uses the optimization coordinates directly; ``force_field`` enforces the
    frozen ORACLE-atlas source-coordinate contract before the target transformation.
    """

    name = _normalized_hessian_engine(engine)
    normalized_kind = str(hessian_kind).strip().lower().replace("-", "_")
    if normalized_kind not in {"qm", "force_field"}:
        raise ValueError("hessian_kind must be 'qm' or 'force_field'")
    root = Path(run_dir).expanduser().resolve()
    root.mkdir(parents=True, exist_ok=True)
    gaussian_route_override = _frozen_composite_initial_hessian_route_override(
        selector=composite_protocol_selector,
        protocol_id=composite_protocol_id,
        protocol_sha256=composite_protocol_sha256,
        engine=engine,
        route=route,
    )
    if engine_command.strip():
        target = (
            Path(hessian_path)
            if hessian_path is not None
            else root / _default_hessian_output_name(name)
        )
        command = _format_command(
            engine_command,
            xyzin=Path(xyzin_path),
            workdir=root,
            hessian=target,
            output=target,
        )
        require_authorized_descendant_calculation(
            backend="LINK/external-hessian-provider",
            input_path=xyzin_path,
            command=command,
            workdir=root,
        )
        completed = subprocess.run(
            command,
            cwd=root,
            check=False,
            timeout=timeout,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
        )
        if completed.returncode != 0:
            raise RuntimeError(completed.stdout.strip())
        projected = optimizer_hessian_from_engine_hessian(
            name,
            target,
            model,
            hessian_kind=normalized_kind,
            xyzin_path=xyzin_path,
        )
        return projected, target
    if name == "xtb":
        return _build_xtb_optimizer_hessian_seed(
            xyzin_path,
            model,
            run_dir=root,
            route=route or "--gfn 2",
            executable=executable,
            timeout=timeout,
            hessian_kind=normalized_kind,
        )
    if name == "matrix_gfn2":
        return _build_matrix_gfn2_optimizer_hessian_seed(
            xyzin_path,
            model,
            run_dir=root,
            method=method or "MATRIX-GFN2",
            charge=charge,
            multiplicity=multiplicity,
            hessian_kind=normalized_kind,
            parallel_workers=parallel_workers,
        )
    if name == "pyscf":
        from matrix_pyscf import pyscf_cartesian_hessian

        geometry = read_xyzin_geometry(Path(xyzin_path))
        evaluation = pyscf_cartesian_hessian(
            geometry.atoms,
            geometry.coordinates_angstrom,
            method=method or "HF",
            basis=basis or "STO-3G",
            charge=charge,
            multiplicity=multiplicity,
        )
        cartesian = np.asarray(evaluation.hessian_hartree_per_bohr2, dtype=float)
        artifact = root / "pyscf_cartesian_hessian.json"
        artifact.write_text(
            json.dumps(
                {
                    "schema": "matrix.link.initial_hessian.pyscf.v1",
                    "method": method or "HF",
                    "basis": basis or "STO-3G",
                    "charge": int(charge),
                    "multiplicity": int(multiplicity),
                    "derivative": evaluation.derivative,
                    "gradient_evaluations": evaluation.gradient_evaluations,
                    "units": "hartree/bohr^2",
                    "hessian": cartesian.tolist(),
                },
                indent=2,
                sort_keys=True,
            )
            + "\n",
            encoding="utf-8",
        )
        projected = (
            optimizer_hessian_from_force_field_cartesian(
                cartesian,
                model,
                xyzin_path=xyzin_path,
                coordinates_angstrom=np.asarray(geometry.coordinates_angstrom, dtype=float),
            )
            if normalized_kind == "force_field"
            else optimizer_hessian_from_cartesian(cartesian, model)
        )
        return projected, artifact
    if name == "gaussian":
        hessian, log_path = build_optimizer_hessian_from_gaussian_job(
            xyzin_path,
            model,
            run_dir=root,
            route=route or "#p HF/STO-3G Freq",
            charge=charge,
            multiplicity=multiplicity,
            executable=executable,
            timeout=timeout,
            # The B-prime term is the curvilinear correction required when a
            # physical Cartesian Hessian is expressed in SONIC coordinates.
            # SYCART is a linear projected-Cartesian basis, so its exact
            # transformation is the single linear congruence below and must
            # not require a frozen SONIC definition.
            use_b_prime=normalized_kind == "qm" and model.kind == "sonic",
            route_override=gaussian_route_override,
        )
        return hessian, log_path
    if name == "orca":
        return _build_orca_optimizer_hessian_seed(
            xyzin_path,
            model,
            run_dir=root,
            route=route or "HF STO-3G Freq",
            charge=charge,
            multiplicity=multiplicity,
            executable=executable,
            timeout=timeout,
        )
    if name == "cfour":
        return _build_cfour_optimizer_hessian_seed(
            xyzin_path,
            model,
            run_dir=root,
            method=method or "HF",
            basis=basis or "STO-3G",
            charge=charge,
            multiplicity=multiplicity,
            executable=executable,
            timeout=timeout,
        )
    raise ValueError(
        f"automatic Hessian seed jobs for {engine!r} need --initial-hessian-seed-command; "
        "MATRIX can still read the resulting Hessian through --initial-hessian-engine/--initial-hessian-file"
    )


def _build_xtb_optimizer_hessian_seed(
    xyzin_path: Path | str,
    model: OptimizerCoordinateModel,
    *,
    run_dir: Path,
    route: str,
    executable: str | None,
    timeout: float | None,
    hessian_kind: str = "qm",
) -> tuple[np.ndarray, Path]:
    """Run xTB Hessian generation on the exact geometry consumed by LINK."""

    from matrix_core import CalculationResources, authorize_calculation_launch
    from matrix_chem import write_xyz
    from matrix_engines import prepare_external_qm_launch_plan
    from matrix_xtb import XTB_SPEC
    from matrix_xtb import hessian_input_from_xtb_files, run_xtb_job

    geometry_path = Path(xyzin_path)
    geometry = read_xyzin_geometry(geometry_path)
    seed_input = run_dir / "input.xyz"
    write_xyz(
        seed_input,
        tuple(geometry.atoms),
        np.asarray(geometry.coordinates_angstrom, dtype=float),
        comment="MATRIX xTB Hessian seed",
    )
    output_path = run_dir / "xtb.out"
    resources = CalculationResources(
        process_count=1,
        threads_per_process=1,
        memory_per_job_gb=1.0,
        concurrent_jobs=1,
    )
    launch_plan = prepare_external_qm_launch_plan(
        run_dir,
        XTB_SPEC,
        executable=executable,
        input_path=seed_input,
        extra_args=tuple(shlex.split(route)) + ("--hess",),
        resources=resources,
    )
    authorization = authorize_calculation_launch(
        launch_plan,
        approved_plan_sha256=launch_plan.sha256,
        authorized_by="LINK optimizer user request",
    )
    run = run_xtb_job(
        run_dir,
        executable=executable,
        input_path=seed_input,
        output_path=output_path,
        timeout=timeout,
        extra_args=tuple(shlex.split(route)) + ("--hess",),
        resources=resources,
        launch_authorization=authorization,
    )
    if run.success is not True:
        raise RuntimeError(run.message)
    hessian_path = run_dir / "hessian"
    data = hessian_input_from_xtb_files(
        hessian_path,
        geometry=seed_input,
        output=output_path,
    )
    projected = (
        optimizer_hessian_from_force_field_cartesian(
            data.cartesian_hessian,
            model,
            xyzin_path=xyzin_path,
            coordinates_angstrom=np.asarray(geometry.coordinates_angstrom, dtype=float),
        )
        if hessian_kind == "force_field"
        else optimizer_hessian_from_cartesian(data.cartesian_hessian, model)
    )
    return projected, hessian_path


def _build_orca_optimizer_hessian_seed(
    xyzin_path: Path | str,
    model: OptimizerCoordinateModel,
    *,
    run_dir: Path,
    route: str,
    charge: int,
    multiplicity: int,
    executable: str | None,
    timeout: float | None,
) -> tuple[np.ndarray, Path]:
    from matrix_orca import hessian_input_from_orca_output, run_orca_job, write_orca_point_input

    geometry = read_xyzin_geometry(Path(xyzin_path))
    input_path = write_orca_point_input(
        run_dir / "orca.inp",
        tuple(geometry.atoms),
        np.asarray(geometry.coordinates_angstrom, dtype=float),
        route=route,
        charge=charge,
        multiplicity=multiplicity,
    )
    run = run_orca_job(
        run_dir,
        executable=executable,
        input_path=input_path,
        timeout=timeout,
    )
    if run.success is not True:
        raise RuntimeError(run.message)
    data = hessian_input_from_orca_output(run.output_path)
    return optimizer_hessian_from_cartesian(data.cartesian_hessian, model), run.output_path


def _build_cfour_optimizer_hessian_seed(
    xyzin_path: Path | str,
    model: OptimizerCoordinateModel,
    *,
    run_dir: Path,
    method: str,
    basis: str,
    charge: int,
    multiplicity: int,
    executable: str | None,
    timeout: float | None,
) -> tuple[np.ndarray, Path]:
    from matrix_cfour import hessian_input_from_cfour_files, run_cfour_job, write_cfour_point_input

    geometry = read_xyzin_geometry(Path(xyzin_path))
    input_path = write_cfour_point_input(
        run_dir / "ZMAT",
        tuple(geometry.atoms),
        np.asarray(geometry.coordinates_angstrom, dtype=float),
        method=method,
        basis=basis,
        charge=charge,
        multiplicity=multiplicity,
    )
    text = input_path.read_text(encoding="utf-8")
    input_path.write_text(text.replace("DERIV_LEVEL=FIRST", "DERIV_LEVEL=SECOND"), encoding="utf-8")
    run = run_cfour_job(
        run_dir,
        executable=executable,
        input_path=input_path,
        timeout=timeout,
    )
    if run.success is not True:
        raise RuntimeError(run.message)
    fcmfinal = run_dir / "FCMFINAL"
    data = hessian_input_from_cfour_files(
        fcmfinal,
        grd=run_dir / "GRD",
        output=run.output_path,
    )
    return optimizer_hessian_from_cartesian(data.cartesian_hessian, model), fcmfinal


def _normalized_hessian_engine(engine: str) -> str:
    normalized = str(engine).strip().lower().replace("-", "").replace("_", "")
    aliases = {
        "xyzin": "xyzin",
        "matrix": "xyzin",
        "gaussian": "gaussian",
        "g16": "gaussian",
        "gdv": "gaussian",
        "gaussian16": "gaussian",
        "orca": "orca",
        "molpro": "molpro",
        "mrcc": "mrcc",
        "cfour": "cfour",
        "cfourfcmfinal": "cfour",
        "xtb": "xtb",
        "matrixgfn2": "matrix_gfn2",
        "gfn2xtb": "matrix_gfn2",
        "pyscf": "pyscf",
    }
    try:
        return aliases[normalized]
    except KeyError as exc:
        raise ValueError(f"unsupported Hessian engine: {engine}") from exc


def _default_hessian_output_name(engine: str) -> str:
    if engine == "cfour":
        return "FCMFINAL"
    if engine == "orca":
        return "orca.out"
    if engine == "gaussian":
        return "gau.log"
    if engine == "molpro":
        return "molpro.out"
    if engine == "mrcc":
        return "mrcc.out"
    if engine == "xtb":
        return "hessian"
    if engine == "pyscf":
        return "pyscf_cartesian_hessian.json"
    return "hessian.out"


def _signed_energy_change(old_energy: float, new_energy: float) -> float:
    """Return ``E_new - E_old`` for convergence and trace diagnostics."""

    old = float(old_energy)
    new = float(new_energy)
    if not math.isfinite(old) or not math.isfinite(new):
        raise ValueError("energy change requires finite energies")
    return new - old


def _positive_metric_matrix(metric: np.ndarray, absolute_floor: float) -> np.ndarray:
    """Return a symmetric positive metric without discarding its couplings."""

    matrix = np.asarray(metric, dtype=float)
    if matrix.ndim != 2 or matrix.shape[0] != matrix.shape[1]:
        raise ValueError("optimizer metric must be square")
    if not np.all(np.isfinite(matrix)):
        raise ValueError("optimizer metric contains non-finite values")
    matrix = 0.5 * (matrix + matrix.T)
    if matrix.size == 0:
        return matrix
    eigenvalues, eigenvectors = np.linalg.eigh(matrix)
    maximum = max(float(np.max(np.abs(eigenvalues))), float(absolute_floor))
    floor = max(float(absolute_floor), 1.0e-12 * maximum)
    positive = np.maximum(eigenvalues, floor)
    result = eigenvectors @ np.diag(positive) @ eigenvectors.T
    return 0.5 * (result + result.T)


def _initial_optimizer_hessian(
    model: OptimizerCoordinateModel,
    settings: OptimizerSettings,
    *,
    initial_hessian: np.ndarray | None,
    atoms: Sequence[str] = (),
    coordinates_angstrom: np.ndarray | None = None,
    xyzin_path: Path | str | None = None,
) -> np.ndarray:
    matrix, _source = _initial_optimizer_hessian_selection(
        model,
        settings,
        initial_hessian=initial_hessian,
        atoms=atoms,
        coordinates_angstrom=coordinates_angstrom,
        xyzin_path=xyzin_path,
    )
    return matrix


def _hf_sto3g_fd_initial_hessian(
    service: GeometryEvaluationService,
    model: OptimizerCoordinateModel,
    *,
    backend: QMScanBackend | None,
    coordinates_angstrom: np.ndarray,
    run_dir: Path,
    method: str = "HF",
) -> tuple[np.ndarray, str]:
    """Build a Cartesian STO-3G Hessian from PyFock gradients.

    HF uses PyFock's numerical nuclear-gradient driver because the current
    release does not expose analytic HF gradients.  LDA uses PyFock's
    analytic nuclear gradients and only the outer Hessian difference is
    numerical.
    """

    if backend is None or _normalized_backend_name(backend.name) != "pyfock":
        raise RuntimeError("HF/STO-3G seed requires a PyFock backend")
    if model.kind != "cartesian":
        raise RuntimeError("HF/STO-3G seed currently requires Cartesian optimizer coordinates")
    from dataclasses import replace as dataclass_replace

    seed_backend = dataclass_replace(
        backend,
        method=method,
        route=method,
        basis="sto-3g",
        # PyFock has no analytic HF gradient in the current release; its
        # numerical-gradient driver supplies the gradients that are then
        # centrally differenced into this initial Hessian.
        gradient_mode=("analytic" if method.upper() == "LDA" else "numerical"),
        numerical_gradient_stencil="central",
        reuse_density_projection=False,
        pyfock_initial_guess="core",
    )
    seed_service = GeometryEvaluationService(
        xyzin_path=service.xyzin_path,
        run_dir=run_dir,
        coordinate_model=model,
        backend=seed_backend,
        timeout=service.timeout,
        settings=service.settings,
    )
    coordinates = np.asarray(coordinates_angstrom, dtype=float)
    ncart = coordinates.size
    step_bohr = 1.0e-3
    step_angstrom = step_bohr / ANGSTROM_TO_BOHR
    hessian = np.zeros((ncart, ncart), dtype=float)
    zero_q = np.zeros(ncart, dtype=float)
    for column in range(ncart):
        plus = coordinates.reshape(-1).copy()
        minus = coordinates.reshape(-1).copy()
        plus[column] += step_angstrom
        minus[column] -= step_angstrom
        plus_result = seed_service.evaluate(
            zero_q,
            tag=f"initial-hessian-plus-{column + 1}",
            use_cache=False,
            persist_cache=True,
            requested_properties=("energy", "gradient"),
            realized_coordinates_angstrom=plus.reshape(coordinates.shape),
        )
        minus_result = seed_service.evaluate(
            zero_q,
            tag=f"initial-hessian-minus-{column + 1}",
            use_cache=False,
            persist_cache=True,
            requested_properties=("energy", "gradient"),
            realized_coordinates_angstrom=minus.reshape(coordinates.shape),
        )
        plus_gradient = plus_result.result.gradient_hartree_per_bohr
        minus_gradient = minus_result.result.gradient_hartree_per_bohr
        if plus_gradient is None or minus_gradient is None:
            raise RuntimeError("PyFock HF/STO-3G gradient missing during Hessian construction")
        hessian[:, column] = (
            np.asarray(plus_gradient, dtype=float).reshape(-1)
            - np.asarray(minus_gradient, dtype=float).reshape(-1)
        ) / (2.0 * step_bohr)
    hessian = 0.5 * (hessian + hessian.T)
    return hessian, f"PyFock {method.upper()}/STO-3G central finite-difference gradient Hessian"


def _gfn2_xtb_initial_hessian(
    service: GeometryEvaluationService,
    model: OptimizerCoordinateModel,
    *,
    backend: QMScanBackend | None,
    run_dir: Path,
) -> tuple[np.ndarray, str]:
    """Build the initial Hessian with GFN2-xTB.

    The Hessian and the electronic guess are deliberately decoupled: xTB
    supplies only the inexpensive curvature model, while the PyFock point
    backend can independently use a projected HF/STO-3G density guess.
    """

    if backend is None or _normalized_backend_name(backend.name) != "pyfock":
        raise RuntimeError("GFN2-xTB seed requires a PyFock optimization backend")
    if model.kind != "cartesian":
        raise RuntimeError("GFN2-xTB seed currently requires Cartesian optimizer coordinates")
    executable = shutil.which("xtb")
    if executable is None:
        raise FileNotFoundError("GFN2-xTB Hessian seed requested but xtb is not available")
    geometry = read_xyzin_geometry(Path(service.xyzin_path))
    hessian, _path = _build_xtb_optimizer_hessian_seed(
        service.xyzin_path,
        model,
        run_dir=run_dir,
        route="--gfn 2",
        executable=executable,
        timeout=service.timeout,
        hessian_kind="qm",
    )
    del geometry
    return hessian, "GFN2-xTB analytic Hessian + PyFock configurable STO-3G projected density guess"


def _frozen_gic_for_active_label(definition, label: str):
    """Resolve an active SONIC identity without requiring display-name uniqueness."""

    text = str(label)
    identifier_matches = tuple(gic for gic in definition.gics if str(gic.identifier) == text)
    if len(identifier_matches) == 1:
        return identifier_matches[0]
    if len(identifier_matches) > 1:
        raise ValueError(f"duplicate frozen SONIC identifier {text}")
    name_matches = tuple(gic for gic in definition.gics if str(gic.name or gic.identifier) == text)
    if len(name_matches) == 1:
        return name_matches[0]
    if len(name_matches) > 1:
        raise ValueError(f"ambiguous frozen SONIC display name {text}")
    raise ValueError(f"local SONIC atlas cannot classify {text}")


def _sonic_family_components(
    model: OptimizerCoordinateModel,
) -> tuple[tuple[tuple[str, float], ...], ...]:
    """Return squared local-family weights for every active SONIC variable."""

    if model.kind == "sonic":
        definition = model.sonic_definition
        if definition is None:
            raise ValueError("the local SONIC atlas requires a frozen SONIC definition")
        source_labels = tuple(model.sonic_labels or model.labels)
        source_families = tuple(
            str(_frozen_gic_for_active_label(definition, label).family).strip().upper()
            for label in source_labels
        )
        transform = model.sonic_from_coordinates
        if transform is None:
            if source_labels != tuple(model.labels):
                raise ValueError("unprojected SONIC source and active labels differ")
            return tuple(((family, 1.0),) for family in source_families)
        coefficients = np.asarray(transform, dtype=float)
        components: list[tuple[tuple[str, float], ...]] = []
        for column in range(coefficients.shape[1]):
            support = np.flatnonzero(np.abs(coefficients[:, column]) > 1.0e-12)
            if not len(support):
                raise ValueError(
                    f"active SONIC coordinate {model.labels[column]} has empty support"
                )
            weights: dict[str, float] = {}
            for index in support:
                family = source_families[index]
                weights[family] = weights.get(family, 0.0) + float(coefficients[index, column] ** 2)
            components.append(tuple(sorted(weights.items())))
        return tuple(components)

    if model.kind == "typed_onic":
        runtime = model.typed_onic_runtime
        if runtime is None:
            raise ValueError("the local SONIC atlas requires a typed ONIC runtime")
        family_by_label: dict[str, str] = {}
        for block in runtime.definition.blocks:
            if block.representation == "SYMMETRY_ADAPTED_CARTESIAN":
                block_families = ("CARTESIAN_DISPLACEMENT",) * block.target_rank
            elif block.representation == "INVERSE_DISTANCE_PROJECTOR":
                block_families = ("INVERSE_DISTANCE_PAIR",) * block.target_rank
            else:
                payload = runtime._payload_by_id.get(block.identifier)
                if payload is None:
                    raise ValueError(f"typed ONIC block {block.identifier} lacks its payload")
                by_name = {
                    f"{block.identifier}.{gic.name or gic.identifier}": str(gic.family).upper()
                    for gic in payload.gics
                }
                try:
                    block_families = tuple(by_name[label] for label in block.coordinate_identifiers)
                except KeyError as exc:
                    raise ValueError(f"typed ONIC atlas cannot classify {exc.args[0]}") from exc
            family_by_label.update(zip(block.coordinate_identifiers, block_families))
        try:
            return tuple(((family_by_label[label], 1.0),) for label in model.labels)
        except KeyError as exc:
            raise ValueError(f"typed ONIC atlas cannot classify {exc.args[0]}") from exc

    raise ValueError(f"the local SONIC atlas does not apply to {model.kind}")


def _sonic_family_diagonal_seed(
    model: OptimizerCoordinateModel,
    *,
    regime: str = "MINIMUM",
    xyzin_path: Path | str | None = None,
    atoms: Sequence[str] = (),
) -> tuple[np.ndarray, dict[str, object]]:
    """Build an O(n) diagonal seed directly from family labels, without transforms."""

    from matrix_smith import DEFAULT_SONIC_FORCE_CONSTANT_ATLAS

    components = _sonic_family_components(model)
    local_parameters: list[dict[str, object]] = []
    typed_diagonal: np.ndarray | None = None
    if xyzin_path is not None and atoms and model.kind == "sonic":
        from matrix_smith import sonic_primitive_environments_from_xyzin

        definition = model.sonic_definition
        environments = sonic_primitive_environments_from_xyzin(
            xyzin_path,
            atoms,
            definition,
        )
        primitive_constants: dict[str, float] = {}
        for primitive, environment in zip(definition.primitives, environments):
            entry = DEFAULT_SONIC_FORCE_CONSTANT_ATLAS.entry(
                primitive.family,
                regime=regime,
            )
            resolved_force_constant = entry.resolve_force_constant(environment)
            primitive_constants[primitive.identifier] = resolved_force_constant
            torsional_counts = None
            central_bond_order = None
            central_bond_typed = None
            if (
                str(primitive.family).strip().upper()
                in {
                    "TORSION",
                    "PSEUDO_CYCLE_TORSION",
                    "CYCLIC_TORSION",
                    "CONDENSED_RING_TORSION",
                }
                and len(environment.coordinate_atom_indices) == 4
            ):
                _, left, right, _ = environment.coordinate_atom_indices
                central_bond_order = environment.optional_bond_order(left, right)
                central_bond_typed = central_bond_order is not None
                if central_bond_typed:
                    torsional_counts = environment.torsional_substituent_counts()
            local_parameters.append(
                {
                    "primitive_identifier": primitive.identifier,
                    "family": primitive.family,
                    "force_constant": resolved_force_constant,
                    "equilibrium_value": entry.resolve_equilibrium(environment),
                    "coordinate_atom_indices": list(environment.coordinate_atom_indices),
                    "torsional_substituent_counts": (
                        None if torsional_counts is None else list(torsional_counts)
                    ),
                    "central_bond_order": central_bond_order,
                    "central_bond_typed": central_bond_typed,
                    "torsional_curvature_periodicity_dependent": False,
                    "atoms": [asdict(atom) for atom in environment.atoms],
                    "bonds": [asdict(bond) for bond in environment.bonds],
                }
            )
        source_constants = []
        for label in tuple(model.sonic_labels or model.labels):
            gic = _frozen_gic_for_active_label(definition, label)
            coefficients = getattr(gic, "coefficients", ()) or ((str(gic.primitive_id), 1.0),)
            source_constants.append(
                sum(
                    float(coefficient) ** 2 * primitive_constants[str(primitive_id)]
                    for primitive_id, coefficient in coefficients
                )
            )
        source_diagonal = np.asarray(source_constants, dtype=float)
        transform = model.sonic_from_coordinates
        typed_diagonal = (
            source_diagonal
            if transform is None
            else np.sum(np.asarray(transform, dtype=float) ** 2 * source_diagonal[:, None], axis=0)
        )
    diagonal = (
        np.asarray(typed_diagonal, dtype=float)
        if typed_diagonal is not None
        else np.asarray(
            [
                sum(
                    weight
                    * DEFAULT_SONIC_FORCE_CONSTANT_ATLAS.entry(
                        family,
                        regime=regime,
                    ).force_constant
                    for family, weight in coordinate_components
                )
                for coordinate_components in components
            ],
            dtype=float,
        )
    )
    if diagonal.shape != (len(model.labels),) or np.any(~np.isfinite(diagonal)):
        raise ValueError("the local SONIC family atlas returned an invalid diagonal")
    counts: dict[str, int] = {}
    for coordinate_components in components:
        for family, _weight in coordinate_components:
            counts[family] = counts.get(family, 0) + 1
    records = []
    for family in sorted(counts):
        entry = DEFAULT_SONIC_FORCE_CONSTANT_ATLAS.entry(family, regime=regime)
        resolved = [
            float(parameter["force_constant"])
            for parameter in local_parameters
            if str(parameter["family"]).strip().upper() == family
        ]
        records.append(
            {
                "family": family,
                "coordinate_count": counts[family],
                "force_constant": entry.force_constant,
                "resolved_force_constant_min": min(resolved) if resolved else entry.force_constant,
                "resolved_force_constant_max": max(resolved) if resolved else entry.force_constant,
                "force_constant_unit": entry.unit,
                "equilibrium_model": entry.equilibrium_model,
                "equilibrium_value": entry.equilibrium_value,
                "equilibrium_unit": entry.equilibrium_unit,
                "potential_model": entry.potential_model,
                "periodicity": entry.periodicity,
            }
        )
    chemical_typing: dict[str, object] = {
        "required_fields": (
            "atomic_number",
            "effective_atomic_number",
            "partial_charge",
            "bond_order",
        ),
        "status": "NOT_REQUESTED_FOR_FAMILY_ONLY_SEED",
    }
    if local_parameters:
        chemical_typing = {
            "required_fields": chemical_typing["required_fields"],
            "status": "COMPLETE_FROZEN_ORACLE_INPUT",
            "local_primitive_count": len(local_parameters),
            "local_parameters": local_parameters,
        }
    return diagonal, {
        "schema": DEFAULT_SONIC_FORCE_CONSTANT_ATLAS.schema,
        "name": "SH",
        "long_name": "SONIC Hessian",
        "regime": regime,
        "coordinate_kind": model.kind,
        "coordinate_count": len(components),
        "construction": "DIRECT_LOCAL_FAMILY_DIAGONAL",
        "primitive_congruence_transform": False,
        "cartesian_congruence_transform": False,
        "metric_or_pseudoinverse_transform": False,
        "gradient_evaluations": 0,
        "mixed_coordinate_count": sum(len(item) > 1 for item in components),
        "mixed_coordinate_estimator": "SUM_SQUARED_COEFFICIENTS_TIMES_FAMILY_CURVATURE",
        "torsional_curvature_model": ("N_I_TIMES_N_J_TIMES_BAKER_CENTRAL_BOND_ORDER_TYPED"),
        "torsional_curvature_uses_periodicity": False,
        "coordinate_family_weights": [
            [
                {"family": family, "squared_coefficient_weight": weight}
                for family, weight in coordinate_components
            ]
            for coordinate_components in components
        ],
        "chemical_typing": chemical_typing,
        "records": records,
    }


def _sparse_primitive_compliance_action(coefficient_matrix, primitive_constants: np.ndarray):
    """Return ``v -> C K^-1 C.T v`` and its linear-storage audit."""

    coefficients = coefficient_matrix.tocsr(copy=True)
    coefficients.sum_duplicates()
    constants = np.asarray(primitive_constants, dtype=float).reshape(-1)
    if coefficients.shape[1] != constants.size:
        raise ValueError("SH coefficient and primitive-curvature dimensions differ")
    if np.any(~np.isfinite(constants)) or np.any(constants <= 0.0):
        raise ValueError("the native SONIC Hessian requires positive primitive curvatures")
    inverse_constants = 1.0 / constants

    def apply(vector: np.ndarray) -> np.ndarray:
        values = np.asarray(vector, dtype=float).reshape(-1)
        if values.shape != (coefficients.shape[0],) or not np.all(np.isfinite(values)):
            raise ValueError("SH compliance action received an invalid SONIC covector")
        primitive_covector = coefficients.T @ values
        result = coefficients @ (inverse_constants * primitive_covector)
        result = np.asarray(result, dtype=float).reshape(-1)
        if not np.all(np.isfinite(result)):
            raise FloatingPointError("SH compliance action returned non-finite values")
        return result

    diagonal = np.asarray(
        coefficients.multiply(coefficients) @ inverse_constants,
        dtype=float,
    ).reshape(-1)
    if np.any(diagonal <= 0.0):
        raise ValueError("SH compliance operator is singular on an active SONIC row")
    return apply, {
        "schema": "matrix.link.sonic_hessian_compliance.v1",
        "construction": "DIRECT_LOCAL_PRIMITIVE_COMPLIANCE_ACTION",
        "formula": "C K^-1 C^T",
        "coordinate_count": coefficients.shape[0],
        "primitive_count": coefficients.shape[1],
        "coefficient_nonzero_count": int(coefficients.nnz),
        "stored_float_count": int(coefficients.nnz + inverse_constants.size),
        "dense_matrix_materialized": False,
        "cartesian_transform": False,
        "metric_or_pseudoinverse_transform": False,
        "gradient_evaluations": 0,
        "inverse_diagonal_min": float(np.min(diagonal)),
        "inverse_diagonal_max": float(np.max(diagonal)),
    }


def _sonic_hessian_compliance_action(
    model: OptimizerCoordinateModel,
    *,
    xyzin_path: Path | str,
    atoms: Sequence[str],
    regime: str = "MINIMUM",
    service=None,
):
    """Inverse of the admissible primitive SH, including recovery transfers."""
    from matrix_smith.primitive_hessian import build_primitive_sh, checked_inverse_action

    if regime == "MINIMUM":
        from matrix_smith.sonic_hessian import build_sonic_hessian as build_sh
    else:
        build_sh = build_primitive_sh
    sh = build_sh(
        xyzin_path,
        coordinates_angstrom=(
            np.asarray(service.reference_coordinates, dtype=float) if service is not None else None
        ),
        **(
            {"pair_error_tolerance": service.settings.initial_hessian_pair_tolerance}
            if service is not None and regime == "MINIMUM"
            else {}
        ),
    )
    if service is not None:
        reference = np.asarray(service.reference_coordinates, dtype=float).copy()
        action = sh.realize(
            lambda v: service.cartesian_step_from_optimizer(v, reference),
            lambda v: service.optimizer_covector_from_cartesian(v, reference) / ANGSTROM_TO_BOHR,
        )
    else:
        directions = np.asarray(model.directions_angstrom, dtype=float)
        if directions.shape != (len(model.labels), sh.b_matrix.shape[1]):
            raise ValueError("matrix-free SH inverse requires its coordinate service")
        action = sh.realize(lambda v: directions.T @ v, lambda v: directions @ v)
    return checked_inverse_action(action, len(model.labels)), dict(sh.audit)


def _sonic_local_primitive_compliance_action(
    model: OptimizerCoordinateModel,
    *,
    xyzin_path: Path | str,
    atoms: Sequence[str],
    regime: str = "MINIMUM",
    primitive_sh=None,
):
    """Return the sparse local inverse preconditioner for transformed SH."""

    if model.kind != "sonic" or model.sonic_definition is None:
        return None, None
    if model.sonic_from_coordinates is not None:
        return None, None

    from scipy.sparse import csr_matrix
    from matrix_smith.primitive_hessian import build_primitive_sh

    definition = model.sonic_definition
    # SH is defined once on ORACLE's elementary measurements.  In
    # particular, no RING_PUCKER_COMPONENT, BUTTERFLY, delocalized, or other
    # derived SONIC family is assigned an independent curvature here.
    source_sh = primitive_sh or build_primitive_sh(xyzin_path)
    if not all(hasattr(source_sh, attribute) for attribute in ("primitives", "curvatures")):
        # A transferred/matrix-free Cartesian Hessian operator is already the
        # authoritative physical model, but it has no elementary primitive
        # diagonal from which this optional local preconditioner can be built.
        return None, {
            "schema": "matrix.link.sonic_hessian_compliance.v1",
            "construction": "UNAVAILABLE_FOR_OPERATOR_ONLY_SH",
            "role": "PRECONDITIONER_FOR_TRANSFORMED_ORACLE_SH",
            "dense_matrix_materialized": False,
        }
    source_curvature = {
        str(primitive.identifier): float(curvature)
        for primitive, curvature in zip(
            source_sh.primitives,
            source_sh.curvatures,
            strict=True,
        )
    }
    primitive_index = {
        primitive.identifier: index for index, primitive in enumerate(definition.primitives)
    }
    try:
        primitive_constants = np.asarray(
            [source_curvature[str(primitive.identifier)] for primitive in definition.primitives],
            dtype=float,
        )
    except KeyError as exc:
        raise ValueError(
            f"SONIC primitive {exc.args[0]!r} has no ORACLE SH curvature"
        ) from exc
    gic_by_label: dict[str, object] = {}
    for gic in definition.gics:
        gic_by_label[str(gic.identifier)] = gic
        gic_by_label[str(gic.name or gic.identifier)] = gic
    row_indices: list[int] = []
    column_indices: list[int] = []
    coefficients: list[float] = []
    for row, label in enumerate(tuple(model.sonic_labels or model.labels)):
        try:
            gic = gic_by_label[str(label)]
        except KeyError as exc:
            raise ValueError(f"SH cannot resolve active SONIC {label!r}") from exc
        terms = getattr(gic, "coefficients", ()) or (
            (str(getattr(gic, "primitive_id")), 1.0),
        )
        for primitive_id, coefficient in terms:
            row_indices.append(row)
            column_indices.append(primitive_index[str(primitive_id)])
            coefficients.append(float(coefficient))
    coefficient_matrix = csr_matrix(
        (
            np.asarray(coefficients, dtype=float),
            (
                np.asarray(row_indices, dtype=np.int64),
                np.asarray(column_indices, dtype=np.int64),
            ),
        ),
        shape=(len(model.labels), len(definition.primitives)),
    )
    action, audit = _sparse_primitive_compliance_action(
        coefficient_matrix,
        primitive_constants,
    )
    return action, dict(audit, role="PRECONDITIONER_FOR_TRANSFORMED_ORACLE_SH")


def _fragment_coordinate_blocks(
    model: OptimizerCoordinateModel,
    xyzin_path: Path | str | None,
) -> tuple[tuple[int, ...], ...]:
    """Return intrafragment/interfragment SONIC coordinate blocks.

    ORACLE stores fragment membership in the frozen topology section and
    SMITH stores the primitive support of every derived SONIC.  Classifying
    that support, rather than guessing from coordinate names, keeps the
    separation valid for ordinary, cyclic, SOOP, contact, and rigid-fragment
    coordinates alike.  All one-fragment rows share the intrafragment block;
    rows whose support touches two or more fragments share the interfragment
    block.  Unclassified rows are kept in a small third block.
    """

    if xyzin_path is None or model.kind not in {"sonic", "typed_onic"}:
        return ()
    definition = model.sonic_definition
    if definition is None:
        return ()
    try:
        from matrix_chem import topology_snapshot_from_xyzin

        snapshot = topology_snapshot_from_xyzin(Path(xyzin_path))
    except (ImportError, OSError, ValueError, TypeError):
        return ()
    fragments = tuple(
        tuple(int(atom) - 1 for atom in atoms) for atoms in snapshot.get("fragments", ())
    )
    if len(fragments) <= 1:
        return ()
    atom_to_fragment: dict[int, int] = {}
    for fragment_index, atoms in enumerate(fragments):
        for atom in atoms:
            atom_to_fragment[atom] = fragment_index
    primitive_by_id = {str(primitive.identifier): primitive for primitive in definition.primitives}
    positions = {str(label): index for index, label in enumerate(model.labels)}
    blocks: dict[str, list[int]] = {"INTRA": [], "INTER": [], "OTHER": []}
    for gic in definition.gics:
        position = positions.get(str(gic.identifier))
        if position is None:
            position = positions.get(str(gic.name))
        if position is None or position < 0 or position >= len(model.labels):
            continue
        support_atoms: set[int] = set()
        coefficients = gic.coefficients or ((gic.primitive_id, 1.0),)
        for primitive_id, _weight in coefficients:
            primitive = primitive_by_id.get(str(primitive_id))
            if primitive is None:
                continue
            support_atoms.update(int(atom) - 1 for atom in primitive.atoms)
            support_atoms.update(int(atom) - 1 for atom in primitive.ref_atoms)
            support_atoms.update(int(atom) - 1 for atom in primitive.frame_atoms)
            support_atoms.update(int(atom) - 1 for atom in primitive.ref_frame_atoms)
        fragment_ids = {
            atom_to_fragment[atom] for atom in support_atoms if atom in atom_to_fragment
        }
        if len(fragment_ids) == 1:
            blocks["INTRA"].append(int(position))
        elif len(fragment_ids) >= 2:
            blocks["INTER"].append(int(position))
        else:
            blocks["OTHER"].append(int(position))
    covered = set().union(*blocks.values()) if blocks else set()
    blocks["OTHER"].extend(index for index in range(len(model.labels)) if index not in covered)
    result = tuple(
        tuple(sorted(set(indices)))
        for key in ("INTRA", "INTER", "OTHER")
        if (indices := blocks[key])
    )
    return result if len(result) >= 2 else ()


def _block_diagonal_hessian(
    hessian: np.ndarray,
    blocks: tuple[tuple[int, ...], ...],
) -> np.ndarray:
    """Remove cross-block entries while preserving each analytic SH block."""

    matrix = np.asarray(hessian, dtype=float)
    if matrix.ndim != 2 or matrix.shape[0] != matrix.shape[1]:
        raise ValueError("fragment-block Hessian must be square")
    if not blocks:
        return 0.5 * (matrix + matrix.T)
    result = np.zeros_like(matrix)
    for indices in blocks:
        result[np.ix_(indices, indices)] = matrix[np.ix_(indices, indices)]
    return 0.5 * (result + result.T)


def _block_diagonal_hessian_action(
    action: Callable[[np.ndarray], np.ndarray],
    blocks: tuple[tuple[int, ...], ...],
    dimension: int,
) -> Callable[[np.ndarray], np.ndarray]:
    """Matrix-free block projection of an analytic Hessian action."""

    masks = tuple(np.asarray(indices, dtype=int) for indices in blocks)

    def block_action(vector: np.ndarray) -> np.ndarray:
        values = np.asarray(vector, dtype=float).reshape(-1)
        if values.shape != (int(dimension),):
            raise ValueError("fragment-block Hessian action received the wrong dimension")
        result = np.zeros_like(values)
        for indices in masks:
            local = np.zeros_like(values)
            local[indices] = values[indices]
            response = np.asarray(action(local), dtype=float).reshape(-1)
            if response.shape != values.shape or not np.all(np.isfinite(response)):
                raise FloatingPointError("fragment-block Hessian action returned invalid values")
            result[indices] = response[indices]
        return result

    return block_action


def _initial_optimizer_hessian_selection(
    model: OptimizerCoordinateModel,
    settings: OptimizerSettings,
    *,
    initial_hessian: np.ndarray | None,
    atoms: Sequence[str] = (),
    coordinates_angstrom: np.ndarray | None = None,
    xyzin_path: Path | str | None = None,
) -> tuple[np.ndarray, str]:
    """Return the initial Hessian and its exact deterministic provenance."""

    if initial_hessian is None:
        if model.simple_chart_runtime is not None:
            if settings.initial_hessian_model not in {"auto", "lindh_swart_special"}:
                raise ValueError("simple charts require the exact ORACLE xTB Hessian")
            return (
                model.simple_chart_runtime.hessian(
                    coordinates_angstrom,
                    pair_error_tolerance=settings.initial_hessian_pair_tolerance,
                ),
                "oracle-xtb-anc-" + model.kind + "-congruence",
            )
        if settings.initial_hessian_model == "gfnff":
            raise ValueError(
                "the GFN-FF topology Hessian is an operator available only to "
                "matrix-free SYCART/L-BFGS with a resident GFN-FF calculator"
            )
        if (
            model.kind in {"sonic", "sycart", "typed_onic"}
            and xyzin_path is not None
            and coordinates_angstrom is not None
            and settings.initial_hessian_model
            in {"auto", "lindh_swart_special", "berny", "almloef"}
        ):
            from matrix_smith.primitive_hessian import build_primitive_sh

            new_sonic_sh = (
                model.kind in {"sonic", "typed_onic"}
                or settings.initial_hessian_pair_tolerance is not None
            ) and settings.stationary_point == "minimum"
            if new_sonic_sh:
                from matrix_smith.sonic_hessian import build_sonic_hessian as build_sh
            else:
                build_sh = build_primitive_sh
            primitive_sh = build_sh(
                xyzin_path,
                coordinates_angstrom=coordinates_angstrom,
                **(
                    {"pair_error_tolerance": settings.initial_hessian_pair_tolerance}
                    if new_sonic_sh
                    else {}
                ),
            )
            directions = np.asarray(model.directions_angstrom, dtype=float)
            if model.kind == "sonic" and model.sonic_definition is not None:
                directions = (
                    _optimizer_directions_at_geometry(
                        model, model.sonic_definition, np.asarray(coordinates_angstrom, dtype=float)
                    )
                    / ANGSTROM_TO_BOHR
                )
            return (
                _validate_optimizer_hessian(primitive_sh.dense(directions.T), len(model.labels)),
                "sonic-hessian-sh-xtb-anc-congruence"
                if new_sonic_sh
                else "sonic-hessian-sh-oracle-primitives-normalized-congruence",
            )
        if (
            model.kind in {"sonic", "typed_onic"}
            and settings.stationary_point in {"minimum", "transition_state"}
            and settings.initial_hessian_model
            in {"auto", "lindh_swart_special", "berny", "almloef"}
        ):
            raise ValueError(
                "SONIC SH requires the frozen ORACLE primitive contract; "
                "derived coordinate families do not own Hessian curvatures"
            )
        if model.kind in {"sonic", "sycart"} and atoms and coordinates_angstrom is not None:
            # A rank-one active SONIC space has no meaningful Hessian block to
            # reconstruct: its sole diagonal curvature is sufficient for the
            # first RFO step.  Use the existing force-field seed machinery,
            # transformed onto that coordinate, and avoid an unnecessary
            # complete Hessian acquisition (in particular, never route this
            # case through GDV).  This is a mathematical rank criterion, not a
            # molecule-, backend- or symmetry-specific exception.
            if model.kind == "sonic" and len(model.labels) == 1:
                almloef = _fischer_almloef_hessian(
                    model, atoms, coordinates_angstrom, xyzin_path=xyzin_path
                )
                if _initial_model_hessian_passes_audit(almloef, settings):
                    assert almloef is not None
                    return almloef, "fischer-almloef-rank-one-active-sonic-seed"
                chemical = _chemical_valence_hessian(
                    model, atoms, coordinates_angstrom, settings, xyzin_path=xyzin_path
                )
                if chemical is not None and _initial_model_hessian_passes_audit(chemical, settings):
                    return chemical, "chemical-valence-rank-one-active-sonic-seed"
            if settings.initial_hessian_model in {"auto", "lindh_swart_special"}:
                lindh_swart = _lindh_swart_special_hessian(
                    model,
                    atoms,
                    coordinates_angstrom,
                    xyzin_path=xyzin_path,
                )
                if _initial_model_hessian_passes_audit(lindh_swart, settings):
                    assert lindh_swart is not None
                    return (
                        lindh_swart,
                        "primitive-diagonal-berny-swart-oracle-atlas-block-dual",
                    )
                if model.kind == "sycart":
                    raise ValueError("Lindh--Swart-special SYCART Hessian seed failed audit")
                almloef = _fischer_almloef_hessian(
                    model, atoms, coordinates_angstrom, xyzin_path=xyzin_path
                )
                if _initial_model_hessian_passes_audit(almloef, settings):
                    assert almloef is not None
                    return almloef, "fischer-almloef-oracle-atlas-source-fallback"
                raise ValueError(
                    "Lindh--Swart-special and Fischer--Almloef SONIC Hessian seeds failed audit"
                )
            if settings.initial_hessian_model == "berny":
                berny = _berny_geometric_fragment_hessian(
                    model, atoms, coordinates_angstrom, xyzin_path=xyzin_path
                )
                if berny is None:
                    berny = _gaussian_berny_pseudobond_hessian(
                        model,
                        atoms,
                        coordinates_angstrom,
                        xyzin_path=xyzin_path,
                        require_pseudobonds=False,
                    )
                if berny is None:
                    raise ValueError("Berny Hessian needs a frozen SONIC definition")
                return berny, "berny-explicit-initial-hessian"
            if settings.initial_hessian_model == "almloef":
                almloef = _fischer_almloef_hessian(
                    model, atoms, coordinates_angstrom, xyzin_path=xyzin_path
                )
                if almloef is None:
                    raise ValueError("Fischer-Almloef Hessian needs a frozen SONIC definition")
                return almloef, "fischer-almloef-explicit-oracle-atlas-source"
            berny = _gaussian_berny_pseudobond_hessian(
                model, atoms, coordinates_angstrom, xyzin_path=xyzin_path
            )
            if berny is not None:
                return berny, "berny-pseudobond-initial-hessian"
            hybrid = _berny_geometric_fragment_hessian(
                model, atoms, coordinates_angstrom, xyzin_path=xyzin_path
            )
            if hybrid is not None:
                return hybrid, "berny-geometric-fragment-initial-hessian"
            chemical = _chemical_valence_hessian(
                model, atoms, coordinates_angstrom, settings, xyzin_path=xyzin_path
            )
            if chemical is not None:
                return chemical, "chemical-valence-initial-hessian"
        if atoms and coordinates_angstrom is not None:
            chemical = _chemical_valence_hessian(
                model, atoms, coordinates_angstrom, settings, xyzin_path=xyzin_path
            )
            if chemical is not None:
                return chemical, "chemical-valence"
        return (
            np.diag(np.maximum(np.abs(model.metric_diagonal), settings.min_abs_metric_diagonal)),
            "metric-diagonal-nonsonic-fallback",
        )
    matrix = _validate_optimizer_hessian(initial_hessian, len(model.labels))
    diagonal = np.diag(matrix).copy()
    small = np.abs(diagonal) < settings.min_abs_metric_diagonal
    if np.any(small):
        matrix = matrix.copy()
        for index in np.flatnonzero(small):
            sign = 1.0 if diagonal[index] >= 0.0 else -1.0
            matrix[index, index] = sign * settings.min_abs_metric_diagonal
    return 0.5 * (matrix + matrix.T), "caller-provided-initial-hessian"


def _initial_model_hessian_passes_audit(
    hessian: np.ndarray | None,
    settings: OptimizerSettings,
) -> bool:
    """Apply the common finite, positive-curvature and conditioning audit."""

    if hessian is None:
        return False
    matrix = np.asarray(hessian, dtype=float)
    if matrix.ndim != 2 or matrix.shape[0] != matrix.shape[1] or not np.all(np.isfinite(matrix)):
        return False
    try:
        eigenvalues = np.linalg.eigvalsh(0.5 * (matrix + matrix.T))
    except np.linalg.LinAlgError:
        return False
    if not eigenvalues.size:
        return True
    maximum = float(np.max(eigenvalues))
    minimum = float(np.min(eigenvalues))
    if minimum <= 0.0 or maximum <= 0.0:
        return False
    return bool(maximum / minimum <= settings.max_hessian_condition)


def _rebuild_optimizer_hessian_at_geometry(
    model: OptimizerCoordinateModel,
    settings: OptimizerSettings,
    previous_hessian: np.ndarray,
    *,
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    xyzin_path: Path | str | None,
) -> tuple[np.ndarray, str]:
    """Rebuild the declared chemical seed at the current geometry.

    A model reset must never manufacture a diagonal from the coordinate
    metric: the metric is not a force-constant model.  When an in-memory
    custom coordinate model has no frozen chemical definition, retaining the
    last finite physical model is the only non-invented fallback and is made
    explicit in the returned provenance string.
    """

    previous = 0.5 * (
        np.asarray(previous_hessian, dtype=float) + np.asarray(previous_hessian, dtype=float).T
    )
    try:
        rebuilt = _initial_optimizer_hessian(
            model,
            settings,
            initial_hessian=None,
            atoms=tuple(atoms),
            coordinates_angstrom=np.asarray(coordinates_angstrom, dtype=float),
            xyzin_path=xyzin_path,
        )
    except (ImportError, OSError, ValueError, np.linalg.LinAlgError):
        return previous, "canonical_seed_unavailable_previous_model_preserved"
    rebuilt = 0.5 * (np.asarray(rebuilt, dtype=float) + np.asarray(rebuilt, dtype=float).T)
    if not _stored_hessian_is_numerically_usable(rebuilt, settings):
        return previous, "canonical_seed_invalid_previous_model_preserved"
    return rebuilt, "canonical_chemical_seed_rebuilt_at_current_geometry"


def _lindh_swart_special_hessian(
    model: OptimizerCoordinateModel,
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    *,
    xyzin_path: Path | str | None,
) -> np.ndarray | None:
    """Build the diagonal primitive Lindh--Swart seed in the active chart.

    The model is defined in primitive internal coordinates.  Construct its
    diagonal there and transform it once to the active SONIC/SYCART chart;
    never assemble an intermediate Cartesian Hessian by enumerating atom
    quadruples.
    """

    if xyzin_path is None or model.kind not in {"sonic", "sycart"}:
        return None
    try:
        from matrix_smith import (
            build_primitive_b_matrix,
            read_gic_definition_from_xyzin,
        )

        active_definition = model.sonic_definition
        if model.kind == "sonic":
            if active_definition is None:
                return None
        else:
            # The authoritative physical definition is already frozen in the
            # enriched geometry.  Reconstructing it here repeated ORACLE and
            # SMITH topology/symmetry work before every optimization.
            active_definition = read_gic_definition_from_xyzin(Path(xyzin_path))
    except (ImportError, OSError, ValueError):
        return None
    source_definition = active_definition
    coords = np.asarray(coordinates_angstrom, dtype=float)
    if coords.shape != (len(atoms), 3):
        return None
    from matrix_chem.topology.elements import atomic_number

    atomic_numbers = tuple(int(atomic_number(atom) or 0) for atom in atoms)
    if model.kind == "sonic":
        primitive_by_id = {
            primitive.identifier: index
            for index, primitive in enumerate(active_definition.primitives)
        }
        try:
            curvatures = np.asarray(
                [
                    _berny_swart_primitive_curvature(
                        primitive,
                        atomic_numbers=atomic_numbers,
                        atoms=tuple(atoms),
                        coordinates_angstrom=coords,
                        definition=active_definition,
                        xyzin_path=Path(xyzin_path),
                    )
                    for primitive in active_definition.primitives
                ],
                dtype=float,
            )
            primitive_from_sonic = np.zeros(
                (len(active_definition.primitives), len(active_definition.gics)),
                dtype=float,
            )
            for coordinate_index, gic in enumerate(active_definition.gics):
                coefficients = gic.coefficients or ((gic.primitive_id, 1.0),)
                for primitive_id, coefficient in coefficients:
                    primitive_from_sonic[primitive_by_id[primitive_id], coordinate_index] = float(
                        coefficient
                    )
            if model.sonic_from_coordinates is not None:
                primitive_from_sonic = primitive_from_sonic @ np.asarray(
                    model.sonic_from_coordinates,
                    dtype=float,
                )
            elif primitive_from_sonic.shape[1] != len(model.labels):
                coordinate_by_label = {
                    str(gic.name or gic.identifier): index
                    for index, gic in enumerate(active_definition.gics)
                }
                primitive_from_sonic = primitive_from_sonic[
                    :,
                    [coordinate_by_label[label] for label in model.labels],
                ]
        except (KeyError, FloatingPointError, OSError, ValueError):
            return None
        if (
            len(curvatures) != primitive_from_sonic.shape[0]
            or not np.all(np.isfinite(curvatures))
            or np.any(curvatures <= 0.0)
        ):
            return None
        curvatures = _compact_torsion_curvatures(
            active_definition,
            curvatures,
        )
        active_hessian = _blockwise_internal_hessian(
            primitive_from_sonic.T,
            curvatures,
        )
        return _validate_optimizer_hessian(active_hessian, len(model.labels))
    try:
        primitive_indices = tuple(range(len(source_definition.primitives)))
        curvatures = np.asarray(
            [
                _berny_swart_primitive_curvature(
                    primitive,
                    atomic_numbers=atomic_numbers,
                    atoms=tuple(atoms),
                    coordinates_angstrom=coords,
                    definition=source_definition,
                    xyzin_path=Path(xyzin_path),
                )
                for primitive in source_definition.primitives
            ],
            dtype=float,
        )
        all_primitive_b = np.asarray(
            build_primitive_b_matrix(
                source_definition,
                coordinates_angstrom=coords,
            ).rows,
            dtype=float,
        )
    except (FloatingPointError, OSError, ValueError):
        return None
    primitive_b = all_primitive_b[np.asarray(primitive_indices, dtype=int)]
    if (
        primitive_b.shape != (len(curvatures), coords.size)
        or not np.all(np.isfinite(curvatures))
        or np.any(curvatures <= 0.0)
    ):
        return None
    extra_torsion_b, extra_torsion_curvatures = _missing_redundant_torsion_terms(
        source_definition,
        coords,
        {index: curvature for index, curvature in enumerate(curvatures)},
    )
    active_directions_bohr = np.asarray(model.directions_angstrom, dtype=float) * ANGSTROM_TO_BOHR
    active_directions_angstrom = active_directions_bohr / ANGSTROM_TO_BOHR
    primitive_from_active = primitive_b @ active_directions_angstrom.T
    active_hessian = primitive_from_active.T @ (curvatures[:, None] * primitive_from_active)
    if len(extra_torsion_curvatures):
        extra_from_active = extra_torsion_b @ active_directions_angstrom.T
        active_hessian += extra_from_active.T @ (
            extra_torsion_curvatures[:, None] * extra_from_active
        )
    return _validate_optimizer_hessian(active_hessian, len(model.labels))


def _sycart_preconditioner_epoch(
    iteration: int,
    *,
    microcycle_length: int = SYCART_PRECONDITIONER_MICROCYCLE_LENGTH,
) -> int:
    """Return the ANC-style SYCART basis epoch for a one-based iteration."""

    step = int(iteration)
    length = int(microcycle_length)
    if step <= 0 or length <= 0:
        raise ValueError("SYCART iteration and microcycle length must be positive")
    return (step - 1) // length


def _delocalized_chart_condition_check_due(
    iteration: int,
    *,
    last_check: int,
    microcycle_length: int = DELOCALIZED_CHART_CHECK_MICROCYCLE_LENGTH,
) -> bool:
    """Schedule nonlinear DLC certification at bounded microcycle boundaries."""

    step = int(iteration)
    previous = int(last_check)
    length = int(microcycle_length)
    if step <= 0 or previous < 0 or length <= 0 or previous > step:
        raise ValueError("invalid delocalized chart condition-check schedule")
    return previous == 0 or (previous < step and step - previous >= length)


def _matrix_free_sycart_davidson_preconditioner(
    service: GeometryEvaluationService,
    model: OptimizerCoordinateModel,
    *,
    coordinates_angstrom: np.ndarray | None = None,
    refresh_epoch: int = 0,
    source_iteration: int = 0,
    initial_ritz_vectors: np.ndarray | None = None,
):
    """Build one analytic sparse model inverse for a SYCART microcycle."""

    construction_started = time.perf_counter()

    runtime = model.sycart_matrix_free_runtime
    if runtime is None:
        return None, None
    if service.settings.initial_hessian_pair_tolerance is not None:
        from matrix_oracle import build_initial_hessian
        from .xtb_preconditioner import xtb_davidson_preconditioner

        source = build_initial_hessian(
            service.xyzin_path,
            coordinates_angstrom=(
                service.reference_coordinates
                if coordinates_angstrom is None
                else coordinates_angstrom
            ),
            pair_error_tolerance=service.settings.initial_hessian_pair_tolerance,
        )
        inverse, audit = xtb_davidson_preconditioner(
            source, runtime, initial_vectors=initial_ritz_vectors
        )
        audit.update(
            refresh_epoch=int(refresh_epoch),
            source_iteration=int(source_iteration),
            microcycle_length=SYCART_PRECONDITIONER_MICROCYCLE_LENGTH,
        )
        return inverse, audit
    from matrix_smith import (
        GICForgeContractError,
        compiled_gic_primitive_csr,
        read_gic_definition_from_xyzin,
    )
    from .sycart_matrix_free import (
        ProjectedPrimitiveHessianOperator,
        davidson_inverse_preconditioner,
    )

    primitive_sh = None
    try:
        if getattr(service, "_gfnff_session", None) is None:
            from types import SimpleNamespace
            from matrix_smith.primitive_hessian import build_primitive_sh

            primitive_sh = build_primitive_sh(
                service.xyzin_path,
                coordinates_angstrom=service.reference_coordinates
                if coordinates_angstrom is None
                else coordinates_angstrom,
                simple_optimizer_model=True,
            )
            definition = SimpleNamespace(
                primitives=primitive_sh.primitives,
                reference_coordinates_angstrom=service.reference_coordinates,
            )
        else:
            definition = read_gic_definition_from_xyzin(service.xyzin_path)
    except GICForgeContractError:
        # A failed SONIC contract must not force an isotropic Cartesian seed.
        # Re-perceive the current geometry through ORACLE and retain only the
        # elementary R/A/L/D primitives for the SYCART fallback.  This is the
        # intended SIMPLE_PRIMITIVES path for distorted or uncertified charts;
        # it never fabricates a SONIC definition.
        try:
            from matrix_oracle import analyze_structure

            simple_path = (
                Path(service.run_dir) / "sycart_simple_primitives" / "oracle.xyzin"
            )
            analyze_structure(
                Path(service.xyzin_path),
                simple_path,
                source_kind="xyz",
                validate=False,
                cartesian_symmetrization="retain",
            )
            from matrix_oracle import write_oracle_sonic_contract_from_xyzin

            write_oracle_sonic_contract_from_xyzin(
                simple_path,
                primitive_mode="SIMPLE_PRIMITIVES",
            )
            primitive_sh = build_primitive_sh(
                simple_path,
                coordinates_angstrom=(
                    service.reference_coordinates
                    if coordinates_angstrom is None
                    else coordinates_angstrom
                ),
                simple_optimizer_model=True,
            )
            definition = SimpleNamespace(
                primitives=primitive_sh.primitives,
                reference_coordinates_angstrom=service.reference_coordinates,
            )
        except Exception:
            from matrix_core import read_sectioned_lines, section_content

            if section_content(read_sectioned_lines(service.xyzin_path), "ORACLE_SONIC_CONTRACT"):
                raise  # A failed SIMPLE_PRIMITIVES perception is a hard error.
            return None, {
                "schema": "matrix.link.sycart_davidson_preconditioner.v1",
                "microcycle_length": SYCART_PRECONDITIONER_MICROCYCLE_LENGTH,
                "refresh_epoch": int(refresh_epoch),
                "source_iteration": int(source_iteration),
                "cartesian_dimension": runtime.cartesian_dimension,
                "active_rank": runtime.active_rank,
                "curvature_source": "ISOTROPIC_CARTESIAN_DIAGONAL_NO_CERTIFIED_TOPOLOGY",
                "baseline_inverse": 1.0,
                "dense_matrix_materialized": False,
                "initial_hessian_uses_gradients": False,
            }
    coordinates = np.asarray(
        service.reference_coordinates if coordinates_angstrom is None else coordinates_angstrom,
        dtype=float,
    )
    if coordinates.shape != service.reference_coordinates.shape or not np.all(
        np.isfinite(coordinates)
    ):
        raise ValueError("SYCART preconditioner refresh geometry is invalid")
    gfnff_session = getattr(service, "_gfnff_session", None)
    if service.settings.initial_hessian_model == "gfnff" and gfnff_session is None:
        raise ValueError("initial_hessian_model=gfnff requires the resident GFN-FF backend")
    if gfnff_session is not None:
        if gfnff_session.topology_curvatures is None:
            raise ValueError(
                "resident GFN-FF did not provide topology curvatures for the initial Hessian"
            )
        curvatures, curvature_matches = gfnff_session.topology_curvatures.primitive_curvatures(
            definition.primitives,
            coordinates,
        )
        curvature_source = "GFNFF_TOPOLOGY_LOCAL_ANALYTIC_CURVATURES"
    else:
        assert primitive_sh is not None
        curvatures = primitive_sh.curvatures
        curvature_matches = {}
        curvature_source = "SH_ORACLE_PRIMITIVES_NORMALIZED"
    if gfnff_session is not None or primitive_sh is not None:
        # The GFN-FF torsional curvature above already sums every explicit
        # outer-atom pair around a central bond.  Adding the generic missing
        # torsion expansion would count the n_i*n_j multiplicity twice.
        additions = ()
        extra_curvatures = np.zeros(0, dtype=float)
    else:
        additions = _missing_redundant_torsion_primitives(
            definition,
            {index: curvature for index, curvature in enumerate(curvatures)},
        )
        extra_curvatures = np.asarray(
            [curvature for _primitive, curvature in additions],
            dtype=float,
        )
    combined_curvatures = np.concatenate(
        (curvatures, np.asarray(extra_curvatures, dtype=float).reshape(-1))
    )
    combined_primitives = (
        *definition.primitives,
        *(primitive for primitive, _curvature in additions),
    )
    compiled_primitives = tuple(
        replace(primitive, function="R")
        if str(getattr(primitive, "function", "")).upper() in {"IR", "IR3", "ER"}
        else primitive
        for primitive in combined_primitives
    )
    compiled_csr = compiled_gic_primitive_csr(
        compiled_primitives,
        coordinates,
        reference_coords=np.asarray(definition.reference_coordinates_angstrom, dtype=float),
    )
    if compiled_csr is None:
        raise RuntimeError(
            "the complete compiled SMITH primitive atlas is required for periodic "
            "matrix-free SYCART preconditioner reconstruction"
        )
    from scipy.sparse import csr_matrix

    _primitive_values, data, indices, indptr = compiled_csr
    csr = csr_matrix(
        (data, indices, indptr),
        shape=(len(combined_primitives), coordinates.size),
        copy=False,
    )
    operator = ProjectedPrimitiveHessianOperator(
        runtime=runtime,
        b_matrix=None,
        curvatures=combined_curvatures,
        csr_matrix=csr,
    )
    primitive_row_count = csr.shape[0]
    primitive_nnz = csr.nnz
    primitive_rebuild_backend = "ORACLE_COMPILED_COMPLETE_SMITH_CSR"
    attempted_preconditioner = davidson_inverse_preconditioner(
        operator.matvec,
        runtime.project,
        dimension=runtime.cartesian_dimension,
        active_rank=runtime.active_rank,
        roots=min(12, runtime.active_rank),
        maximum_iterations=SYCART_DAVIDSON_MAXIMUM_ITERATIONS,
        eigenvalue_floor=SYCART_MINIMUM_HESSIAN_EIGENVALUE_FLOOR,
        baseline_curvature=operator.baseline_curvature,
        initial_vectors=initial_ritz_vectors,
    )
    # Davidson is deliberately bounded because this is a preconditioner, not
    # an eigenspectrum calculation.  Its Ritz vectors remain useful deflation
    # directions when the residual tolerance is not reached: the inverse
    # action still applies the analytic Berny--Swart operator through the
    # residual-controlled Krylov solve.  Discarding the bounded Ritz space was
    # observed to degrade the GFN-FF/SYCART iteration count substantially.
    preconditioner = attempted_preconditioner
    fallback = (
        "NONE"
        if attempted_preconditioner.converged
        else "BOUNDED_APPROXIMATE_RITZ_PLUS_MODEL_HESSIAN_KRYLOV"
    )
    audit = {
        "schema": "matrix.link.sycart_davidson_preconditioner.v1",
        "microcycle_length": SYCART_PRECONDITIONER_MICROCYCLE_LENGTH,
        "refresh_epoch": int(refresh_epoch),
        "source_iteration": int(source_iteration),
        "reference_geometry_sha256": hashlib.sha256(
            np.ascontiguousarray(coordinates, dtype=np.float64).tobytes()
        ).hexdigest(),
        "cartesian_dimension": runtime.cartesian_dimension,
        "active_rank": runtime.active_rank,
        "symmetry_operation_count": len(runtime.rotations),
        "external_mode_count": runtime.external_rows.shape[0],
        "primitive_row_count": primitive_row_count,
        "primitive_nnz": primitive_nnz,
        "primitive_rebuild_backend": primitive_rebuild_backend,
        "curvature_source": curvature_source,
        "primitive_sh": None if primitive_sh is None else primitive_sh.audit,
        "gfnff_curvature_matches": curvature_matches,
        "gfnff_torsion_multiplicity": (
            "SUMMED_ON_CENTRAL_BOND_NO_REDUNDANT_EXPANSION"
            if gfnff_session is not None
            else "NOT_APPLICABLE"
        ),
        "stored_value_count": operator.stored_value_count,
        "davidson_requested_roots": min(12, runtime.active_rank),
        "davidson_seeded_roots": (
            0 if initial_ritz_vectors is None else int(np.asarray(initial_ritz_vectors).shape[1])
        ),
        "davidson_retained_roots": int(preconditioner.eigenvalues.size),
        "davidson_iterations": attempted_preconditioner.iterations,
        "davidson_maximum_iterations": SYCART_DAVIDSON_MAXIMUM_ITERATIONS,
        "davidson_converged": attempted_preconditioner.converged,
        "davidson_attempted_eigenvalues": (attempted_preconditioner.eigenvalues.tolist()),
        "davidson_fallback": fallback,
        "baseline_inverse": preconditioner.baseline_inverse,
        "hessian_action": "P_Btranspose_K_B_P",
        "initial_hessian_uses_gradients": False,
        "construction_wall_seconds": time.perf_counter() - construction_started,
    }
    return preconditioner, audit


def _blockwise_internal_hessian(
    coordinate_from_primitive: np.ndarray,
    primitive_curvatures: np.ndarray,
) -> np.ndarray:
    """Combine a primitive diagonal into independent internal blocks.

    For ``dq = C dp`` and primitive ``K``, elimination of redundant primitive
    displacements gives ``Hq = (C K^-1 C.T)^-1``.  Rows coupled through a
    shared primitive are solved together; unrelated blocks never enter a
    global inverse or any Cartesian representation.
    """

    coefficients = np.asarray(coordinate_from_primitive, dtype=float)
    if coefficients.ndim != 2:
        raise ValueError("coordinate/primitive coefficient map must be a matrix")
    ncoord, nprimitive = coefficients.shape
    curvatures = np.asarray(primitive_curvatures, dtype=float).reshape(-1)
    if curvatures.shape != (nprimitive,) or np.any(curvatures <= 0.0):
        raise ValueError("primitive curvature diagonal is incompatible")
    primitive_rows: dict[int, list[int]] = {}
    supports: list[tuple[int, ...]] = []
    for row in range(ncoord):
        support = tuple(int(index) for index in np.flatnonzero(coefficients[row]))
        if not support:
            raise ValueError("internal coordinate has no primitive support")
        supports.append(support)
        for primitive in support:
            primitive_rows.setdefault(primitive, []).append(row)
    remaining = set(range(ncoord))
    blocks: list[tuple[int, ...]] = []
    while remaining:
        pending = [min(remaining)]
        component: set[int] = set()
        while pending:
            row = pending.pop()
            if row in component:
                continue
            component.add(row)
            remaining.discard(row)
            for primitive in supports[row]:
                pending.extend(
                    candidate
                    for candidate in primitive_rows[primitive]
                    if candidate not in component
                )
        blocks.append(tuple(sorted(component)))
    hessian = np.zeros((ncoord, ncoord), dtype=float)
    for rows in blocks:
        columns = tuple(sorted({column for row in rows for column in supports[row]}))
        block = coefficients[np.ix_(rows, columns)]
        compliance = (block / curvatures[np.asarray(columns, dtype=int)]) @ block.T
        hessian[np.ix_(rows, rows)] = np.linalg.solve(
            compliance,
            np.eye(len(rows)),
        )
    return hessian


def _compact_torsion_curvatures(
    definition: object,
    primitive_curvatures: np.ndarray,
) -> np.ndarray:
    """Preserve redundant Berny torsion weight in a compact SONIC chart.

    Berny's primitive diagonal contains every proper dihedral about a bonded
    atom pair.  SMITH deliberately retains one representative for the same
    central-bond torsion.  All of those redundant dihedrals have unit response
    to a rigid rotation about that bond, so their diagonal force constants add
    exactly in the compact torsional mode.  Count that multiplicity from the
    primitive bond graph; no Wilson rows or Cartesian intermediate are needed.
    """

    values = np.asarray(primitive_curvatures, dtype=float).reshape(-1).copy()
    primitives = tuple(getattr(definition, "primitives", ()))
    if values.shape != (len(primitives),):
        raise ValueError("primitive curvature diagonal is incompatible")
    pseudo_bonds = {
        tuple(sorted((int(left), int(right))))
        for left, right in getattr(definition, "pseudo_bonds", ())
    }
    adjacency: dict[int, set[int]] = {}
    for primitive in primitives:
        if str(getattr(primitive, "function", "")).upper() != "R":
            continue
        atoms = tuple(int(atom) for atom in getattr(primitive, "atoms", ()))
        if len(atoms) != 2 or tuple(sorted(atoms)) in pseudo_bonds:
            continue
        left, right = atoms
        adjacency.setdefault(left, set()).add(right)
        adjacency.setdefault(right, set()).add(left)
    torsions_by_bond: dict[tuple[int, int], list[int]] = {}
    for index, primitive in enumerate(primitives):
        if (
            str(getattr(primitive, "function", "")).upper() != "D"
            or str(getattr(primitive, "family", "")).upper() != "TORSION"
        ):
            continue
        atoms = tuple(int(atom) for atom in getattr(primitive, "atoms", ()))
        if len(atoms) != 4:
            continue
        bond = tuple(sorted((atoms[1], atoms[2])))
        if bond in pseudo_bonds:
            continue
        torsions_by_bond.setdefault(bond, []).append(index)
    for (left, right), indices in torsions_by_bond.items():
        multiplicity = len(adjacency.get(left, set()).difference({right})) * len(
            adjacency.get(right, set()).difference({left})
        )
        if multiplicity <= len(indices):
            continue
        scale = float(multiplicity) / float(len(indices))
        values[np.asarray(indices, dtype=int)] *= scale
    return values


def _center_interaction_lindh_valence_pairs(
    xyzin_path: Path,
) -> tuple[tuple[int, int], ...]:
    """Return atom spokes replaced by declared center-based curvature."""

    try:
        from matrix_fragments import read_interaction_center_definition

        definition = read_interaction_center_definition(Path(xyzin_path))
    except (ImportError, OSError, ValueError):
        return ()
    centers = {str(center.identifier): center for center in getattr(definition, "centers", ())}
    pairs: set[tuple[int, int]] = set()
    for interaction in getattr(definition, "interactions", ()):
        kind = str(getattr(interaction, "kind", "")).upper()
        if not (
            kind.startswith("METAL_ETA")
            or kind
            in {
                "ATOM_BOND_CENTER",
                "ATOM_RING_CENTER",
                "ATOM_HAPTIC_CENTER",
            }
        ):
            continue
        center = centers.get(str(getattr(interaction, "center_id", "")))
        if center is None:
            continue
        center_kind = str(getattr(center, "kind", "")).upper()
        if center_kind not in {"BOND_CENTER", "RING_CENTER", "HAPTIC_CENTER"}:
            continue
        atom = int(getattr(interaction, "atom")) - 1
        for member in getattr(center, "atoms", ()):
            donor = int(member) - 1
            if atom != donor:
                pairs.add(tuple(sorted((atom, donor))))
    return tuple(sorted(pairs))


def _is_swart_special_primitive(primitive: object, *, definition: object) -> bool:
    """Select coordinates attached to SMITH's declared special graph."""

    from matrix_smith import SPECIAL_REDUCTION_CLASS, primitive_reduction_class

    family = str(getattr(primitive, "family", ""))
    if primitive_reduction_class(family) == SPECIAL_REDUCTION_CLASS:
        return True
    pseudo_bonds = {
        tuple(sorted((int(left), int(right))))
        for left, right in getattr(definition, "pseudo_bonds", ())
    }
    if not pseudo_bonds:
        return False
    support = {
        int(atom)
        for attribute in ("atoms", "ref_atoms", "frame_atoms", "ref_frame_atoms")
        for atom in getattr(primitive, attribute, ())
    }
    return any(left in support and right in support for left, right in pseudo_bonds)


def _berny_swart_primitive_curvature(
    primitive: object,
    *,
    atomic_numbers: Sequence[int],
    atoms: tuple[str, ...],
    coordinates_angstrom: np.ndarray,
    definition: object,
    xyzin_path: Path,
) -> float:
    """Return the common primitive-diagonal Berny/Swart seed curvature."""

    function = str(getattr(primitive, "function", "")).upper()
    if function == "H" or (
        function in {"R", "A", "L", "D", "U", "IMPD"}
        and not _is_swart_special_primitive(primitive, definition=definition)
    ):
        return _gaussian_gredfc_primitive_curvature(
            primitive,
            atomic_numbers,
            np.asarray(coordinates_angstrom, dtype=float),
        )
    curvature = _swart_lindh_primitive_curvature(
        primitive,
        atoms=atoms,
        coordinates_angstrom=coordinates_angstrom,
        definition=definition,
        xyzin_path=xyzin_path,
    )
    function = str(getattr(primitive, "function", "")).upper()
    if function in {"IR", "IR3", "ER"} and len(getattr(primitive, "atoms", ())) == 2:
        i, j = (int(atom) - 1 for atom in primitive.atoms)
        distance = float(
            np.linalg.norm(
                np.asarray(coordinates_angstrom)[i] - np.asarray(coordinates_angstrom)[j]
            )
        )
        if function == "IR":
            curvature *= distance**-4
        elif function == "IR3":
            curvature *= distance**-8
        else:
            curvature *= math.exp(-2.0 * distance)
    return curvature


def _swart_lindh_primitive_curvature(
    primitive: object,
    *,
    atoms: tuple[str, ...],
    coordinates_angstrom: np.ndarray,
    definition: object,
    xyzin_path: Path,
) -> float:
    """Return one Swart--Lindh source curvature in SMITH coordinate units."""

    from matrix_chem import (
        DEFAULT_SPECIAL_EDGE_EFFECTIVE_ORDER,
        swart_lindh_center_screening,
        swart_lindh_force_constant,
        swart_lindh_screening,
    )
    from matrix_chem.topology.covalent_radii import covalent_radius
    from matrix_chem.topology.elements import atomic_number

    coords = np.asarray(coordinates_angstrom, dtype=float)
    radii = tuple(
        float(covalent_radius(int(atomic_number(symbol) or 0)) or 0.75) for symbol in atoms
    )
    pseudo_bonds = {
        tuple(sorted((int(left), int(right))))
        for left, right in getattr(definition, "pseudo_bonds", ())
    }

    def screening(left: int, right: int) -> float:
        pair = tuple(sorted((int(left), int(right))))
        distance = float(np.linalg.norm(coords[left - 1] - coords[right - 1]))
        order = DEFAULT_SPECIAL_EDGE_EFFECTIVE_ORDER if pair in pseudo_bonds else 1.0
        return swart_lindh_screening(
            distance,
            radii[left - 1] + radii[right - 1],
            effective_order=order,
        )

    def basic(function: str, indices: tuple[int, ...]) -> float:
        if function == "R" and len(indices) == 2:
            return swart_lindh_force_constant("bond", (screening(*indices),)) * (
                ANGSTROM_TO_BOHR**2
            )
        if function in {"A", "L"} and len(indices) >= 3:
            left, center, right = indices[:3]
            return swart_lindh_force_constant(
                "angle",
                (screening(left, center), screening(center, right)),
            )
        if function == "D" and len(indices) >= 4:
            first, second, third, fourth = indices[:4]
            return swart_lindh_force_constant(
                "dihedral",
                (
                    screening(first, second),
                    screening(second, third),
                    screening(third, fourth),
                ),
            )
        if function in {"U", "IMPD"} and len(indices) == 4:
            center, first, second, third = indices
            return swart_lindh_force_constant(
                "improper",
                (
                    screening(center, first),
                    screening(center, second),
                    screening(center, third),
                ),
            )
        raise ValueError(f"unsupported Swart--Lindh primitive {function}/{indices}")

    function = str(getattr(primitive, "function", "")).upper()
    indices = tuple(int(index) for index in getattr(primitive, "atoms", ()))
    if function in {"R", "A", "L", "D", "U", "IMPD"}:
        return basic(function, indices)
    if function in {"IR", "IR3", "ER"} and len(indices) == 2:
        # Radial reparameterizations retain the underlying bond curvature;
        # their analytic Jacobian is handled by the coordinate B row.
        return basic("R", indices)
    if function == "RPCB":
        return float(
            sum(
                coefficient * coefficient * basic("A", component)
                for coefficient, component in _encoded_component_terms(
                    getattr(primitive, "refs", ()), arity=3
                )
            )
        )
    if function == "RPCK":
        return float(
            sum(
                coefficient * coefficient * basic("D", component)
                for coefficient, component in _encoded_component_terms(
                    getattr(primitive, "refs", ()), arity=4
                )
            )
        )

    special_order = _swart_lindh_special_effective_order(
        primitive,
        xyzin_path=xyzin_path,
        default=DEFAULT_SPECIAL_EDGE_EFFECTIVE_ORDER,
    )
    special_screening = swart_lindh_center_screening(effective_order=special_order)
    if function in {"FC_DIST", "FCA_DIST", "CENTER_ATOM_DIST"}:
        return swart_lindh_force_constant("bond", (special_screening,)) * (ANGSTROM_TO_BOHR**2)
    if function == "FTRANS":
        # Preserve the established geomeTRIC/LINK translation scale while
        # allowing the declared special-edge order to tune weak/strong cases.
        return 0.025 * special_order / DEFAULT_SPECIAL_EDGE_EFFECTIVE_ORDER * ANGSTROM_TO_BOHR**2
    if function == "FROT":
        return 0.025 * special_order / DEFAULT_SPECIAL_EDGE_EFFECTIVE_ORDER
    raise ValueError(f"unsupported Swart--Lindh primitive function {function!r}")


def _swart_lindh_special_effective_order(
    primitive: object,
    *,
    xyzin_path: Path,
    default: float,
) -> float:
    """Resolve an explicit center order, otherwise return the frozen default."""

    try:
        from matrix_fragments import read_interaction_center_definition

        interaction_definition = read_interaction_center_definition(xyzin_path)
    except (ImportError, OSError, ValueError):
        return float(default)
    refs = tuple(str(item) for item in getattr(primitive, "refs", ()))
    center_id = refs[0] if refs else ""
    exact = tuple(
        float(getattr(interaction, "effective_order", default))
        for interaction in getattr(interaction_definition, "interactions", ())
        if str(getattr(interaction, "center_id", "")) == center_id
    )
    if exact:
        return float(max(exact))
    haptic = tuple(
        float(getattr(interaction, "effective_order", default))
        for interaction in getattr(interaction_definition, "interactions", ())
        if str(getattr(interaction, "kind", "")).upper().startswith("METAL_ETA")
        or str(getattr(interaction, "kind", "")).upper() == "ATOM_RING_CENTER"
    )
    return float(np.exp(np.mean(np.log(haptic)))) if haptic else float(default)


def _point_group_average_cartesian_hessian(
    hessian: np.ndarray,
    *,
    operations: tuple[object, ...],
    natoms: int,
) -> np.ndarray:
    """Project a Cartesian quadratic form onto the frozen point group."""

    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    if len(operations) <= 1:
        return matrix
    transformed: list[np.ndarray] = []
    for operation in operations:
        rotation = np.asarray(getattr(operation, "rotation"), dtype=float)
        permutation = tuple(int(item) for item in getattr(operation, "permutation"))
        cartesian = np.zeros((3 * natoms, 3 * natoms), dtype=float)
        for source_index, target_atom in enumerate(permutation):
            target_index = target_atom - 1
            cartesian[
                3 * source_index : 3 * source_index + 3,
                3 * target_index : 3 * target_index + 3,
            ] = rotation
        transformed.append(cartesian.T @ matrix @ cartesian)
    averaged = np.mean(np.stack(transformed), axis=0)
    return 0.5 * (averaged + averaged.T)


def _point_group_average_cartesian_gradient(
    gradient: np.ndarray,
    *,
    operations: tuple[object, ...],
    natoms: int,
) -> np.ndarray:
    """Project a Cartesian covector onto the frozen totally symmetric sector."""

    vector = np.asarray(gradient, dtype=float).reshape(-1)
    if vector.size != 3 * natoms:
        raise ValueError("Cartesian gradient size does not match the molecular atom count")
    if len(operations) <= 1:
        return vector.copy()
    transformed: list[np.ndarray] = []
    for operation in operations:
        rotation = np.asarray(getattr(operation, "rotation"), dtype=float)
        permutation = tuple(int(item) for item in getattr(operation, "permutation"))
        cartesian = np.zeros((3 * natoms, 3 * natoms), dtype=float)
        for source_index, target_atom in enumerate(permutation):
            target_index = target_atom - 1
            cartesian[
                3 * source_index : 3 * source_index + 3,
                3 * target_index : 3 * target_index + 3,
            ] = rotation
        transformed.append(cartesian.T @ vector)
    return np.mean(np.stack(transformed), axis=0)


def _fischer_almloef_hessian(
    model: OptimizerCoordinateModel,
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    *,
    xyzin_path: Path | str | None,
) -> np.ndarray | None:
    """Fischer--Almloef diagonal primitive model transformed to frozen SONIC.

    T. H. Fischer and J. Almloef, J. Phys. Chem. 96 (1992) 9768--9774,
    DOI 10.1021/j100203a036. Distances and covalent radii are evaluated in
    bohr, as in the published atomic-unit parameterization.
    """

    if xyzin_path is None:
        return None
    try:
        from matrix_chem.topology.covalent_radii import covalent_radius
        from matrix_chem.topology.elements import atomic_number
        from matrix_smith import construct_gic_definition_from_xyzin

        active_definition = model.sonic_definition
        if active_definition is None:
            return None
        definition, source_atoms, _operations = construct_gic_definition_from_xyzin(
            Path(xyzin_path),
            symmetry_group=str(active_definition.point_group),
            fragment_context=_frozen_smith_fragment_context(Path(xyzin_path)),
            retain_candidate_primitives=False,
        )
    except (ImportError, OSError, ValueError):
        return None
    if tuple(source_atoms) != tuple(atoms):
        return None
    geometry_angstrom = np.asarray(coordinates_angstrom, dtype=float)
    coords = geometry_angstrom * ANGSTROM_TO_BOHR
    numbers = tuple(int(atomic_number(atom) or 0) for atom in atoms)
    radii = tuple(float(covalent_radius(z) or 0.75) * ANGSTROM_TO_BOHR for z in numbers)
    connectivity = np.zeros((len(atoms), len(atoms)), dtype=int)
    pseudo_bonds = {tuple(sorted((int(i) - 1, int(j) - 1))) for i, j in definition.pseudo_bonds}
    for primitive in definition.primitives:
        if str(primitive.function).upper() == "R" and len(primitive.atoms) == 2:
            i, j = (int(index) - 1 for index in primitive.atoms)
            connectivity[i, j] = connectivity[j, i] = 1

    def distance(i: int, j: int) -> float:
        return float(np.linalg.norm(coords[i] - coords[j]))

    def rcov(i: int, j: int) -> float:
        return radii[i] + radii[j]

    def curvature(primitive) -> float:
        function = str(primitive.function).upper()
        idx = tuple(int(index) - 1 for index in primitive.atoms)
        edges = tuple(tuple(sorted(pair)) for pair in zip(idx, idx[1:]))
        if pseudo_bonds.intersection(edges):
            return _gaussian_gredfc_primitive_curvature(
                primitive, numbers, np.asarray(coordinates_angstrom, dtype=float)
            )
        if function == "R" and len(idx) == 2:
            i, j = idx
            # Fischer--Almloef parameterizes radial curvature in Eh/bohr^2,
            # whereas frozen SMITH/LINK stretch coordinates are in angstrom.
            # Apply the exact Hessian congruence dq_bohr/dq_angstrom squared.
            return 0.3601 * math.exp(-1.944 * (distance(i, j) - rcov(i, j))) * ANGSTROM_TO_BOHR**2
        if function in {"A", "L"} and len(idx) >= 3:
            i, j, k = idx[:3]
            return 0.089 + 0.11 * (rcov(i, j) * rcov(j, k)) ** 0.42 * math.exp(
                -0.44 * (distance(i, j) + distance(j, k) - rcov(i, j) - rcov(j, k))
            )
        if function in {"D", "IMPD"} and len(idx) >= 4:
            _i, j, k, _l = idx[:4]
            degree = max(int(connectivity[j].sum() + connectivity[k].sum() - 2), 1)
            return 0.0015 + 14.0 * degree**0.57 / (distance(j, k) * rcov(j, k)) ** 4 * math.exp(
                -2.85 * (distance(j, k) - rcov(j, k))
            )
        if function == "U" and len(idx) == 4:
            center, left, right, out = idx
            u = coords[out] - coords[center]
            v = coords[left] - coords[center]
            w = coords[right] - coords[center]
            normal = np.cross(v, w)
            sine = float(
                np.dot(u, normal) / max(np.linalg.norm(u) * np.linalg.norm(normal), 1.0e-15)
            )
            value = -math.asin(float(np.clip(sine, -1.0, 1.0)))
            return 0.0025 + 0.0061 * (rcov(center, left) * rcov(center, right)) ** 0.80 * math.cos(
                value
            ) ** 4 * math.exp(-3.0 * (distance(center, out) - rcov(center, out)))
        if function == "RPCB":
            from types import SimpleNamespace

            return float(
                sum(
                    coefficient
                    * coefficient
                    * curvature(SimpleNamespace(function="A", atoms=component))
                    for coefficient, component in _encoded_component_terms(
                        getattr(primitive, "refs", ()), arity=3
                    )
                )
            )
        if function == "RPCK":
            from types import SimpleNamespace

            return float(
                sum(
                    coefficient
                    * coefficient
                    * curvature(SimpleNamespace(function="D", atoms=component))
                    for coefficient, component in _encoded_component_terms(
                        getattr(primitive, "refs", ()), arity=4
                    )
                )
            )
        if function == "FTRANS":
            return 0.025 * ANGSTROM_TO_BOHR**2
        if function == "FROT":
            return 0.025
        if function in {"FC_DIST", "FCA_DIST", "CENTER_ATOM_DIST"}:
            return 0.05 * ANGSTROM_TO_BOHR**2
        raise ValueError(f"Fischer-Almloef has no primitive assignment for {primitive.function}")

    curvatures = np.asarray(
        [curvature(primitive) for primitive in definition.primitives],
        dtype=float,
    )
    return _primitive_diagonal_hessian_to_active(
        model,
        definition,
        curvatures,
        coordinates_angstrom=geometry_angstrom,
    )


def _frozen_smith_fragment_context(xyzin_path: Path) -> str:
    """Translate ORACLE's frozen task regime into SMITH's construction context."""

    from matrix_chem import (
        ATLAS_TASK_EXPLORATION,
        ATLAS_TASK_MINIMUM,
        ATLAS_TASK_TRANSITION_STATE,
        read_oracle_coordinate_atlas_contract,
    )

    task_regime = read_oracle_coordinate_atlas_contract(xyzin_path).task_regime
    if task_regime == ATLAS_TASK_MINIMUM:
        return "minimum"
    if task_regime == ATLAS_TASK_EXPLORATION:
        return "exploration"
    if task_regime == ATLAS_TASK_TRANSITION_STATE:
        return "transition_state"
    raise ValueError(f"unsupported frozen ORACLE task regime: {task_regime}")


def _gaussian_berny_pseudobond_hessian(
    model: OptimizerCoordinateModel,
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    *,
    xyzin_path: Path | str | None,
    require_pseudobonds: bool = True,
) -> np.ndarray | None:
    """Transform Gaussian GRedFC's pseudobond primitive Hessian into SONIC."""

    if xyzin_path is None:
        return None
    try:
        from matrix_chem.topology.elements import atomic_number
        from matrix_smith import read_gic_definition_from_xyzin

        definition = read_gic_definition_from_xyzin(Path(xyzin_path))
    except (ImportError, OSError, ValueError):
        return None
    if require_pseudobonds and definition.fragment_mode != "PSEUDO_BONDS":
        return None
    coords = np.asarray(coordinates_angstrom, dtype=float)
    if coords.shape != (len(atoms), 3):
        raise ValueError("Berny coordinates do not match the atom list")
    numbers = tuple(int(atomic_number(atom) or 0) for atom in atoms)
    primitive_curvatures = np.asarray(
        [
            _gaussian_gredfc_primitive_curvature(primitive, numbers, coords)
            for primitive in definition.primitives
        ],
        dtype=float,
    )
    return _primitive_diagonal_hessian_to_active(
        model,
        definition,
        primitive_curvatures,
        coordinates_angstrom=coords,
    )


def _primitive_from_active_matrix(
    model: OptimizerCoordinateModel,
    sonic_from_primitive: np.ndarray,
    *,
    definition: object,
    coordinates_angstrom: np.ndarray,
) -> np.ndarray:
    """Return the physical tangent map ``dq_active -> dq_primitive``.

    A coefficient pseudoinverse solves ``C dp = A dq`` in an arbitrary
    Euclidean gauge of the redundant primitive list.  The molecular geometry
    instead supplies the unique realizable change: ``dp = Bp (dx/dq) dq``.
    Both factors below come from the authoritative SMITH/LINK Wilson tangent,
    including fragment translations and exponential-map rotations.
    """

    sonic_transform = np.asarray(sonic_from_primitive, dtype=float)
    if sonic_transform.ndim != 2:
        raise ValueError("SONIC-from-primitive transform must be two-dimensional")
    active_transform = model.sonic_from_coordinates
    if active_transform is None:
        active_transform = np.eye(sonic_transform.shape[0], dtype=float)
    else:
        active_transform = np.asarray(active_transform, dtype=float)
    if active_transform.shape != (sonic_transform.shape[0], len(model.labels)):
        raise ValueError("active SONIC transform is inconsistent with primitive coordinates")
    from matrix_smith import build_primitive_b_matrix

    primitive_b = np.asarray(
        build_primitive_b_matrix(
            definition,
            coordinates_angstrom=np.asarray(coordinates_angstrom, dtype=float),
        ).rows,
        dtype=float,
    )
    cartesian_from_active_angstrom = (
        _optimizer_directions_at_geometry(
            model,
            definition,
            np.asarray(coordinates_angstrom, dtype=float),
        ).T
        / ANGSTROM_TO_BOHR
    )
    primitive_from_active = primitive_b @ cartesian_from_active_angstrom
    residual = sonic_transform @ primitive_from_active - active_transform
    tolerance = 1.0e-8 * max(1.0, float(np.linalg.norm(active_transform)))
    if float(np.linalg.norm(residual)) > tolerance:
        raise ValueError("physical primitive/SONIC tangent contract is inconsistent")
    return np.asarray(primitive_from_active, dtype=float)


def _primitive_diagonal_hessian_to_active(
    model: OptimizerCoordinateModel,
    source_definition: object,
    curvatures: np.ndarray,
    *,
    coordinates_angstrom: np.ndarray,
) -> np.ndarray:
    """Transform a source-primitive diagonal model to the active SONIC."""

    from matrix_smith import build_primitive_b_matrix

    values = np.asarray(curvatures, dtype=float).reshape(-1)
    primitive_b = np.asarray(
        build_primitive_b_matrix(
            source_definition,
            coordinates_angstrom=np.asarray(coordinates_angstrom, dtype=float),
        ).rows,
        dtype=float,
    )
    if primitive_b.shape[0] != len(values) or not np.all(np.isfinite(values)):
        raise ValueError("primitive Hessian diagonal is inconsistent with its source basis")
    if np.any(values <= 0.0):
        raise ValueError("primitive Hessian curvatures must be positive")
    active_definition = model.sonic_definition
    if active_definition is None:
        raise ValueError("primitive Hessian transformation requires a frozen active SONIC")
    cartesian_from_active_angstrom = (
        _optimizer_directions_at_geometry(
            model,
            active_definition,
            np.asarray(coordinates_angstrom, dtype=float),
        ).T
        / ANGSTROM_TO_BOHR
    )
    primitive_from_active = primitive_b @ cartesian_from_active_angstrom
    if np.linalg.matrix_rank(primitive_from_active, tol=1.0e-10) != len(model.labels):
        raise ValueError("primitive-to-active SONIC transform is rank deficient")
    hessian = primitive_from_active.T @ (values[:, None] * primitive_from_active)
    extra_b, extra_curvatures = _missing_redundant_torsion_terms(
        source_definition,
        np.asarray(coordinates_angstrom, dtype=float),
        {
            index: float(values[index])
            for index, primitive in enumerate(source_definition.primitives)
            if (
                str(getattr(primitive, "function", "")).upper() == "D"
                and str(getattr(primitive, "family", "")).upper() == "TORSION"
            )
        },
    )
    if len(extra_curvatures):
        extra_from_active = extra_b @ cartesian_from_active_angstrom
        hessian += extra_from_active.T @ (extra_curvatures[:, None] * extra_from_active)
    return _validate_optimizer_hessian(hessian, len(model.labels))


def _missing_redundant_torsion_primitives(
    definition: object,
    curvature_by_index: Mapping[int, float],
) -> tuple[tuple[object, float], ...]:
    """Materialize omitted proper dihedrals with their empirical curvature.

    Berny-like empirical models assign one force constant to every redundant
    proper dihedral around a bonded atom pair.  A compact SONIC chart can keep
    one or a few representatives.  The omitted rows must be restored before
    projection because equivalent dihedrals have distinct Cartesian Wilson
    vectors; scaling one representative preserves total weight but loses the
    associated directional coupling.

    This expands only the empirical Hessian model.  The optimized SONIC chart,
    including its C1 coordinates and torsional periodicities, is unchanged.
    """

    from matrix_smith import GICPrimitive

    primitives = tuple(getattr(definition, "primitives", ()))
    pseudo_bonds = {
        tuple(sorted((int(left), int(right))))
        for left, right in getattr(definition, "pseudo_bonds", ())
    }
    adjacency: dict[int, set[int]] = {}
    for primitive in primitives:
        if str(getattr(primitive, "function", "")).upper() != "R":
            continue
        atoms = tuple(int(atom) for atom in getattr(primitive, "atoms", ()))
        if len(atoms) != 2:
            continue
        bond = tuple(sorted(atoms))
        if bond in pseudo_bonds:
            continue
        left, right = bond
        adjacency.setdefault(left, set()).add(right)
        adjacency.setdefault(right, set()).add(left)

    torsions_by_bond: dict[tuple[int, int], list[tuple[int, tuple[int, ...]]]] = {}
    for raw_index, raw_curvature in curvature_by_index.items():
        index = int(raw_index)
        if index < 0 or index >= len(primitives):
            raise ValueError("torsional curvature index is outside the frozen definition")
        if not math.isfinite(float(raw_curvature)) or float(raw_curvature) <= 0.0:
            raise ValueError("torsional curvatures must be positive and finite")
        primitive = primitives[index]
        if (
            str(getattr(primitive, "function", "")).upper() != "D"
            or str(getattr(primitive, "family", "")).upper() != "TORSION"
        ):
            continue
        atoms = tuple(int(atom) for atom in getattr(primitive, "atoms", ()))
        if len(atoms) < 4:
            continue
        bond = tuple(sorted((atoms[1], atoms[2])))
        if bond in pseudo_bonds or bond[1] not in adjacency.get(bond[0], set()):
            continue
        canonical = min(atoms, tuple(reversed(atoms)))
        torsions_by_bond.setdefault(bond, []).append((index, canonical))

    additions: list[tuple[object, float]] = []
    for (left, right), entries in sorted(torsions_by_bond.items()):
        quartets = {
            min(
                (outer_left, left, right, outer_right),
                (outer_right, right, left, outer_left),
            )
            for outer_left in adjacency.get(left, set()).difference({right})
            for outer_right in adjacency.get(right, set()).difference({left})
            if len({outer_left, left, right, outer_right}) == 4
        }
        represented = {quartet for _index, quartet in entries}
        curvature = float(
            np.mean([float(curvature_by_index[index]) for index, _quartet in entries])
        )
        for quartet in sorted(quartets.difference(represented)):
            ordinal = len(additions) + 1
            additions.append(
                (
                    GICPrimitive(
                        identifier=f"REDUNDANT_TORSION_{ordinal:04d}",
                        name=f"REDUNDANT_TORSION_{ordinal:04d}",
                        family="TORSION",
                        function="D",
                        atoms=tuple(int(atom) for atom in quartet),
                    ),
                    curvature,
                )
            )
    return tuple(additions)


def _missing_redundant_torsion_terms(
    definition: object,
    coordinates_angstrom: np.ndarray,
    curvature_by_index: Mapping[int, float],
) -> tuple[np.ndarray, np.ndarray]:
    """Return Wilson rows and curvatures omitted by SONIC compression."""

    additions = _missing_redundant_torsion_primitives(
        definition,
        curvature_by_index,
    )
    ncart = int(np.asarray(coordinates_angstrom, dtype=float).size)
    if not additions:
        return np.zeros((0, ncart), dtype=float), np.zeros(0, dtype=float)
    from matrix_smith import build_primitive_b_matrix

    expanded_definition = replace(
        definition,
        primitives=tuple(primitive for primitive, _curvature in additions),
        gics=(),
    )
    rows = np.asarray(
        build_primitive_b_matrix(
            expanded_definition,
            coordinates_angstrom=np.asarray(coordinates_angstrom, dtype=float),
        ).rows,
        dtype=float,
    )
    curvatures = np.asarray(
        [curvature for _primitive, curvature in additions],
        dtype=float,
    )
    return rows, curvatures


def _missing_redundant_torsion_sparse_terms(
    definition: object,
    coordinates_angstrom: np.ndarray,
    curvature_by_index: Mapping[int, float],
):
    """Return omitted torsions as native sparse rows without a dense detour."""

    additions = _missing_redundant_torsion_primitives(
        definition,
        curvature_by_index,
    )
    if not additions:
        return (), np.zeros(0, dtype=float)
    from matrix_smith import build_sparse_primitive_b_matrix

    expanded_definition = replace(
        definition,
        primitives=tuple(primitive for primitive, _curvature in additions),
        gics=(),
    )
    sparse = build_sparse_primitive_b_matrix(
        expanded_definition,
        coordinates_angstrom=np.asarray(coordinates_angstrom, dtype=float),
    )
    return sparse.rows, np.asarray(
        [curvature for _primitive, curvature in additions],
        dtype=float,
    )


def _berny_geometric_fragment_hessian(
    model: OptimizerCoordinateModel,
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    *,
    xyzin_path: Path | str | None,
) -> np.ndarray | None:
    """Berny intramolecular plus geomeTRIC fragment primitive Hessian."""

    if xyzin_path is None:
        return None
    try:
        from matrix_chem.topology.elements import atomic_number
        from matrix_smith import read_gic_definition_from_xyzin

        definition = read_gic_definition_from_xyzin(Path(xyzin_path))
    except (ImportError, OSError, ValueError):
        return None
    if definition.fragment_mode != "SPECIAL_COORDINATES":
        return None
    coords = np.asarray(coordinates_angstrom, dtype=float)
    numbers = tuple(int(atomic_number(atom) or 0) for atom in atoms)
    primitive_index = {
        primitive.identifier: index for index, primitive in enumerate(definition.primitives)
    }
    curvatures: list[float] = []
    for primitive in definition.primitives:
        function = str(primitive.function).upper()
        if function == "FTRANS":
            # geomeTRIC assigns 0.05 to each absolute fragment primitive.
            # MATRIX stores q_rel=q_a-q_b rather than (q_a-q_b)/sqrt(2).
            # geomeTRIC translations are in bohr; MATRIX FTRANS is in angstrom.
            curvatures.append(0.025 * ANGSTROM_TO_BOHR**2)
        elif function == "FROT":
            # Exponential-map rotations are dimensionless angular coordinates.
            curvatures.append(0.025)
        elif function in {"FC_DIST", "FCA_DIST", "CENTER_ATOM_DIST"}:
            curvatures.append(0.05 * ANGSTROM_TO_BOHR**2)
        else:
            curvatures.append(_gaussian_gredfc_primitive_curvature(primitive, numbers, coords))
    primitive_curvatures = np.asarray(curvatures, dtype=float)
    primitive_hessian = np.diag(primitive_curvatures)
    sonic_labels = model.sonic_labels or model.labels
    sonic_transform = np.zeros((len(sonic_labels), len(definition.primitives)), dtype=float)
    for row, label in enumerate(sonic_labels):
        try:
            gic = _frozen_gic_for_active_label(definition, label)
        except ValueError as exc:
            raise ValueError(
                f"SONIC coordinate {label!r} is absent from the frozen definition"
            ) from exc
        for primitive_id, coefficient in gic.coefficients or ((gic.primitive_id, 1.0),):
            sonic_transform[row, primitive_index[primitive_id]] += float(coefficient)
    primitive_from_active = _primitive_from_active_matrix(
        model,
        sonic_transform,
        definition=definition,
        coordinates_angstrom=coords,
    )
    if np.linalg.matrix_rank(primitive_from_active, tol=1.0e-10) != len(model.labels):
        raise ValueError("primitive-to-SONIC fragment transform is rank deficient")
    hessian = primitive_from_active.T @ primitive_hessian @ primitive_from_active
    extra_b, extra_curvatures = _missing_redundant_torsion_terms(
        definition,
        coords,
        {
            index: float(primitive_curvatures[index])
            for index, primitive in enumerate(definition.primitives)
            if (
                str(getattr(primitive, "function", "")).upper() == "D"
                and str(getattr(primitive, "family", "")).upper() == "TORSION"
            )
        },
    )
    if len(extra_curvatures):
        cartesian_from_active_angstrom = (
            _optimizer_directions_at_geometry(
                model,
                definition,
                coords,
            ).T
            / ANGSTROM_TO_BOHR
        )
        extra_from_active = extra_b @ cartesian_from_active_angstrom
        hessian += extra_from_active.T @ (extra_curvatures[:, None] * extra_from_active)
    return 0.5 * (hessian + hessian.T)


def _gaussian_gredfc_primitive_curvature(
    primitive,
    atomic_numbers: Sequence[int],
    coordinates_angstrom: np.ndarray,
) -> float:
    """Literal FCStr/FCBend/FCTors assignment in Gaussian GRedFC.

    MATRIX's genuine out-of-plane angle U has no Gaussian GRedFC primitive
    force constant because Gaussian substitutes an improper dihedral.  Its
    transferable curvature is defined halfway between the Berny valence-bend
    and torsional curvatures of the same tricoordinated center.
    """

    function = str(primitive.function).upper()
    indices = tuple(int(index) - 1 for index in primitive.atoms)
    if function == "R" and len(indices) == 2:
        distance = _distance_bohr(coordinates_angstrom, indices[0], indices[1])
        return (
            _gaussian_fcstr(distance, atomic_numbers[indices[0]], atomic_numbers[indices[1]])
            * ANGSTROM_TO_BOHR**2
        )
    if function == "A" and len(indices) == 3:
        return (
            0.160 if atomic_numbers[indices[0]] == 1 or atomic_numbers[indices[2]] == 1 else 0.250
        )
    if function == "L" and len(indices) >= 3:
        central = _distance_bohr(coordinates_angstrom, indices[1], indices[2])
        return _gaussian_fctors(central, atomic_numbers[indices[1]], atomic_numbers[indices[2]])
    if function in {"D", "IMPD"} and len(indices) >= 4:
        central = _distance_bohr(coordinates_angstrom, indices[1], indices[2])
        return _gaussian_fctors(central, atomic_numbers[indices[1]], atomic_numbers[indices[2]])
    if function == "U" and len(indices) == 4:
        center, first, second, third = indices
        neighbours = (first, second, third)
        bend_curvatures = [
            0.160 if atomic_numbers[left] == 1 or atomic_numbers[right] == 1 else 0.250
            for left, right in combinations(neighbours, 2)
        ]
        torsional_curvatures = [
            _gaussian_fctors(
                _distance_bohr(coordinates_angstrom, center, neighbour),
                atomic_numbers[center],
                atomic_numbers[neighbour],
            )
            for neighbour in neighbours
        ]
        return 0.5 * (float(np.mean(bend_curvatures)) + float(np.mean(torsional_curvatures)))
    if function == "H" and len(indices) == 4:
        center, first, second, out = indices
        neighbours = (first, second, out)
        bend_curvatures = [
            0.160 if atomic_numbers[left] == 1 or atomic_numbers[right] == 1 else 0.250
            for left, right in combinations(neighbours, 2)
        ]
        torsional_curvatures = [
            _gaussian_fctors(
                _distance_bohr(coordinates_angstrom, center, neighbour),
                atomic_numbers[center],
                atomic_numbers[neighbour],
            )
            for neighbour in neighbours
        ]
        angular_curvature = 0.5 * (
            float(np.mean(bend_curvatures)) + float(np.mean(torsional_curvatures))
        )
        radius_angstrom = float(
            np.linalg.norm(coordinates_angstrom[out] - coordinates_angstrom[center])
        )
        if not np.isfinite(radius_angstrom) or radius_angstrom <= 1.0e-10:
            raise ValueError("Berny out-of-plane height has a singular center-to-atom radius")
        # H = r sin(U), so its local Berny curvature in the native
        # Hartree/angstrom^2 coordinate unit is k_U/r^2.
        return angular_curvature / (radius_angstrom * radius_angstrom)
    if function == "RPCB" and primitive.family == "PSEUDO_CYCLE_BEND":
        terms = _encoded_component_terms(primitive.refs, arity=3)
        return float(
            sum(
                coefficient
                * coefficient
                * (
                    0.160
                    if atomic_numbers[atoms[0] - 1] == 1 or atomic_numbers[atoms[2] - 1] == 1
                    else 0.250
                )
                for coefficient, atoms in terms
            )
        )
    if function == "RPCK" and primitive.family in {
        "PSEUDO_CYCLE_TORSION",
        "RING_PUCKER_COMPONENT",
    }:
        # RPCK/CHARM components are normalized linear combinations of
        # ordinary ring torsions.  The diagonal Berny seed therefore follows
        # the exact congruence sum c_i^2 k_i used for pseudo-cycle torsions;
        # no arbitrary generic fallback is needed for genuine ring puckering.
        terms = _encoded_component_terms(primitive.refs, arity=4)
        return float(
            sum(
                coefficient
                * coefficient
                * _gaussian_fctors(
                    _distance_bohr(coordinates_angstrom, atoms[1] - 1, atoms[2] - 1),
                    atomic_numbers[atoms[1] - 1],
                    atomic_numbers[atoms[2] - 1],
                )
                for coefficient, atoms in terms
            )
        )
    raise ValueError(
        f"Gaussian Berny has no exact primitive assignment for {primitive.function}/{primitive.family}"
    )


def _encoded_component_terms(
    refs: Sequence[str],
    *,
    arity: int,
) -> tuple[tuple[float, tuple[int, ...]], ...]:
    terms: list[tuple[float, tuple[int, ...]]] = []
    for ref in refs:
        coefficient_text, separator, atom_text = str(ref).partition(":")
        if not separator:
            raise ValueError(f"invalid encoded primitive component {ref!r}")
        atoms = tuple(int(value) for value in atom_text.split("-") if value)
        if len(atoms) != arity:
            raise ValueError(f"invalid {arity}-atom primitive component {ref!r}")
        terms.append((float(coefficient_text), atoms))
    if not terms:
        raise ValueError("composite primitive has no encoded components")
    return tuple(terms)


def _distance_bohr(coordinates_angstrom: np.ndarray, left: int, right: int) -> float:
    return float(
        np.linalg.norm(coordinates_angstrom[left] - coordinates_angstrom[right]) * ANGSTROM_TO_BOHR
    )


def _gaussian_fcstr(
    distance_bohr: float, left_atomic_number: int, right_atomic_number: int
) -> float:
    shifts = (
        -0.244,
        0.352,
        1.085,
        0.660,
        1.522,
        2.068,
        0.7126,
        1.4725,
        1.8238,
        2.0203,
        0.8335,
        1.6549,
        2.1164,
        2.2137,
        2.3718,
        0.9491,
        1.7190,
        2.3185,
        2.5206,
        2.5110,
        2.5,
    )

    def row(number: int) -> int:
        return (number + 13) // 8 if number <= 18 else (number + 53) // 18

    high = min(max(row(max(left_atomic_number, right_atomic_number)), 1), 6)
    low = min(max(row(min(left_atomic_number, right_atomic_number)), 1), 6)
    denominator = max((distance_bohr - shifts[high * (high - 1) // 2 + low - 1]) ** 3, 0.1)
    return max(1.734 / denominator, 1.0e-3)


def _gaussian_fctors(
    distance_bohr: float, left_atomic_number: int, right_atomic_number: int
) -> float:
    radii = (
        0.32,
        0.60,
        1.20,
        1.05,
        0.81,
        0.77,
        0.74,
        0.74,
        0.72,
        0.72,
        1.50,
        1.40,
        1.30,
        1.17,
        1.10,
        1.04,
        0.99,
        0.99,
        1.80,
        1.60,
        *([1.40] * 11),
        1.30,
        1.20,
        1.20,
        1.10,
        1.10,
    )
    left = min(max(int(left_atomic_number), 1), 36)
    right = min(max(int(right_atomic_number), 1), 36)
    overlap = (radii[left - 1] + radii[right - 1]) / 0.529 - float(distance_bohr)
    return 0.0023 + 0.07 * max(overlap, 0.0)


def _chemical_valence_hessian(
    model: OptimizerCoordinateModel,
    atoms: Sequence[str],
    coordinates_angstrom: np.ndarray,
    settings: OptimizerSettings,
    *,
    xyzin_path: Path | str | None = None,
) -> np.ndarray | None:
    coords = np.asarray(coordinates_angstrom, dtype=float)
    if coords.shape != (len(atoms), 3) or len(atoms) < 2:
        return None
    try:
        from matrix_chem.topology.covalent_radii import covalent_radius
        from matrix_chem.topology.elements import atomic_number
    except ImportError:
        return None
    ncart = coords.size
    cart_angstrom = np.eye(ncart, dtype=float) * 0.02
    numbers = [atomic_number(atom) or 0 for atom in atoms]
    bond_count = 0
    for i in range(len(atoms)):
        zi = numbers[i]
        ri = covalent_radius(zi) or 0.75
        for j in range(i + 1, len(atoms)):
            zj = numbers[j]
            rj = covalent_radius(zj) or 0.75
            delta = coords[i] - coords[j]
            distance = float(np.linalg.norm(delta))
            if distance <= 1.0e-8:
                continue
            cutoff = 1.25 * (ri + rj) + 0.20
            if distance > cutoff:
                continue
            unit = delta / distance
            stiffness = _bond_stiffness_hartree_per_angstrom2(zi, zj, distance, ri + rj)
            block = stiffness * np.outer(unit, unit)
            si = slice(3 * i, 3 * i + 3)
            sj = slice(3 * j, 3 * j + 3)
            cart_angstrom[si, si] += block
            cart_angstrom[sj, sj] += block
            cart_angstrom[si, sj] -= block
            cart_angstrom[sj, si] -= block
            bond_count += 1
    if bond_count == 0:
        return None
    # Convert Eh/A^2 to Eh/bohr^2 before using the standard Cartesian projector.
    cart_bohr = cart_angstrom / (ANGSTROM_TO_BOHR * ANGSTROM_TO_BOHR)
    projected = optimizer_hessian_from_cartesian(cart_bohr, model)
    # Complete the central-force Cartesian guess with transferable
    # Schlegel/TRIC curvatures: central springs underestimate bends and cannot
    # supply the inter-fragment rigid-body block.
    projected = projected.copy()
    for index, label in enumerate(model.labels):
        name = str(label).lower()
        if name.startswith("bend"):
            projected[index, index] = max(float(projected[index, index]), 0.160)
        elif name.startswith(("fdis", "fc_dist")):
            # The radial intermolecular coordinate is stiffer than tangential
            # sliding but remains much softer than a covalent stretch.
            projected[index, index] = max(float(projected[index, index]), 0.100)
        elif name.startswith("ftrn"):
            # MATRIX stores a relative translation (fragment minus reference),
            # so two geomeTRIC-like 0.05 primitive blocks project to 0.025.
            projected[index, index] = max(float(projected[index, index]), 0.025)
        elif name.startswith("frot"):
            projected[index, index] = max(
                float(projected[index, index]), settings.fragment_rotation_curvature or 0.025
            )
    if (
        xyzin_path is not None
        and settings.fragment_radial_curvature is not None
        and settings.fragment_tangential_curvature is not None
    ):
        projected = _apply_fragment_hessian_blocks(projected, model, coords, xyzin_path, settings)
    diagonal_floor = np.diag(np.maximum(np.diag(projected), settings.min_abs_metric_diagonal))
    if _hessian_is_usable(projected, settings):
        return projected
    return diagonal_floor


def _apply_fragment_hessian_blocks(
    hessian: np.ndarray,
    model: OptimizerCoordinateModel,
    coordinates_angstrom: np.ndarray,
    xyzin_path: Path | str,
    settings: OptimizerSettings,
) -> np.ndarray:
    """Add radial/tangential curvature in complete relative-translation blocks."""

    try:
        from matrix_smith import read_gic_definition_from_xyzin

        definition = read_gic_definition_from_xyzin(Path(xyzin_path))
    except (ImportError, OSError, ValueError):
        return hessian
    primitive_by_id = {primitive.identifier: primitive for primitive in definition.primitives}
    coordinate_position = {label: index for index, label in enumerate(model.labels)}
    groups: dict[tuple[tuple[int, ...], tuple[int, ...]], dict[int, int]] = {}
    group_reference_frames: dict[tuple[tuple[int, ...], tuple[int, ...]], tuple[int, ...]] = {}
    for gic in definition.gics:
        position = coordinate_position.get(gic.identifier, coordinate_position.get(gic.name))
        if position is None:
            continue
        coefficients = gic.coefficients or ((gic.primitive_id, 1.0),)
        if len(coefficients) != 1 or not np.isclose(float(coefficients[0][1]), 1.0):
            continue
        primitive = primitive_by_id.get(coefficients[0][0])
        if primitive is None or primitive.function != "FTRANS":
            continue
        key = (tuple(primitive.atoms), tuple(primitive.ref_atoms))
        groups.setdefault(key, {})[int(primitive.mode)] = int(position)
        ref_frame_atoms = tuple(getattr(primitive, "ref_frame_atoms", ()))
        if ref_frame_atoms:
            group_reference_frames[key] = ref_frame_atoms
    result = np.asarray(hessian, dtype=float).copy()
    coords = np.asarray(coordinates_angstrom, dtype=float)
    for (atoms, ref_atoms), modes in groups.items():
        if set(modes) != {0, 1, 2}:
            continue
        center = np.mean(coords[np.asarray(atoms, dtype=int) - 1], axis=0)
        ref_center = np.mean(coords[np.asarray(ref_atoms, dtype=int) - 1], axis=0)
        radial = center - ref_center
        norm = float(np.linalg.norm(radial))
        if norm <= 1.0e-10:
            continue
        radial /= norm
        ref_frame_atoms = group_reference_frames.get((atoms, ref_atoms), ())
        if ref_frame_atoms:
            from matrix_smith.numerics import _fragment_frame

            reference_frame = _fragment_frame(
                coords,
                ref_atoms,
                frame_atoms=ref_frame_atoms,
            )
            radial = radial @ reference_frame
        tangential_curvature = float(settings.fragment_tangential_curvature)
        radial_curvature = float(settings.fragment_radial_curvature)
        block = tangential_curvature * np.eye(3) + (
            radial_curvature - tangential_curvature
        ) * np.outer(radial, radial)
        indices = [modes[axis] for axis in range(3)]
        result[np.ix_(indices, indices)] = block
    return 0.5 * (result + result.T)


def _bond_stiffness_hartree_per_angstrom2(
    zi: int, zj: int, distance: float, covalent_sum: float
) -> float:
    if zi == 1 or zj == 1:
        base = 0.45
    elif zi in {6, 7, 8} and zj in {6, 7, 8}:
        base = 0.65
    else:
        base = 0.35
    if covalent_sum > 1.0e-8:
        base *= min(1.5, max(0.5, covalent_sum / max(distance, 1.0e-8)))
    return float(base)


def _validate_optimizer_hessian(hessian: np.ndarray, ncoord: int) -> np.ndarray:
    matrix = np.asarray(hessian, dtype=float)
    if matrix.shape != (ncoord, ncoord):
        raise ValueError(f"optimizer Hessian shape must be {(ncoord, ncoord)}, got {matrix.shape}")
    if not np.all(np.isfinite(matrix)):
        raise ValueError("optimizer Hessian contains non-finite values")
    return 0.5 * (matrix + matrix.T)


def _cache_record_to_json(evaluation: OptimizerEvaluation) -> dict[str, object]:
    return {
        "schema": OPTIMIZER_CACHE_SCHEMA,
        "chart_epoch": evaluation.chart_epoch,
        "q": np.asarray(evaluation.q, dtype=float).reshape(-1).tolist(),
        "coordinates_angstrom": np.asarray(evaluation.coordinates_angstrom, dtype=float).tolist(),
        "result": point_result_to_json(evaluation.result),
    }


def _cache_record_from_json(payload: dict[str, object]) -> OptimizerEvaluation:
    result_payload = dict(payload.get("result") or {})
    gradient = result_payload.get("gradient_hartree_per_bohr")
    hessian = result_payload.get("hessian_hartree_per_bohr2")
    backend_coordinates = result_payload.get("backend_coordinates_angstrom")
    result = PointEvaluationResult(
        point_index=int(result_payload.get("point_index", 0)),
        displacement=float(result_payload.get("displacement", 0.0)),
        energy_hartree=result_payload.get("energy_hartree"),
        gradient_hartree_per_bohr=None if gradient is None else np.asarray(gradient, dtype=float),
        hessian_hartree_per_bohr2=None if hessian is None else np.asarray(hessian, dtype=float),
        backend_coordinates_angstrom=(
            None if backend_coordinates is None else np.asarray(backend_coordinates, dtype=float)
        ),
        frame_alignment_rms_angstrom=float(result_payload.get("frame_alignment_rms_angstrom", 0.0)),
        status=str(result_payload.get("status", "completed")),
        message=str(result_payload.get("message", "")),
        source=str(result_payload.get("source", "optimizer-cache")),
        point_group=str(result_payload.get("point_group", "")),
        symmetry_projection_status=str(
            result_payload.get("symmetry_projection_status", "NOT_ANALYZED")
        ),
        symmetry_projection_max_displacement_angstrom=float(
            result_payload.get("symmetry_projection_max_displacement_angstrom", 0.0)
        ),
        symmetry_projection_rms_displacement_angstrom=float(
            result_payload.get("symmetry_projection_rms_displacement_angstrom", 0.0)
        ),
        execution=dict(result_payload.get("execution", {})),
        schema=str(result_payload.get("schema", "oracle.link.point_result.v1")),
    )
    return OptimizerEvaluation(
        q=np.asarray(payload["q"], dtype=float),
        coordinates_angstrom=np.asarray(payload["coordinates_angstrom"], dtype=float),
        result=result,
        cache_hit=False,
        chart_epoch=int(payload.get("chart_epoch", 0)),
    )


def _refine_hessian_diagonals_from_two_sided_energies(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    settings: OptimizerSettings,
    *,
    coordinate_steps: Sequence[float] | None = None,
    zero_off_diagonal: bool = False,
) -> tuple[np.ndarray, dict[str, object]]:
    """Replace Hessian diagonals and either rescale or clear the couplings."""

    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    ncoord = matrix.shape[0]
    if matrix.shape != (len(q), len(q)):
        raise ValueError("Hessian and optimizer coordinate dimensions do not match")
    if coordinate_steps is None:
        steps = np.full(
            ncoord,
            min(settings.fd_max_step, max(settings.fd_min_step, settings.fd_step)),
            dtype=float,
        )
    else:
        steps = np.asarray(coordinate_steps, dtype=float).reshape(-1)
        if steps.shape != (ncoord,) or not np.all(np.isfinite(steps)):
            raise ValueError("two-sided Hessian coordinate steps do not match the model")
        steps = np.minimum(
            settings.fd_max_step,
            np.maximum(settings.fd_min_step, np.abs(steps)),
        )
    new_diagonal = np.zeros(ncoord, dtype=float)
    extra_points = 0
    from matrix_numerics import scalar_finite_difference

    for index in range(ncoord):
        step = float(steps[index])
        plus = np.asarray(q, dtype=float).copy()
        minus = np.asarray(q, dtype=float).copy()
        plus[index] += step
        minus[index] -= step
        plus_eval = service.evaluate(
            plus, tag=f"final-hessian-plus-{index + 1}", requested_properties=("energy",)
        )
        minus_eval = service.evaluate(
            minus, tag=f"final-hessian-minus-{index + 1}", requested_properties=("energy",)
        )
        difference = scalar_finite_difference(
            current.energy_hartree,
            plus_eval.energy_hartree,
            step,
            minus_energy=minus_eval.energy_hartree,
            minus_step=step,
        )
        if difference.curvature is None:
            raise RuntimeError("two-sided curvature protocol returned no curvature")
        new_diagonal[index] = difference.curvature
        extra_points += int(not plus_eval.cache_hit) + int(not minus_eval.cache_hit)
    bprime_correction = np.zeros(ncoord, dtype=float)
    if service.coordinate_model.kind == "sonic" and current.gradient_hartree_per_bohr is not None:
        # Direct energy curvatures are second derivatives of E(q), whereas
        # the optimizer Hessian is the physical Wilson/GF curvature.  At a
        # non-stationary point the two differ by the exact g B' chain-rule
        # term.  ARCHITECT already owns the validated B' transformation;
        # using it here prevents spurious negative modal curvatures.
        bprime_hessian = optimizer_hessian_from_cartesian(
            np.zeros((current.coordinates_angstrom.size, current.coordinates_angstrom.size)),
            service.coordinate_model,
            cartesian_gradient_hartree_per_bohr=current.gradient_hartree_per_bohr,
            coordinates_angstrom=current.coordinates_angstrom,
        )
        bprime_correction = np.diag(bprime_hessian)
        new_diagonal = new_diagonal - bprime_correction
    old_diagonal = np.diag(matrix).copy()
    refined = matrix.copy()
    np.fill_diagonal(refined, new_diagonal)
    scale_factors = np.ones(ncoord, dtype=float)
    valid = (np.abs(old_diagonal) > settings.min_abs_metric_diagonal) & np.isfinite(new_diagonal)
    scale_factors[valid] = np.sqrt(
        np.minimum(
            settings.final_hessian_rescale_max**2,
            np.maximum(
                settings.final_hessian_rescale_min**2,
                np.abs(new_diagonal[valid] / old_diagonal[valid]),
            ),
        )
    )
    for left in range(ncoord):
        for right in range(left):
            refined[left, right] = refined[right, left] = (
                0.0
                if zero_off_diagonal
                else matrix[left, right] * scale_factors[left] * scale_factors[right]
            )
    refined = 0.5 * (refined + refined.T)
    return refined, {
        "performed": True,
        "steps": steps.tolist(),
        "extra_points": extra_points,
        "old_diagonal": old_diagonal.tolist(),
        "new_diagonal": new_diagonal.tolist(),
        "raw_energy_second_derivative_diagonal": ((new_diagonal + bprime_correction).tolist()),
        "b_prime_diagonal_correction": bprime_correction.tolist(),
        "rescale_factors": scale_factors.tolist(),
        "sign_changes": int(np.count_nonzero(np.signbit(old_diagonal) != np.signbit(new_diagonal))),
        "off_diagonal_policy": "zero" if zero_off_diagonal else "scaled_previous",
    }


def _advance_numerical_convergence_state(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    gradient: np.ndarray,
    fd_info: Mapping[str, object],
    hessian: np.ndarray,
    settings: OptimizerSettings,
    convergence: Mapping[str, bool],
    *,
    last_energy_change: float,
    last_cartesian_step_bohr: np.ndarray,
    selective_disabled: bool,
    final_hessian_refinement_attempted: bool,
    transition_mode_reference: TransitionModeReference | None,
) -> tuple[
    np.ndarray,
    dict[str, object],
    np.ndarray,
    OptimizerSettings,
    dict[str, bool],
    dict[str, object],
    bool,
    bool,
]:
    """Verify one-sided convergence and advance the irreversible central state."""

    active_gradient = np.asarray(gradient, dtype=float)
    active_info = dict(fd_info)
    active_hessian = np.asarray(hessian, dtype=float)
    active_settings = settings
    active_convergence = dict(convergence)
    mode = str(active_info.get("mode", ""))
    verification: dict[str, object]

    if (
        active_settings.fd_stencil_policy in {"one_sided_only", "stalled_two_sided"}
        and mode != "two-sided"
        and not active_settings.compute_final_hessian
    ):
        verification = {
            "performed": False,
            "confirmed": True,
            "reason": (
                "one_sided_only_protocol"
                if active_settings.fd_stencil_policy == "one_sided_only"
                else "one_sided_converged_without_stall"
            ),
            "gradient_policy": active_settings.fd_stencil_policy,
            "fd_two_sided_count": 0,
            "final_hessian_requested": False,
        }
        return (
            active_gradient,
            active_info,
            active_hessian,
            active_settings,
            active_convergence,
            verification,
            final_hessian_refinement_attempted,
            True,
        )

    if mode != "two-sided":
        verified_gradient, verified_info = _verify_final_numerical_gradient(
            service,
            current,
            q,
            active_hessian,
            active_settings,
            selective_disabled=selective_disabled,
        )
        verified_convergence = _gaussian_like_convergence(
            active_settings,
            last_energy_change,
            _convergence_gradient(current, verified_gradient, active_settings, service),
            last_cartesian_step_bohr,
        )
        active_gradient = verified_gradient
        active_info = dict(verified_info)
        active_convergence = verified_convergence
        agreement = bool(all(verified_convergence.values()))
        verification = {
            "performed": True,
            "confirmed": agreement,
            "gradient_policy": "final_central_verification",
            "fd_two_sided_count": int(verified_info["two_sided_count"]),
        }
        if not agreement:
            hessian_info = {"performed": False, "reason": "final_hessian_not_requested"}
            if active_settings.compute_final_hessian:
                active_hessian, hessian_info = _refine_hessian_diagonals_from_two_sided_energies(
                    service,
                    current,
                    q,
                    active_hessian,
                    active_settings,
                    coordinate_steps=verified_info.get("coordinate_steps"),
                    zero_off_diagonal=True,
                )
            active_settings = replace(
                active_settings,
                one_sided_until_convergence=False,
                final_gradient_verification=False,
                selective_fd_refresh=False,
            )
            verification.update(
                {
                    "two_sided_mismatch": True,
                    "continue_two_sided": True,
                    "hessian_refinement": hessian_info,
                }
            )
            return (
                active_gradient,
                active_info,
                active_hessian,
                active_settings,
                active_convergence,
                verification,
                final_hessian_refinement_attempted,
                False,
            )
    else:
        verification = {
            "performed": False,
            "confirmed": True,
            "reason": "already_two_sided",
            "fd_two_sided_count": int(active_info.get("two_sided_count", 0)),
        }

    if not active_settings.compute_final_hessian:
        active_settings = replace(
            active_settings,
            one_sided_until_convergence=False,
            final_gradient_verification=False,
            selective_fd_refresh=False,
        )
        verification["final_hessian_requested"] = False
        return (
            active_gradient,
            active_info,
            active_hessian,
            active_settings,
            active_convergence,
            verification,
            True,
            True,
        )
    if not final_hessian_refinement_attempted:
        active_hessian, hessian_info = _refine_hessian_diagonals_from_two_sided_energies(
            service,
            current,
            q,
            active_hessian,
            active_settings,
            coordinate_steps=active_info.get("coordinate_steps"),
            zero_off_diagonal=False,
        )
        active_settings = replace(
            active_settings,
            one_sided_until_convergence=False,
            final_gradient_verification=False,
            selective_fd_refresh=False,
        )
        verification.update(
            {
                "hessian_refinement": hessian_info,
                "final_step_pending": True,
            }
        )
        return (
            active_gradient,
            active_info,
            active_hessian,
            active_settings,
            active_convergence,
            verification,
            True,
            False,
        )

    verification["final_step_converged"] = True
    return (
        active_gradient,
        active_info,
        active_hessian,
        active_settings,
        active_convergence,
        verification,
        True,
        True,
    )


def _frequencies_from_final_sonic_hessian(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    hessian: np.ndarray,
) -> tuple[float, ...]:
    """Return GF frequencies from a stationary-point SONIC Hessian.

    The transformation is deliberately delegated to MATRIX-GF.  LINK owns the
    optimization Hessian and the convergence contract; GF owns mass weighting,
    external-mode projection and the frequency convention.
    """
    if service.coordinate_model.kind != "sonic":
        return ()
    from matrix_chem import atomic_mass
    from matrix_chem.topology.elements import atomic_number
    from matrix_gf import cartesian_normal_modes_from_sonic_hessian

    _values, b_matrix = service._evaluate_active_sonic(current.coordinates_angstrom)
    masses = np.asarray(
        [atomic_mass(int(atomic_number(atom) or 0)) for atom in service.atoms],
        dtype=float,
    )
    if np.any(masses <= 0.0):
        raise ValueError("final SONIC GF requires positive atomic masses")
    modes = cartesian_normal_modes_from_sonic_hessian(
        np.asarray(hessian, dtype=float),
        b_matrix,
        masses,
        np.asarray(current.coordinates_angstrom, dtype=float).reshape((-1, 3)) * ANGSTROM_TO_BOHR,
        source="LINK final SONIC Hessian",
    )
    return tuple(float(value) for value in modes.frequencies_cm)


def _verify_final_numerical_gradient(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    settings: OptimizerSettings,
    *,
    selective_disabled: bool,
) -> tuple[np.ndarray, dict[str, object]]:
    """Recompute the final numerical gradient with the cached plus side and new minus side."""

    verification_settings = replace(
        settings,
        one_sided_until_convergence=False,
        adaptive_fd_mode=False,
        two_sided=True,
        selective_fd_refresh=False,
    )
    gradient, info = _gradient_in_coordinate_space(
        service,
        current,
        q,
        hessian,
        verification_settings,
        force_explicit=True,
        selective_disabled=selective_disabled,
        force_two_sided=True,
    )
    info = dict(info)
    info["gradient_policy"] = "final_central_verification"
    return gradient, info


def _restart_evaluation_kwargs(current: object) -> dict[str, object]:
    """Return an optional backend restart contract without changing test doubles.

    Optimizer evaluations produced by resident QM backends carry a point-result
    execution mapping.  Lightweight services and external engines may not.
    Omitting the keywords entirely in that case preserves the generic evaluator
    boundary.
    """

    result = getattr(current, "result", None)
    execution = getattr(result, "execution", None)
    if not isinstance(execution, Mapping):
        return {}
    if execution.get("restart_reuse_for_displacements") is False:
        return {}
    artifact = execution.get("restart_artifact")
    if artifact is None:
        return {}
    projection = execution.get("restart_projection")
    return {
        "restart_artifact": str(artifact),
        "restart_projection": None if projection is None else str(projection),
    }


def _finite_difference_worker_allocation(
    _service: object,
    *,
    requested_workers: int,
    independent_calculations: int,
) -> tuple[int, dict[str, object]]:
    """Bound finite-difference concurrency by the authorized resource plan."""

    requested = max(1, int(requested_workers))
    count = max(1, int(independent_calculations))
    parent = authorized_parent_plan_from_environment()
    if parent is None:
        workers = min(requested, count)
        return workers, {
            "source": "optimizer-setting",
            "requested_cap": requested,
            "independent_calculations": count,
            "workers": workers,
        }
    resources = parent.resources
    estimate = estimate_concurrent_jobs(
        independent_calculations=count,
        threads_per_calculation=resources.threads_per_job,
        memory_per_calculation_gb=resources.memory_per_job_gb,
        assigned_threads=resources.maximum_threads,
        assigned_memory_gb=resources.maximum_memory_gb,
        assigned_job_limit=resources.concurrent_jobs,
        requested_cap=requested,
    )
    return estimate.workers, {
        "source": "authorized-parent-plan",
        "requested_cap": requested,
        "independent_calculations": count,
        "cpu_cap": estimate.cpu_cap,
        "memory_cap": estimate.memory_cap,
        "job_cap": estimate.job_cap,
        "limiting_factors": list(estimate.limiting_factors),
        "workers": estimate.workers,
        "parent_plan_sha256": parent.sha256,
    }


def _gradient_in_coordinate_space(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray | None,
    settings: OptimizerSettings,
    *,
    force_explicit: bool = False,
    iteration: int = 0,
    previous_gradient: np.ndarray | None = None,
    selective_disabled: bool = False,
    force_two_sided: bool = False,
    two_sided_latched: bool = False,
) -> tuple[np.ndarray, dict[str, object]]:
    composite_gradient = _frozen_composite_sonic_gradient(
        service,
        current,
        q,
        settings,
        force_two_sided=force_two_sided,
        two_sided_latched=two_sided_latched,
    )
    if composite_gradient is not None:
        return composite_gradient
    analytic = current.gradient_hartree_per_bohr
    if analytic is not None and settings.prefer_analytic_gradient:
        gradient = service.optimizer_covector_from_cartesian(
            analytic,
            current.coordinates_angstrom,
        )
        std2_hybrid = current.result.execution.get("gradient_source", "").startswith("backend_S0_analytic_plus_APOC_followed_std2")
        return gradient, {
            "gradient_policy": "hybrid_std2_cartesian_projected_full" if std2_hybrid else "analytic_cartesian_projected_full",
            "mode": "hybrid-gradient" if std2_hybrid else "analytic-gradient",
            "step_min": 0.0,
            "step_max": 0.0,
            "refreshed_coordinate_count": gradient.size,
            "predicted_coordinate_count": 0,
            "active_coordinate_fraction": 1.0,
            "one_sided_count": 0,
            "two_sided_count": 0,
            "parallel_workers": 1,
            "surrogate_sample_count": 0,
        }
    if hessian is None:
        raise ValueError("numerical coordinate gradients require a dense curvature model")
    if settings.stationary_point == "transition_state" and not force_explicit:
        negative_subspace_gradient = _gradient_in_negative_mode_subspace(
            service,
            current,
            q,
            hessian,
            settings,
            iteration=iteration,
            two_sided_latched=two_sided_latched,
        )
        if negative_subspace_gradient is not None:
            return negative_subspace_gradient
    ncoord = q.size
    gradient = np.zeros(ncoord, dtype=float)
    steps = np.zeros(ncoord, dtype=float)
    near_minimum = bool(
        force_two_sided
        or two_sided_latched
        or (
            settings.adaptive_fd_mode
            and previous_gradient is not None
            and np.max(np.abs(np.asarray(previous_gradient, dtype=float)))
            <= settings.fd_two_sided_switch_force
        )
    )
    use_central = bool(
        settings.two_sided
        and (
            force_two_sided
            or two_sided_latched
            or (
                not settings.one_sided_until_convergence
                and (near_minimum or not settings.adaptive_fd_mode)
            )
        )
    )
    if force_two_sided:
        use_central = bool(settings.two_sided)
    fd_modes = np.full(ncoord, "two-sided" if use_central else "one-sided", dtype=object)
    refresh_mask = np.ones(ncoord, dtype=bool)
    symmetry_mask = np.ones(ncoord, dtype=bool)
    if settings.fd_totally_symmetric_only:
        if service.coordinate_model.kind != "sonic" or service._sonic_definition is None:
            raise ValueError(
                "totally-symmetric finite differences require a SONIC coordinate model"
            )
        from matrix_smith.symmetry_labels import is_total_symmetric_irrep

        definition = service._sonic_definition
        symmetry_mask = np.asarray(
            [
                is_total_symmetric_irrep(
                    definition.point_group,
                    definition.gics[index].irrep,
                )
                for index in service._sonic_coordinate_indices
            ],
            dtype=bool,
        )
        if symmetry_mask.shape != (ncoord,) or not np.any(symmetry_mask):
            raise ValueError(
                "SONIC total-symmetry mask does not match the numerical coordinate model"
            )
        # At a geometry satisfying the frozen parent group, non-totally-
        # symmetric first derivatives vanish.  Do not sample their displaced
        # energies; retain their exact projected value of zero.
        refresh_mask &= symmetry_mask
    # The frozen production protocol uses only the exact symmetry mask.
    # Same-family magnitude screening is retained only as an isolated
    # diagnostic helper and is never active in production optimization.
    class_screen_enabled = False
    class_screen_audit = bool(force_two_sided)
    if hasattr(service, "finite_difference_class_screen"):
        class_mask, class_threshold_fraction, class_screen_audit = (
            service.finite_difference_class_screen(
                previous_gradient,
                symmetry_mask,
                settings,
                enabled=class_screen_enabled,
                iteration=iteration,
            )
        )
    else:
        class_mask, class_threshold_fraction = symmetry_mask.copy(), 0.0
        class_screen_audit = bool(force_two_sided)
    refresh_mask &= class_mask
    surrogate_samples = 0
    selective_active = settings.selective_fd_refresh and not selective_disabled
    if selective_active and previous_gradient is not None and not force_explicit:
        previous = np.asarray(previous_gradient, dtype=float).reshape(-1)
        predicted, counts = _surrogate_gradient_from_cache(
            service.cache.records, q, previous, settings
        )
        surrogate_samples = counts
        due = iteration <= 0 or (iteration % settings.fd_refresh_interval == 0)
        if not due and surrogate_samples >= 2:
            refresh_mask = _selective_refresh_mask(previous, predicted, hessian, settings)
            refresh_mask &= symmetry_mask
            gradient[:] = predicted
            gradient[~symmetry_mask] = 0.0
    current_energy = current.energy_hartree
    restart_kwargs = _restart_evaluation_kwargs(current)
    soft = service.coordinate_soft_mask(hessian)

    def finite_difference_step(index: int) -> float:
        hii = max(abs(float(hessian[index, index])), settings.min_abs_metric_diagonal)
        two_sided = str(fd_modes[index]) == "two-sided"
        if settings.adaptive_fd_mode and two_sided:
            scale = (
                settings.fd_soft_characteristic_scale
                if soft[index]
                else settings.fd_hard_characteristic_scale
            )
            step = (3.0 * settings.energy_noise * scale / hii) ** (1.0 / 3.0)
        elif settings.adaptive_fd_mode:
            step = math.sqrt(settings.energy_noise / hii)
        elif two_sided:
            step = settings.fd_step
        else:
            step = settings.fd_step
        return min(settings.fd_max_step, max(settings.fd_min_step, step))

    indices = [int(index) for index in np.flatnonzero(refresh_mask)]
    for index in indices:
        steps[index] = finite_difference_step(index)
    point_requests: list[tuple[int, int, np.ndarray, str]] = []
    for index in indices:
        plus_q = q.copy()
        plus_q[index] += steps[index]
        point_requests.append((index, 1, plus_q, f"fd-plus-{index + 1}"))
        if str(fd_modes[index]) == "two-sided":
            minus_q = q.copy()
            minus_q[index] -= steps[index]
            point_requests.append((index, -1, minus_q, f"fd-minus-{index + 1}"))

    def evaluate_fd_point(
        request: tuple[int, int, np.ndarray, str],
    ) -> tuple[int, int, float, float, int]:
        index, sign, _displaced_q, tag = request
        active_step = float(steps[index])
        backend = getattr(service, "backend", None)
        maximum_halvings = (
            int(backend.state_tracking_max_displacement_halvings) if backend is not None else 0
        )
        for halving in range(maximum_halvings + 1):
            displaced_q = q.copy()
            displaced_q[index] += sign * active_step
            try:
                evaluation = service.evaluate(
                    displaced_q,
                    tag=(tag if halving == 0 else f"{tag}-state-half-{halving}"),
                    requested_properties=("energy",),
                    **restart_kwargs,
                )
            except ElectronicStateResolutionError:
                if halving >= maximum_halvings:
                    raise
                active_step *= 0.5
                continue
            return index, sign, evaluation.energy_hartree, active_step, halving
        raise AssertionError("unreachable APOC displacement-halving state")

    fd_workers, worker_allocation = _finite_difference_worker_allocation(
        service,
        requested_workers=settings.fd_parallel_workers,
        independent_calculations=max(len(point_requests), 1),
    )
    if fd_workers > 1 and len(point_requests) > 1:
        with ThreadPoolExecutor(max_workers=fd_workers) as pool:
            point_results = list(pool.map(evaluate_fd_point, point_requests))
    else:
        point_results = [evaluate_fd_point(request) for request in point_requests]
    energies = {(index, sign): energy for index, sign, energy, _step, _halving in point_results}
    realized_steps = {(index, sign): step for index, sign, _energy, step, _halving in point_results}
    state_halvings = {
        (index, sign): halving for index, sign, _energy, _step, halving in point_results
    }
    for index in indices:
        step = realized_steps[(index, 1)]
        plus_energy = energies[(index, 1)]
        if str(fd_modes[index]) == "two-sided":
            minus_step = realized_steps[(index, -1)]
            minus_energy = energies[(index, -1)]
            gradient[index] = (
                -step / (minus_step * (minus_step + step)) * minus_energy
                + (step - minus_step) / (minus_step * step) * current_energy
                + minus_step / (step * (minus_step + step)) * plus_energy
            )
            steps[index] = min(step, minus_step)
        else:
            gradient[index] = (plus_energy - current_energy) / step
            steps[index] = step
    if class_screen_audit and hasattr(service, "retain_audited_finite_difference_coordinates"):
        service.retain_audited_finite_difference_coordinates(
            gradient,
            symmetry_mask,
            class_threshold_fraction,
        )
    if (
        previous_gradient is None
        and getattr(getattr(service, "coordinate_model", None), "kind", None) == "sonic"
        and settings.fd_initial_class_threshold_fraction > 0.0
    ):
        initial_max = float(np.max(np.abs(gradient))) if gradient.size else 0.0
        service._fd_initial_max_gradient = initial_max
        service._fd_class_threshold_fraction = float(settings.fd_initial_class_threshold_fraction)
    refreshed = int(np.count_nonzero(refresh_mask))
    predicted_count = int(ncoord - refreshed)
    one_sided_count = int(np.count_nonzero(fd_modes[refresh_mask] == "one-sided"))
    two_sided_count = int(np.count_nonzero(fd_modes[refresh_mask] == "two-sided"))
    fd_mode = (
        "mixed"
        if one_sided_count and two_sided_count
        else ("one-sided" if one_sided_count else "two-sided")
    )
    return gradient, {
        "gradient_policy": "coordinate_energy_fd_selective"
        if selective_active
        else "coordinate_energy_fd_full",
        "mode": fd_mode,
        "step_min": float(np.min(steps[refresh_mask])) if refreshed else 0.0,
        "step_max": float(np.max(steps[refresh_mask])) if refreshed else 0.0,
        "refreshed_coordinate_count": refreshed,
        "predicted_coordinate_count": predicted_count,
        "symmetry_excluded_coordinate_count": int(np.count_nonzero(~symmetry_mask)),
        "symmetry_mask": symmetry_mask.tolist(),
        "class_threshold_fraction": class_threshold_fraction,
        "class_screen_enabled": class_screen_enabled,
        "class_screen_audit": class_screen_audit,
        "class_screen_audit_interval": int(settings.fd_class_screen_audit_interval),
        "active_coordinate_fraction": float(refreshed / ncoord) if ncoord else 0.0,
        "one_sided_count": one_sided_count,
        "two_sided_count": two_sided_count,
        "parallel_workers": fd_workers,
        "parallel_worker_allocation": worker_allocation,
        "surrogate_sample_count": surrogate_samples,
        "hard_coordinate_count": int(np.count_nonzero(~soft & refresh_mask)),
        "soft_coordinate_count": int(np.count_nonzero(soft & refresh_mask)),
        "near_minimum": near_minimum,
        "coordinate_steps": steps.tolist(),
        "state_displacement_halvings": {
            f"q{index + 1}:{'plus' if sign > 0 else 'minus'}": count
            for (index, sign), count in state_halvings.items()
            if count
        },
    }


def _frozen_composite_sonic_gradient(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    settings: OptimizerSettings,
    *,
    force_two_sided: bool = False,
    two_sided_latched: bool = False,
) -> tuple[np.ndarray, dict[str, object]] | None:
    """Apply the immutable PCS2/PPCS2 SONIC derivative contract.

    The signed sum of all energy-only terms is sampled at the central point
    and once in the positive direction of every totally symmetric SONIC.
    Analytic term gradients are evaluated only at the central point and added
    after transformation to optimizer coordinates.  Consequently an
    ``n_A1``-dimensional totally symmetric subspace requires exactly
    ``1 + n_A1`` evaluations of each energy-only electronic-structure term.
    """

    backend = getattr(service, "backend", None)
    if (
        backend is None
        or _normalized_backend_name(backend.name) != "linear_composite"
        or str(backend.gradient_mode).strip().casefold() != "sonic_one_sided_hybrid"
    ):
        return None
    if service.coordinate_model.kind != "sonic" or service._sonic_definition is None:
        raise RuntimeError("frozen PCS2/PPCS2 gradients require SONIC coordinates")
    if not settings.fd_totally_symmetric_only:
        raise RuntimeError(
            "frozen PCS2/PPCS2 gradients require the totally symmetric SONIC subspace"
        )
    use_two_sided = bool(settings.two_sided and (force_two_sided or two_sided_latched))

    numerical_terms = tuple(
        term
        for term in backend.composite_terms
        if str(term.backend.gradient_mode).strip().casefold() == "energy"
    )
    if not numerical_terms:
        return None
    execution = current.result.execution
    central_numerical_energy = execution.get("composite_numerical_energy_hartree")
    if central_numerical_energy is None:
        raise RuntimeError("composite central point lacks its numerical-term energy")
    partial = execution.get("composite_partial_analytic_gradient_hartree_per_bohr")
    if partial is None:
        gradient = np.zeros(q.size, dtype=float)
    else:
        partial_cartesian = np.asarray(partial, dtype=float).reshape(-1)
        if partial_cartesian.size != current.coordinates_angstrom.size:
            raise RuntimeError("composite partial analytic gradient has an invalid size")
        gradient = service.optimizer_covector_from_cartesian(
            partial_cartesian,
            current.coordinates_angstrom,
        )

    from matrix_smith.symmetry_labels import is_total_symmetric_irrep

    definition = service._sonic_definition
    symmetry_mask = np.asarray(
        [
            is_total_symmetric_irrep(
                definition.point_group,
                definition.gics[index].irrep,
            )
            for index in service._sonic_coordinate_indices
        ],
        dtype=bool,
    )
    if symmetry_mask.shape != (q.size,) or not np.any(symmetry_mask):
        raise RuntimeError("invalid totally symmetric SONIC mask for composite gradient")
    gradient[~symmetry_mask] = 0.0

    steps = {float(term.backend.numerical_gradient_step_bohr) for term in numerical_terms}
    if len(steps) != 1:
        raise RuntimeError("all numerical composite terms must use the same SONIC step")
    step = steps.pop()
    if not math.isfinite(step) or step <= 0.0:
        raise RuntimeError("composite SONIC gradient step must be finite and positive")

    central_term_execution = {
        str(item.get("label")): item
        for item in execution.get("composite_terms", ())
        if isinstance(item, Mapping)
    }
    reused_restart_labels: list[str] = []
    restarted_numerical_terms = []
    for term in numerical_terms:
        term_execution = central_term_execution.get(term.label, {})
        artifact = term_execution.get("restart_artifact")
        can_reuse = (
            term.backend.restart_reuse_for_displacements
            and bool(term_execution.get("restart_reuse_for_displacements"))
            and artifact is not None
            and Path(str(artifact)).is_file()
        )
        if can_reuse:
            reused_restart_labels.append(term.label)
            restarted_numerical_terms.append(
                replace(
                    term,
                    backend=replace(
                        term.backend,
                        restart_artifact=Path(str(artifact)),
                        restart_projection=(
                            None
                            if term_execution.get("restart_projection") is None
                            else str(term_execution["restart_projection"])
                        ),
                    ),
                )
            )
        else:
            restarted_numerical_terms.append(term)
    numerical_backend = replace(
        backend,
        properties=("energy",),
        gradient_mode="energy",
        composite_terms=tuple(restarted_numerical_terms),
    )
    indices = [int(index) for index in np.flatnonzero(symmetry_mask)]

    requests = [(index, sign) for index in indices for sign in ((1, -1) if use_two_sided else (1,))]

    def evaluate(request: tuple[int, int]) -> tuple[tuple[int, int], float]:
        index, sign = request
        displaced = np.asarray(q, dtype=float).copy()
        displaced[index] += sign * step
        result = service.evaluate(
            displaced,
            tag=(f"fd-composite-sonic-{'plus' if sign > 0 else 'minus'}-{index + 1}"),
            use_cache=False,
            persist_cache=False,
            requested_properties=("energy",),
            enforce_gradient_symmetry=False,
            backend_override=numerical_backend,
        )
        point_result = getattr(result, "result", result)
        numerical_energy = point_result.execution.get("composite_numerical_energy_hartree")
        if numerical_energy is None:
            raise RuntimeError("composite displaced point lacks its numerical-term energy")
        return (index, sign), float(numerical_energy)

    fd_workers, worker_allocation = _finite_difference_worker_allocation(
        service,
        requested_workers=settings.fd_parallel_workers,
        independent_calculations=max(len(requests), 1),
    )
    if fd_workers > 1 and len(requests) > 1:
        with ThreadPoolExecutor(max_workers=fd_workers) as pool:
            displaced_energies = dict(pool.map(evaluate, requests))
    else:
        displaced_energies = dict(evaluate(request) for request in requests)
    center = float(central_numerical_energy)
    for index in indices:
        if use_two_sided:
            gradient[index] += (
                displaced_energies[(index, 1)] - displaced_energies[(index, -1)]
            ) / (2.0 * step)
        else:
            gradient[index] += (displaced_energies[(index, 1)] - center) / step

    return gradient, {
        "gradient_policy": (
            "frozen_composite_two_sided_stall_recovery_totally_symmetric_SONIC"
            if use_two_sided
            else "frozen_composite_one_sided_totally_symmetric_SONIC"
        ),
        "mode": "two-sided" if use_two_sided else "one-sided",
        "step_min": step,
        "step_max": step,
        "refreshed_coordinate_count": len(indices),
        "predicted_coordinate_count": int(q.size - len(indices)),
        "symmetry_excluded_coordinate_count": int(np.count_nonzero(~symmetry_mask)),
        "symmetry_mask": symmetry_mask.tolist(),
        "active_coordinate_fraction": float(len(indices) / q.size) if q.size else 0.0,
        "one_sided_count": 0 if use_two_sided else len(indices),
        "two_sided_count": len(indices) if use_two_sided else 0,
        "parallel_workers": fd_workers,
        "parallel_worker_allocation": worker_allocation,
        "surrogate_sample_count": 0,
        "coordinate_steps": [step if active else 0.0 for active in symmetry_mask],
        "numerical_term_labels": [term.label for term in numerical_terms],
        "restart_reused_numerical_term_labels": reused_restart_labels,
        "numerical_term_evaluations_per_gradient": (1 + (2 if use_two_sided else 1) * len(indices)),
        "totally_symmetric_sonic_coordinate_count": len(indices),
    }


def _gradient_in_negative_mode_subspace(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    settings: OptimizerSettings,
    *,
    iteration: int,
    two_sided_latched: bool,
) -> tuple[np.ndarray, dict[str, object]] | None:
    """Estimate a TS gradient with central differences along negative modes.

    The uphill eigenspace is the numerically most sensitive part of a
    transition-state search.  Directional central differences are used there
    while the orthogonal complement retains the information-efficient
    one-sided estimate.  The returned vector is reconstructed in the complete
    orthonormal optimizer-coordinate basis, so no force component is dropped.
    """

    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    if matrix.shape != (q.size, q.size) or q.size == 0:
        return None
    try:
        eigenvalues, eigenvectors = np.linalg.eigh(matrix)
    except np.linalg.LinAlgError:
        return None
    negative = np.flatnonzero(eigenvalues < -1.0e-12)
    if negative.size == 0:
        return None
    negative_modes = np.asarray(eigenvectors[:, negative], dtype=float)
    try:
        basis, _ = np.linalg.qr(negative_modes, mode="complete")
    except np.linalg.LinAlgError:
        return None
    nnegative = int(negative_modes.shape[1])
    complement = basis[:, nnegative:]
    current_energy = float(current.energy_hartree)
    noise = max(float(settings.energy_noise), 1.0e-16)

    mode_steps = np.zeros(q.size, dtype=float)
    for column, eigenvalue in enumerate(eigenvalues[negative]):
        curvature = max(abs(float(eigenvalue)), settings.min_abs_metric_diagonal)
        mode_steps[column] = min(
            settings.fd_max_step,
            max(
                settings.fd_min_step,
                (3.0 * noise * settings.fd_soft_characteristic_scale / curvature) ** (1.0 / 3.0),
            ),
        )
    complement_steps = np.zeros(complement.shape[1], dtype=float)
    for column in range(complement.shape[1]):
        direction = complement[:, column]
        curvature = max(
            abs(float(direction @ matrix @ direction)), settings.min_abs_metric_diagonal
        )
        complement_steps[column] = min(
            settings.fd_max_step,
            max(settings.fd_min_step, math.sqrt(noise / curvature)),
        )

    requests: list[tuple[str, int, np.ndarray, float]] = []
    for column in range(nnegative):
        direction = basis[:, column]
        step = mode_steps[column]
        requests.append(("negative-plus", column, q + step * direction, step))
        requests.append(("negative-minus", column, q - step * direction, step))
    for column in range(complement.shape[1]):
        direction = complement[:, column]
        step = complement_steps[column]
        requests.append(("complement-plus", column, q + step * direction, step))

    def evaluate(request: tuple[str, int, np.ndarray, float]) -> tuple[str, int, float]:
        family, column, displaced_q, _step = request
        tag = f"fd-ts-{family}-{column + 1}"
        result = service.evaluate(
            displaced_q,
            tag=tag,
            requested_properties=("energy",),
            **_restart_evaluation_kwargs(current),
        )
        return family, column, float(result.energy_hartree)

    fd_workers, worker_allocation = _finite_difference_worker_allocation(
        service,
        requested_workers=settings.fd_parallel_workers,
        independent_calculations=max(len(requests), 1),
    )
    if fd_workers > 1 and len(requests) > 1:
        with ThreadPoolExecutor(max_workers=fd_workers) as pool:
            values = list(pool.map(evaluate, requests))
    else:
        values = [evaluate(request) for request in requests]
    energies = {(family, column): energy for family, column, energy in values}

    directional = np.zeros(q.size, dtype=float)
    for column in range(nnegative):
        directional[column] = (
            energies[("negative-plus", column)] - energies[("negative-minus", column)]
        ) / (2.0 * mode_steps[column])
    for column in range(complement.shape[1]):
        directional[nnegative + column] = (
            energies[("complement-plus", column)] - current_energy
        ) / complement_steps[column]
    gradient = basis @ directional
    return gradient, {
        "gradient_policy": "transition_negative_subspace_central_complement_forward",
        "mode": "negative-subspace-mixed",
        "step_min": float(np.min(np.concatenate((mode_steps, complement_steps))))
        if complement_steps.size
        else float(np.min(mode_steps)),
        "step_max": float(np.max(np.concatenate((mode_steps, complement_steps))))
        if complement_steps.size
        else float(np.max(mode_steps)),
        "refreshed_coordinate_count": int(q.size),
        "predicted_coordinate_count": 0,
        "active_coordinate_fraction": 1.0,
        "one_sided_count": int(complement.shape[1]),
        "two_sided_count": nnegative,
        "parallel_workers": fd_workers,
        "parallel_worker_allocation": worker_allocation,
        "surrogate_sample_count": 0,
        "near_minimum": bool(two_sided_latched),
        "negative_mode_count": nnegative,
    }


def _surrogate_gradient_from_cache(
    records: Sequence[OptimizerEvaluation],
    q: np.ndarray,
    fallback: np.ndarray,
    settings: OptimizerSettings,
) -> tuple[np.ndarray, int]:
    base = np.asarray(q, dtype=float).reshape(-1)
    gradient = np.asarray(fallback, dtype=float).reshape(-1).copy()
    usable: list[tuple[np.ndarray, float]] = []
    for record in records[-settings.surrogate_max_samples :]:
        try:
            usable.append((np.asarray(record.q, dtype=float).reshape(-1), record.energy_hartree))
        except ValueError:
            continue
    if len(usable) < 2:
        return gradient, len(usable)
    q_values = np.vstack([item[0] for item in usable])
    energies = np.asarray([item[1] for item in usable], dtype=float)
    centered = q_values - base
    design = np.column_stack([np.ones(centered.shape[0]), centered])
    try:
        coeffs, *_ = np.linalg.lstsq(design, energies, rcond=None)
    except np.linalg.LinAlgError:
        return gradient, len(usable)
    if coeffs.shape[0] == gradient.size + 1 and np.all(np.isfinite(coeffs[1:])):
        gradient[:] = coeffs[1:]
    return gradient, len(usable)


def _selective_refresh_mask(
    previous: np.ndarray,
    predicted: np.ndarray,
    hessian: np.ndarray,
    settings: OptimizerSettings,
) -> np.ndarray:
    previous_gradient = np.asarray(previous, dtype=float).reshape(-1)
    predicted_gradient = np.asarray(predicted, dtype=float).reshape(-1)
    stable = np.abs(predicted_gradient - previous_gradient) <= settings.fd_gradient_change_tolerance
    inactive_force = (np.abs(previous_gradient) <= settings.max_force_tolerance) & (
        np.abs(predicted_gradient) <= settings.max_force_tolerance
    )
    refresh = ~(stable & inactive_force)
    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    if matrix.shape == (refresh.size, refresh.size) and refresh.size:
        diagonal = np.maximum(np.abs(np.diag(matrix)), settings.min_abs_metric_diagonal)
        denom = np.sqrt(np.outer(diagonal, diagonal))
        normalized_coupling = np.divide(
            np.abs(matrix),
            denom,
            out=np.zeros_like(matrix, dtype=float),
            where=denom > 0.0,
        )
        np.fill_diagonal(normalized_coupling, 0.0)
        active = (
            refresh
            | (np.abs(previous_gradient) > 0.5 * settings.max_force_tolerance)
            | (np.abs(predicted_gradient) > 0.5 * settings.max_force_tolerance)
        )
        coupled_score = normalized_coupling @ active.astype(float)
        refresh |= coupled_score > settings.selective_coupling_threshold
    else:
        coupled_score = np.zeros(refresh.size, dtype=float)
    minimum = int(math.ceil(settings.selective_min_refresh_fraction * refresh.size))
    if minimum > 0 and int(np.count_nonzero(refresh)) < minimum:
        priority = np.maximum(np.abs(previous_gradient), np.abs(predicted_gradient)) + coupled_score
        for index in np.argsort(priority)[::-1][:minimum]:
            refresh[int(index)] = True
    if refresh.size and not np.any(refresh):
        refresh[int(np.argmax(np.abs(predicted_gradient)))] = True
    return np.asarray(refresh, dtype=bool)


def _local_coordinate_groups(
    model: OptimizerCoordinateModel,
    hessian: np.ndarray,
    settings: OptimizerSettings,
) -> tuple[tuple[int, ...], ...]:
    ncoord = len(model.labels)
    if ncoord == 0:
        return ()
    parent = list(range(ncoord))

    def find(item: int) -> int:
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left: int, right: int) -> None:
        root_left = find(left)
        root_right = find(right)
        if root_left != root_right:
            parent[root_right] = root_left

    directions = np.asarray(model.directions_angstrom, dtype=float)
    support = np.abs(directions) > 1.0e-12
    for i in range(ncoord):
        for j in range(i + 1, ncoord):
            shares_cartesian = bool(np.any(support[i] & support[j]))
            coupled = abs(float(hessian[i, j])) > settings.hessian_coupling_threshold
            if shares_cartesian or coupled:
                union(i, j)
    groups: dict[int, list[int]] = {}
    for index in range(ncoord):
        groups.setdefault(find(index), []).append(index)
    return tuple(tuple(items) for items in groups.values())


def _hessian_sparsity_mask(
    model: OptimizerCoordinateModel,
    hessian: np.ndarray,
    settings: OptimizerSettings,
) -> np.ndarray:
    ncoord = len(model.labels)
    mask = np.eye(ncoord, dtype=bool)
    directions = np.asarray(model.directions_angstrom, dtype=float)
    support = np.abs(directions) > 1.0e-12
    for i in range(ncoord):
        for j in range(i + 1, ncoord):
            keep = (
                bool(np.any(support[i] & support[j]))
                or abs(float(hessian[i, j])) > settings.hessian_coupling_threshold
            )
            mask[i, j] = keep
            mask[j, i] = keep
    return mask


def _project_hessian_sparsity(hessian: np.ndarray, mask: np.ndarray) -> np.ndarray:
    projected = np.asarray(hessian, dtype=float).copy()
    projected[~mask] = 0.0
    return 0.5 * (projected + projected.T)


def _matrix_sparsity(matrix: np.ndarray) -> float:
    array = np.asarray(matrix, dtype=float)
    if array.size == 0:
        return 1.0
    return float(1.0 - np.count_nonzero(np.abs(array) > 1.0e-14) / array.size)


def _symmetry_status(
    settings: OptimizerSettings,
    model: OptimizerCoordinateModel,
) -> str:
    if getattr(model, "pes_exploration", False):
        return "instantaneous_exploration_group_perception"
    definition = model.sonic_definition if model.kind == "sonic" else None
    if (
        definition is not None
        and bool(definition.symmetrize)
        and str(definition.point_group).strip().upper() not in {"", "C1", "UNKNOWN"}
    ):
        return "frozen_initial_group_gradient_projection"
    if not settings.symmetry_reduction:
        return "disabled"
    if model.kind != "sonic":
        return "disabled_non_sonic"
    return "diagnostic_only"


def _selective_fallback_status(settings: OptimizerSettings, selective_disabled: bool) -> str:
    if not settings.selective_fd_refresh:
        return "disabled"
    return "fallback_full_fd" if selective_disabled else "selective_active"


def _gradient_adaptive_trust_radius(
    trust_radius: float,
    gradient: np.ndarray,
    settings: OptimizerSettings,
) -> float:
    """Limit the trust radius from the current maximum Cartesian gradient.

    The cube-root scaling uses only the force/convergence threshold.  It
    therefore does not depend on the molecule, atom count, or chemical type.
    Below the requested force threshold the regular trust controller is left
    unchanged. Quadraticized RFO deliberately bypasses this pre-contraction:
    its Morse/Gaussian/periodic map accounts for the diagonal nonlinearity,
    while the designed pullback metric and energy-ratio controller remain
    authoritative for a larger requested radius. Cartesian realization is a
    domain and molecular-geometry validity check for this step model.
    """
    radius = float(trust_radius)
    if (
        settings.stationary_point != "minimum"
        or settings.step_model == "quadraticized_rfo"
        or not np.isfinite(radius)
    ):
        return radius
    values = np.asarray(gradient, dtype=float).reshape(-1)
    if values.size == 0 or not np.all(np.isfinite(values)):
        return radius
    max_force = float(np.max(np.abs(values)))
    force_tolerance = max(float(settings.max_force_tolerance), np.finfo(float).eps)
    force_ratio = max_force / force_tolerance
    if not np.isfinite(force_ratio) or force_ratio <= 1.0:
        return radius
    # A cube-root contraction preserves a larger, still force-controlled
    # radius once the initial model is reliable; this avoids unnecessary
    # extra geometry evaluations on small systems while remaining conservative
    # far from a stationary point.
    scaled = float(settings.trust_radius) / force_ratio ** (1.0 / 3.0)
    return max(float(settings.min_trust_radius), min(radius, scaled))


def _minimum_effective_hessian_model(
    hessian: np.ndarray,
    settings: OptimizerSettings,
    *,
    metric: np.ndarray | None = None,
) -> tuple[np.ndarray, np.ndarray, float, float, float]:
    """Return the conditioned model in an orthonormal full-metric chart."""

    matrix, inverse_sqrt_metric = _orthonormal_optimizer_hessian(
        hessian,
        metric,
        settings,
    )
    size = matrix.shape[0]
    try:
        eigenvalues, eigenvectors = np.linalg.eigh(matrix)
    except np.linalg.LinAlgError:
        eigenvalues = np.ones(size, dtype=float)
        eigenvectors = np.eye(size, dtype=float)
    minimum = float(np.min(eigenvalues)) if eigenvalues.size else 0.0
    maximum = max(float(np.max(np.abs(eigenvalues))), settings.min_hessian_eigenvalue)
    floor = max(settings.min_hessian_eigenvalue, maximum / settings.max_hessian_condition)
    positive = np.maximum(eigenvalues, floor)
    condition = float(np.max(positive) / np.min(positive)) if positive.size else 1.0
    effective_hessian = eigenvectors @ np.diag(positive) @ eigenvectors.T
    return effective_hessian, inverse_sqrt_metric, minimum, condition, floor


def _orthonormal_optimizer_hessian(
    hessian: np.ndarray,
    metric: np.ndarray | None,
    settings: OptimizerSettings,
) -> tuple[np.ndarray, np.ndarray]:
    """Express a covariant Hessian in LINK's physical Wilson metric."""

    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    size = matrix.shape[0]
    metric_matrix = np.eye(size, dtype=float)
    if metric is not None:
        supplied = np.asarray(metric, dtype=float)
        if supplied.ndim == 1 and supplied.shape == (size,):
            supplied = np.diag(supplied)
        if supplied.shape != (size, size):
            raise ValueError("optimizer metric shape does not match the Hessian")
        metric_matrix = _positive_metric_matrix(supplied, settings.min_abs_metric_diagonal)
    metric_values, metric_vectors = np.linalg.eigh(metric_matrix)
    inverse_sqrt_metric = metric_vectors @ np.diag(1.0 / np.sqrt(metric_values)) @ metric_vectors.T
    orthonormal = inverse_sqrt_metric @ matrix @ inverse_sqrt_metric
    return 0.5 * (orthonormal + orthonormal.T), inverse_sqrt_metric


def _minimum_effective_hessian_displacement(
    hessian: np.ndarray,
    gradient: np.ndarray,
    settings: OptimizerSettings,
    *,
    metric: np.ndarray | None = None,
) -> np.ndarray:
    """Apply ``-H_eff^-1`` in the same full-metric chart used by RFO."""

    effective, inverse_sqrt_metric, _minimum, _condition, _floor = _minimum_effective_hessian_model(
        hessian,
        settings,
        metric=metric,
    )
    scaled_gradient = inverse_sqrt_metric @ np.asarray(gradient, dtype=float).reshape(-1)
    try:
        scaled_step = -np.linalg.solve(effective, scaled_gradient)
    except np.linalg.LinAlgError:
        scaled_step = -(np.linalg.pinv(effective, rcond=1.0e-12) @ scaled_gradient)
    return inverse_sqrt_metric @ np.asarray(scaled_step, dtype=float)


def _transformed_primitive_sh_diagonal(
    service: GeometryEvaluationService,
    model: OptimizerCoordinateModel,
) -> tuple[np.ndarray, dict[str, object]]:
    """Return diag(J.T H_ORACLE J), never a derived-family atlas lookup."""

    if model.kind != "sonic" or model.sonic_definition is None:
        raise ValueError("transformed SH diagonal requires a SONIC definition")
    from matrix_smith.sonic_hessian import build_sonic_hessian

    reference = np.asarray(service.reference_coordinates, dtype=float)
    source = build_sonic_hessian(
        service.xyzin_path,
        coordinates_angstrom=reference,
        pair_error_tolerance=service.settings.initial_hessian_pair_tolerance,
    )
    directions = (
        _optimizer_directions_at_geometry(model, model.sonic_definition, reference)
        / ANGSTROM_TO_BOHR
    )
    active_hessian = np.asarray(source.dense(directions.T), dtype=float)
    if active_hessian.shape != (len(model.labels), len(model.labels)):
        raise ValueError("transformed ORACLE SH has the wrong SONIC dimension")
    diagonal = np.diag(0.5 * (active_hessian + active_hessian.T)).copy()
    if np.any(~np.isfinite(diagonal)) or np.any(diagonal <= 0.0):
        raise ValueError("transformed ORACLE SH has a nonpositive SONIC diagonal")
    return diagonal, {
        "source": "ORACLE_PRIMITIVE_SH_CONGRUENCE",
        "formula": "diag(J.T H_ORACLE J)",
        "derived_family_curvatures_assigned": False,
        "coordinate_count": len(diagonal),
    }


def _build_quadraticized_coordinate_map(
    service: GeometryEvaluationService,
    settings: OptimizerSettings,
):
    """Classify direct SONIC variables for the quadraticized-RFO option."""

    from .quadraticized_coordinates import (
        GAUSSIAN,
        LINEAR,
        MORSE,
        PERIODIC,
        QuadraticizedCoordinateMap,
    )

    model = service.coordinate_model
    if settings.stationary_point not in {"minimum", "transition_state"}:
        raise ValueError("quadraticized RFO requires a specified stationary point")
    if model.kind != "sonic" or service._sonic_definition is None:
        raise ValueError("quadraticized RFO requires a SONIC internal-coordinate model")
    projection = model.sonic_from_coordinates
    if settings.coordinate_schedule == "inter-intra-micro":
        raise ValueError(
            "quadraticized RFO supports the joint and inter-intra-joint schedules"
        )
    definition = service._sonic_definition
    indices = tuple(int(index) for index in service._sonic_coordinate_indices)
    if len(indices) != (len(model.sonic_labels) if projection is not None else len(model.labels)):
        raise RuntimeError("quadraticized RFO could not resolve the active SONIC order")
    from matrix_smith.symmetry_labels import is_total_symmetric_irrep

    # Read the frozen ORACLE topology rather than inferring bond orders from
    # the current geometry.  This keeps the chart decision deterministic and
    # makes the periodic/non-periodic split agree with the primitive atlas.
    from matrix_core import read_sectioned_lines
    from matrix_smith.topology_io import (
        _topology_bonds,
        _topology_rings,
        topology_bond_orders_from_lines,
    )

    topology_path = getattr(service, "xyzin_path", None)
    # Small unit-test fakes and legacy in-memory callers do not carry the
    # frozen ORACLE file.  Preserve their explicit periodic declaration; the
    # production GeometryEvaluationService always has ``xyzin_path`` and thus
    # uses the strict topology gate below.
    topology_available = topology_path is not None
    topology_lines = read_sectioned_lines(topology_path) if topology_available else []
    natoms = len(getattr(service, "atoms", ()))
    try:
        topology_bonds = set(_topology_bonds(topology_lines, natoms=natoms))
    except Exception:
        topology_bonds = set()
    try:
        bond_orders = topology_bond_orders_from_lines(topology_lines, natoms=natoms)
    except Exception:
        bond_orders = {}
    ring_edges: set[tuple[int, int]] = set()
    try:
        for _ring_id, ring_atoms in _topology_rings(topology_lines, natoms=natoms):
            ring = tuple(int(atom) for atom in ring_atoms)
            ring_edges.update(
                tuple(sorted((ring[index], ring[(index + 1) % len(ring)])))
                for index in range(len(ring))
            )
    except Exception:
        ring_edges = set()

    primitive_by_id = {
        str(primitive.identifier): primitive
        for primitive in getattr(definition, "primitives", ())
    }
    periodic_torsion_families = {"TORSION", "PSEUDO_CYCLE_TORSION"}

    def is_delocalized(gic) -> bool:
        """Return whether a collective SONIC row should retain a linear map."""

        family = str(getattr(gic, "family", "")).strip().upper()
        labels = (
            str(getattr(gic, "identifier", "")).strip().upper(),
            str(getattr(gic, "name", "")).strip().upper(),
        )
        if family == "DELOCALIZED" or any(label.startswith("DL") for label in labels):
            return True

        components = tuple(getattr(gic, "coefficients", ())) or (
            (str(getattr(gic, "primitive_id", getattr(gic, "identifier", ""))), 1.0),
        )
        weights = np.asarray(
            [float(coefficient) for _primitive_id, coefficient in components],
            dtype=float,
        )
        weights = weights[np.abs(weights) > 1.0e-12]
        if weights.size <= 1:
            return False
        atoms: set[int] = set()
        for primitive_id, coefficient in components:
            if abs(float(coefficient)) <= 1.0e-12:
                continue
            primitive = primitive_by_id.get(str(primitive_id))
            if primitive is not None:
                atoms.update(int(atom) for atom in getattr(primitive, "atoms", ()))
        # A local valence unit contains at most one centre and its first
        # neighbours (four atoms for the common tetra-coordinate case).
        # Combinations spanning more atoms are molecular/ring collective
        # modes even when their coefficient participation happens to be low.
        if len(atoms) > 4:
            return True
        norm2 = float(weights @ weights)
        participation = norm2 * norm2 / max(float(np.sum(weights**4)), 1.0e-30)
        # Four primitive directions still describe a compact local unit.  A
        # larger effective support is a collective/delocalized SONIC row; it
        # already distributes anharmonicity and is therefore left unchanged.
        return participation > 4.0 + 1.0e-10

    def periodic_torsion_is_admissible(gic) -> bool:
        """Return true only for exocyclic low-order proper torsions."""

        if not topology_available:
            return True

        family = str(getattr(gic, "family", "")).strip().upper()
        if family not in periodic_torsion_families:
            return False
        components = tuple(getattr(gic, "coefficients", ())) or (
            (str(gic.primitive_id), 1.0),
        )
        torsion_primitives = []
        for primitive_id, coefficient in components:
            if abs(float(coefficient)) <= 1.0e-14:
                continue
            primitive = primitive_by_id.get(str(primitive_id))
            if primitive is None or str(getattr(primitive, "function", "")).upper() != "D":
                return False
            if str(getattr(primitive, "family", "")).strip().upper() not in periodic_torsion_families:
                return False
            # The chart status is assigned upstream by ORACLE and is not a
            # choice that SMITH or LINK may revise.
            if str(getattr(primitive, "chart", "PRINCIPAL")).strip().upper() not in {
                "PERIODIC",
                "PERIODIC_CONTINUATION",
            }:
                return False
            atoms = tuple(int(atom) for atom in getattr(primitive, "atoms", ()))
            if len(atoms) != 4 or len(set(atoms)) != 4:
                return False
            torsion_primitives.append(atoms)
        if not torsion_primitives:
            return False
        threshold = float(settings.quadraticized_periodic_bond_order_threshold)
        for atoms in torsion_primitives:
            central = tuple(sorted((atoms[1], atoms[2])))
            # A central edge occurring in a topology ring is endocyclic.  If
            # the ring ledger is unavailable, fail closed instead of wrapping
            # an ambiguous torsion.
            if central in ring_edges:
                return False
            if central not in topology_bonds:
                return False
            order = bond_orders.get(central)
            if order is None or float(order) >= threshold:
                return False
        return True

    periodic_periods = dict(service._sonic_periodic_periods)
    periodic_components = dict(service._sonic_periodic_gic_components)
    unit_scales = np.asarray(
        service.gdv_backtransform_coordinate_scales(len(indices))
        if projection is not None
        else service.gdv_internal_coordinate_scales(),
        dtype=float,
    )
    if unit_scales.shape != (len(indices),) or np.any(unit_scales <= 0.0):
        raise RuntimeError("quadraticized RFO requires valid SONIC unit scales")
    # A fully delocalized chart has already distributed the local
    # anharmonicity.  Applying a second component-wise nonlinear map is both
    # physically unmotivated and harmful to its back-transformation.  Select
    # ordinary SONIC/RFO automatically; mixed charts are handled row by row.
    if all(
        str(getattr(definition.gics[index], "family", "")).strip().upper()
        == "DELOCALIZED"
        or str(getattr(definition.gics[index], "identifier", "")).strip().upper().startswith("DL")
        or str(getattr(definition.gics[index], "name", "")).strip().upper().startswith("DL")
        for index in indices
    ):
        return None
    # Use the diagonal of the *transformed primitive SH* to set the nonlinear
    # exponent of each active SONIC coordinate.  The median normalization
    # preserves the global trust-radius scale while retaining local stiffness
    # ratios; derived SONIC families never receive independent curvatures.
    try:
        source_model = (
            coordinate_model_from_xyzin(
                service.xyzin_path, kind="sonic", task_regime="TRANSITION_STATE"
            )
            if projection is not None
            else model
        )
        force_constants, _sh_audit = _transformed_primitive_sh_diagonal(service, source_model)
        force_constants = np.asarray(force_constants, dtype=float).reshape(-1)
        if force_constants.shape != (len(indices),) or np.any(force_constants <= 0.0):
            raise ValueError("invalid SH force-constant diagonal")
        reference_force_constant = float(np.median(force_constants))
        force_alpha = np.sqrt(force_constants / max(reference_force_constant, 1.0e-12))
    except (AttributeError, RuntimeError, ValueError, FloatingPointError):
        # Legacy in-memory definitions have no primitive SH contract.  Their
        # unit-scale map remains the compatibility path; production ORACLE
        # contracts always provide the local force constants.
        force_alpha = np.ones(len(indices), dtype=float)
    alphas = unit_scales * force_alpha
    kinds: list[str] = []
    periods = np.full(len(indices), np.nan, dtype=float)
    for active_index, definition_index in enumerate(indices):
        gic = definition.gics[definition_index]
        if is_delocalized(gic):
            kinds.append(LINEAR)
            continue
        # Ring/puckering and butterfly coordinates are composite functions of
        # local SOOP components.  Their angular labels are descriptive, not a
        # licence to apply a wrapped periodic map: wrapping a composite phase
        # creates a discontinuous local curvature model.  Use the same bounded
        # Morse/Gaussian maps as for other SONIC variables and reserve the
        # periodic map for the exocyclic low-order torsions tagged by ORACLE.
        family = str(getattr(gic, "family", "")).strip().upper()
        if family in {
            "RING_PUCKER_PHASE",
            "RING_PUCKER_COMPONENT",
            "BUTTERFLY",
            "FULLERENE",
        }:
            kinds.append(
                MORSE
                if is_total_symmetric_irrep(definition.point_group, gic.irrep)
                else GAUSSIAN
            )
            continue
        if (
            (definition_index in periodic_periods or definition_index in periodic_components)
            and periodic_torsion_is_admissible(gic)
        ):
            kinds.append(PERIODIC)
            periods[active_index] = float(periodic_periods.get(definition_index, 2.0 * np.pi))
            continue
        kinds.append(
            MORSE
            if is_total_symmetric_irrep(definition.point_group, gic.irrep)
            else GAUSSIAN
        )
    # One bohr for lengths and one radian for angles gives the nonlinear map
    # a physical scale without adding a second set of optimizer parameters.
    component_map = QuadraticizedCoordinateMap(
        tuple(kinds), 1.0 / alphas, periods, alphas=alphas
    )
    if projection is None:
        return component_map
    from .quadraticized_coordinates import ProjectedQuadraticizedCoordinateMap

    return ProjectedQuadraticizedCoordinateMap(component_map, projection)


def _quadraticized_geometric_trust_region_step(
    coordinate_map,
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    gradient: np.ndarray,
    radius: float,
    settings: OptimizerSettings,
    *,
    metric: np.ndarray | None = None,
    damping: float = 0.0,
) -> tuple[StepProposal, np.ndarray]:
    """Run the existing RFO in variables that quadraticize each diagonal."""

    transformed_hessian = coordinate_map.hessian_at_origin(gradient, hessian)
    transformed = _geometric_trust_region_step(
        service,
        current,
        q,
        transformed_hessian,
        gradient,
        radius,
        settings,
        metric=metric,
        damping=damping,
    )
    physical_step, domain_scale = coordinate_map.inverse(transformed.step)
    model_gradient = np.asarray(gradient, dtype=float).copy()
    model_hessian = np.asarray(transformed_hessian, dtype=float).copy()

    def prediction(realized_step: np.ndarray) -> float:
        return coordinate_map.predicted_reduction(realized_step, model_gradient, model_hessian)

    policy = f"quadraticized_morse_gaussian_periodic:{transformed.policy}"
    if domain_scale < 1.0:
        policy += f":coordinate_domain_scale={domain_scale:.6g}"
    return (
        replace(
            transformed,
            step=physical_step,
            policy=policy,
            prediction_hessian=(
                np.asarray(hessian, dtype=float).copy()
                if settings.stationary_point == "transition_state"
                else None
            ),
            prediction_function=prediction,
        ),
        transformed_hessian,
    )


def _quadraticized_metric_step_angstrom(
    coordinate_map,
    physical_step: np.ndarray,
    metric: np.ndarray,
    *,
    atom_count: int,
) -> float:
    """Return the finite-step distance in the designed pullback metric."""

    transformed = coordinate_map.forward(physical_step)
    matrix = np.asarray(metric, dtype=float)
    if matrix.shape != (transformed.size, transformed.size):
        raise ValueError("quadraticized metric does not match the optimizer step")
    squared = float(transformed @ (0.5 * (matrix + matrix.T)) @ transformed)
    if not np.isfinite(squared) or squared < -1.0e-12:
        raise FloatingPointError("quadraticized metric produced an invalid step norm")
    return math.sqrt(max(squared, 0.0)) / (
        ANGSTROM_TO_BOHR * math.sqrt(max(int(atom_count), 1))
    )


def _quadraticized_gdiis_history(
    coordinate_map,
    history: Sequence[tuple[np.ndarray, float, np.ndarray]],
    current_q: np.ndarray,
) -> list[tuple[np.ndarray, float, np.ndarray]]:
    """Express accepted GDIIS points in the current local quadratic chart."""

    origin = np.asarray(current_q, dtype=float).reshape(-1)
    transformed = []
    for history_q, energy, history_gradient in history:
        displacement = np.asarray(history_q, dtype=float).reshape(-1) - origin
        transformed.append(
            (
                coordinate_map.forward(displacement),
                float(energy),
                coordinate_map.covector_to_transformed(displacement, history_gradient),
            )
        )
    return transformed


def _geometric_trust_region_step(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    gradient: np.ndarray,
    radius: float,
    settings: OptimizerSettings,
    *,
    metric: np.ndarray | None = None,
    damping: float = 0.0,
    transition_mode_reference: TransitionModeReference | None = None,
) -> StepProposal:
    """Restricted-step RFO in the supplied positive-definite local metric.

    The RFO level shift is determined in the orthonormal full-metric chart.
    Ordinary coordinate models subsequently use the shared nonlinear
    Cartesian trust enforcer. Quadraticized RFO instead interprets this same
    quadratic constraint as the exact geodesic ball of its designed local
    pullback metric and performs Cartesian realization only as a validity
    check.
    """
    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    gradient_vector = np.asarray(gradient, dtype=float).reshape(-1)
    if settings.stationary_point == "transition_state":
        return _transition_state_trust_region_step(
            service,
            current,
            q,
            matrix,
            gradient_vector,
            radius,
            settings,
            metric=metric,
            transition_mode_reference=transition_mode_reference,
        )
    if getattr(getattr(service, "coordinate_model", None), "kind", None) == "simple_redundant":
        # Solve only on range(B): no artificial stiffness or RFO roots in
        # redundant null directions. The lifted step still targets all rows.
        j = service.coordinate_directions(current.coordinates_angstrom).T
        _, singular, vt = np.linalg.svd(j * ANGSTROM_TO_BOHR, full_matrices=False)
        keep = singular > max(singular[0] * 1.0e-10, 1.0e-12)
        lift = vt[keep].T / singular[keep]
        effective_hessian, inner, minimum, condition, floor = _minimum_effective_hessian_model(
            lift.T @ matrix @ lift, settings
        )
        inverse_sqrt_metric = lift @ inner
    else:
        effective_hessian, inverse_sqrt_metric, minimum, condition, floor = (
            _minimum_effective_hessian_model(matrix, settings, metric=metric)
        )
    gradient_vector = inverse_sqrt_metric.T @ gradient_vector

    def rfo_step(shift: float) -> np.ndarray:
        size = gradient_vector.size
        if size == 0:
            return np.zeros(0, dtype=float)
        augmented = np.zeros((size + 1, size + 1), dtype=float)
        augmented[:-1, :-1] = effective_hessian + max(float(shift), 0.0) * np.eye(size)
        augmented[:-1, -1] = gradient_vector
        augmented[-1, :-1] = gradient_vector
        values, vectors = np.linalg.eigh(augmented)
        root = vectors[:, int(np.argmin(values))]
        if abs(float(root[-1])) <= 1.0e-14:
            raise np.linalg.LinAlgError("singular RS-RFO root")
        step = np.asarray(root[:-1] / root[-1], dtype=float)
        if float(gradient_vector @ step) > 0.0:
            step *= -1.0
        return step

    def physical_step(step: np.ndarray) -> np.ndarray:
        return inverse_sqrt_metric @ np.asarray(step, dtype=float)

    shift = max(float(damping), 0.0)
    step = rfo_step(shift)
    # In the orthonormal metric chart, ||step|| is the total metric distance in
    # bohr-equivalent units. LINK reports the radius per atom in angstrom-
    # equivalent units, hence the sqrt(natom) conversion. For ordinary charts
    # this is followed by finite Cartesian enforcement; for quadraticized RFO
    # it is already the exact finite distance in the pullback metric.
    metric_target = (
        float(radius)
        * ANGSTROM_TO_BOHR
        * math.sqrt(max(int(current.coordinates_angstrom.shape[0]), 1))
    )
    step_norm = float(np.linalg.norm(step))
    active = not np.isfinite(step_norm) or step_norm > 1.1 * metric_target
    if active:
        lower = shift
        upper = max(1.0e-8, 2.0 * max(shift, floor))
        upper_step = rfo_step(upper)
        for _ in range(32):
            upper_norm = float(np.linalg.norm(upper_step))
            if np.isfinite(upper_norm) and upper_norm <= metric_target:
                break
            lower = upper
            upper *= 2.0
            upper_step = rfo_step(upper)
        else:
            raise RuntimeError("unable to bracket an RS-RFO metric-trust step")
        # The shifted positive quadratic model has a monotonically decreasing
        # norm.  A loose 10% algebraic target mirrors the established
        # geomeTRIC strategy; exact finite-chart enforcement happens once in
        # The caller applies the stationary-point-specific trust contract.
        step = upper_step
        for _ in range(32):
            shift = 0.5 * (lower + upper)
            step = rfo_step(shift)
            step_norm = float(np.linalg.norm(step))
            if np.isfinite(step_norm) and 0.9 * metric_target <= step_norm <= metric_target:
                break
            if not np.isfinite(step_norm) or step_norm > metric_target:
                lower = shift
            else:
                upper = shift
        if not np.isfinite(step_norm) or step_norm > metric_target:
            shift = upper
            step = rfo_step(shift)
    policy = "rs_rfo_cartesian_trust"
    if active:
        policy += "_restricted"
    if minimum < -settings.min_hessian_eigenvalue:
        policy += "_positive_model"
    proposal = StepProposal(
        step=physical_step(step),
        policy=policy,
        hessian_min_eigenvalue=minimum,
        hessian_condition=condition,
        damping_shift=shift,
    )
    return proposal


def _preconditioned_cauchy_step(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    gradient: np.ndarray,
    radius: float,
    settings: OptimizerSettings,
) -> StepProposal:
    """Return the trust-restricted Cauchy point of the full-metric model.

    In the orthonormal chart ``y = G**(1/2) q``, the Cauchy direction is
    ``-g_y`` and its unconstrained minimizer is
    ``alpha = (g_y.T g_y) / (g_y.T H_y g_y)``.  The common nonlinear
    Cartesian trust solver then restricts that single model step if needed.
    """

    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    gradient_vector = np.asarray(gradient, dtype=float).reshape(-1)
    effective, inverse_sqrt_metric, minimum, condition, _floor = _minimum_effective_hessian_model(
        matrix,
        settings,
        metric=service.optimizer_metric(current.coordinates_angstrom),
    )
    scaled_gradient = inverse_sqrt_metric @ gradient_vector
    numerator = float(scaled_gradient @ scaled_gradient)
    denominator = float(scaled_gradient @ effective @ scaled_gradient)
    if numerator <= np.finfo(float).eps or denominator <= np.finfo(float).eps:
        scaled_step = np.zeros_like(scaled_gradient)
    else:
        scaled_step = -(numerator / denominator) * scaled_gradient
    metric_target = (
        float(radius)
        * ANGSTROM_TO_BOHR
        * math.sqrt(max(int(current.coordinates_angstrom.shape[0]), 1))
    )
    scaled_norm = float(np.linalg.norm(scaled_step))
    if np.isfinite(scaled_norm) and scaled_norm > metric_target > 0.0:
        scaled_step *= metric_target / scaled_norm
    step = inverse_sqrt_metric @ scaled_step
    proposal = StepProposal(
        step=step,
        policy="full_metric_cauchy_control",
        hessian_min_eigenvalue=minimum,
        hessian_condition=condition,
        damping_shift=0.0,
    )
    return proposal


def _transition_state_trust_region_step(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    gradient: np.ndarray,
    radius: float,
    settings: OptimizerSettings,
    *,
    metric: np.ndarray | None = None,
    transition_mode_reference: TransitionModeReference | None = None,
) -> StepProposal:
    """Return a transition-state step in GDV or quadraticized Wilson-metric form."""

    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    if settings.step_model == "quadraticized_rfo":
        orthonormal, inverse_sqrt_metric = _orthonormal_optimizer_hessian(
            matrix, metric, settings
        )
        eigenvalues, eigenvectors = np.linalg.eigh(orthonormal)
        projected_gradient = eigenvectors.T @ (
            inverse_sqrt_metric @ np.asarray(gradient, dtype=float)
        )
        result = dual_shift_partitioned_rfo_step(
            eigenvalues, projected_gradient, 0,
            absolute_floor=settings.min_hessian_eigenvalue,
            maximum_condition=settings.max_hessian_condition,
        )
        optimizer_candidates = inverse_sqrt_metric @ eigenvectors
        mode_candidates = _cartesian_transition_mode_candidates(
            eigenvectors, inverse_sqrt_metric,
            service.coordinate_directions(current.coordinates_angstrom),
        )
        mode_overlap, mode_vector = _gdv_first_mode_reference(
            mode_candidates, optimizer_candidates,
            current.coordinates_angstrom, transition_mode_reference,
        )
        return StepProposal(
            step=optimizer_candidates @ result.step,
            policy=f"quadraticized_metric_index_one_prfo_raw_spectrum_index_{result.raw_index}",
            hessian_min_eigenvalue=float(np.min(eigenvalues)),
            hessian_condition=result.condition_number,
            damping_shift=0.0,
            transition_mode_index=0,
            transition_mode_overlap=mode_overlap,
            transition_mode_vector=mode_vector,
            transition_ascending_shift=result.ascending_shift,
            transition_descending_shift=result.descending_shift,
            prediction_hessian=matrix.copy(),
        )
    unit_scales = np.asarray(service.gdv_internal_coordinate_scales(), dtype=float).reshape(-1)
    if (
        unit_scales.shape != (matrix.shape[0],)
        or np.any(~np.isfinite(unit_scales))
        or np.any(unit_scales <= 0.0)
    ):
        raise ValueError("GDV coordinate-unit scales do not match the optimizer model")
    inverse_unit_scales = 1.0 / unit_scales
    gdv_matrix = inverse_unit_scales[:, None] * matrix * inverse_unit_scales[None, :]
    # l103.F:DiagFC diagonalizes FC itself.  ReadAllGIC does not solve the
    # generalized Wilson-metric eigenproblem used by LINK's minimum solver.
    # Its distance variables are in bohr, whereas SONIC stores them in
    # angstrom; angular variables are radians in both programs.
    del metric, q
    raw_values, eigenvectors = np.linalg.eigh(gdv_matrix)
    optimizer_candidates = inverse_unit_scales[:, None] * eigenvectors
    mode_candidates = _cartesian_transition_mode_candidates(
        eigenvectors,
        np.diag(inverse_unit_scales),
        service.coordinate_directions(current.coordinates_angstrom),
    )
    # l103.F fixes ModMax=1: after the ordered eigensolve this is always mode
    # zero in Python.  The previous reference is retained only to report an
    # overlap; it must never change the selected DXRFO root.
    mode_index = 0
    mode_overlap, mode_vector = _gdv_first_mode_reference(
        mode_candidates,
        optimizer_candidates,
        current.coordinates_angstrom,
        transition_mode_reference,
    )
    gdv_gradient = inverse_unit_scales * np.asarray(gradient, dtype=float)
    projected = eigenvectors.T @ gdv_gradient
    coordinate_kind = (
        str(getattr(getattr(service, "coordinate_model", None), "kind", "")).strip().lower()
    )
    if coordinate_kind == "sycart":
        # SYCART and the explicitly quadraticized SONIC model use one
        # ascending partition.  A Bofill update can introduce additional
        # negative directions even near an index-one saddle; their transverse
        # step curvatures are conditioned without altering the stored Hessian.
        sycart_result = dual_shift_partitioned_rfo_step(
            raw_values,
            projected,
            0,
            absolute_floor=settings.min_hessian_eigenvalue,
            maximum_condition=settings.max_hessian_condition,
        )
        eigen_step = sycart_result.step
        raw_index = sycart_result.raw_index
        ascending_shift = sycart_result.ascending_shift
        descending_shift = sycart_result.descending_shift
        condition = sycart_result.condition_number
        policy = f"sycart_index_one_prfo_raw_spectrum_index_{raw_index}"
    else:
        result = gdv_dxrfo_step(
            raw_values,
            projected,
            maximum_internal_step=float(radius),
        )
        if not result.ok:
            raise np.linalg.LinAlgError("GDV DXRFO did not produce an acceptable step")
        eigen_step = result.step
        raw_index = result.raw_index
        ascending_shift = result.lambda0
        descending_shift = result.lambda_stable
        magnitudes = np.abs(raw_values)
        condition = float(np.max(magnitudes) / max(float(np.min(magnitudes)), np.finfo(float).eps))
        policy = f"gdv_dxrfo_raw_spectrum_index_{raw_index}"
    step = inverse_unit_scales * (eigenvectors @ eigen_step)
    proposal = StepProposal(
        step=np.asarray(step, dtype=float),
        policy=policy,
        hessian_min_eigenvalue=float(np.min(raw_values)) if raw_values.size else 0.0,
        hessian_condition=condition,
        damping_shift=0.0,
        transition_mode_index=mode_index,
        transition_mode_overlap=mode_overlap,
        transition_mode_vector=mode_vector,
        transition_ascending_shift=ascending_shift,
        transition_descending_shift=descending_shift,
        prediction_hessian=matrix.copy(),
    )
    return proposal


def _gdv_first_mode_reference(
    cartesian_candidates: np.ndarray,
    optimizer_candidates: np.ndarray,
    coordinates_angstrom: np.ndarray,
    previous: TransitionModeReference | None,
) -> tuple[float, TransitionModeReference]:
    """Describe GDV's first ordered mode without using tracking to select it."""

    cartesian = np.asarray(cartesian_candidates, dtype=float)
    optimizer = np.asarray(optimizer_candidates, dtype=float)
    coordinates = np.asarray(coordinates_angstrom, dtype=float)
    if cartesian.ndim != 2 or cartesian.shape[1] == 0:
        raise ValueError("GDV transition-mode candidates cannot be empty")
    if optimizer.ndim != 2 or optimizer.shape[1] != cartesian.shape[1]:
        raise ValueError("GDV optimizer-mode candidates have the wrong shape")
    vector = cartesian[:, 0].copy()
    optimizer_vector = optimizer[:, 0].copy()
    overlap = 1.0
    if previous is not None:
        old_coordinates = np.asarray(previous.coordinates_angstrom, dtype=float)
        old_vector = np.asarray(previous.cartesian_vector, dtype=float).reshape(-1)
        if old_coordinates.shape != coordinates.shape or old_vector.shape != vector.shape:
            raise ValueError("GDV first-mode reference has the wrong shape")
        rotation = kabsch_rotation(old_coordinates, coordinates)
        transported = (old_vector.reshape((-1, 3)) @ rotation).reshape(-1)
        transported /= max(float(np.linalg.norm(transported)), 1.0e-30)
        signed_overlap = float(vector @ transported)
        overlap = abs(signed_overlap)
        if signed_overlap < 0.0:
            vector *= -1.0
            optimizer_vector *= -1.0
    return overlap, TransitionModeReference(
        cartesian_vector=vector,
        coordinates_angstrom=coordinates.copy(),
        cartesian_subspace=vector.reshape((-1, 1)),
        optimizer_vector=optimizer_vector,
        selection_policy="gdv_first_ordered_mode",
    )


def _select_transition_mode(
    cartesian_candidates: np.ndarray,
    settings: OptimizerSettings,
    reference: TransitionModeReference | None,
    coordinates_angstrom: np.ndarray,
    *,
    eigenvalues: np.ndarray | None = None,
    reaction_directions: np.ndarray | None = None,
    optimizer_candidates: np.ndarray | None = None,
) -> tuple[int, float, TransitionModeReference]:
    """Select a reaction mode while tracking near-degenerate subspaces."""

    vectors = np.asarray(cartesian_candidates, dtype=float)
    coordinates = np.asarray(coordinates_angstrom, dtype=float)
    if vectors.ndim != 2 or vectors.shape[0] != coordinates.size:
        raise ValueError("transition-mode candidates must be Cartesian tangent columns")
    if vectors.shape[1] == 0:
        raise ValueError("transition-mode candidates cannot be empty")
    values = None if eigenvalues is None else np.asarray(eigenvalues, dtype=float).reshape(-1)
    if values is not None and values.shape != (vectors.shape[1],):
        raise ValueError("transition-mode eigenvalues have the wrong dimension")
    if reference is None:
        if settings.transition_mode >= vectors.shape[1]:
            raise ValueError(
                f"transition_mode {settings.transition_mode} exceeds the "
                f"{vectors.shape[1]}-mode optimizer Hessian"
            )
        selection = condition_aware_reaction_mode(
            (np.zeros(vectors.shape[1], dtype=float) if values is None else values),
            vectors,
            reaction_directions,
            settings.transition_mode,
            absolute_floor=settings.min_hessian_eigenvalue,
            maximum_condition=settings.max_hessian_condition,
        )
        index = selection.index
        overlap = 1.0
        vector = vectors[:, index].copy()
        optimizer_vector = None
        if optimizer_candidates is not None:
            optimizer_matrix = np.asarray(optimizer_candidates, dtype=float)
            if optimizer_matrix.ndim != 2 or optimizer_matrix.shape[1] != vectors.shape[1]:
                raise ValueError("optimizer mode candidates have the wrong shape")
            optimizer_vector = optimizer_matrix[:, index].copy()
        cluster = _near_degenerate_mode_indices(values, index, settings)
        subspace = _orthonormal_cartesian_subspace(vectors[:, cluster])
    else:
        selection = None
        previous = np.asarray(reference.cartesian_vector, dtype=float).reshape(-1)
        if previous.shape != (vectors.shape[0],):
            raise ValueError("tracked transition mode has the wrong dimension")
        previous_coordinates = np.asarray(reference.coordinates_angstrom, dtype=float)
        if previous_coordinates.shape != coordinates.shape:
            raise ValueError("tracked transition-mode geometry has the wrong shape")
        rotation = kabsch_rotation(previous_coordinates, coordinates)
        previous = (previous.reshape((-1, 3)) @ rotation).reshape(-1)
        previous /= max(float(np.linalg.norm(previous)), 1.0e-30)
        previous_subspace = (
            previous.reshape((-1, 1))
            if reference.cartesian_subspace is None
            else np.asarray(reference.cartesian_subspace, dtype=float)
        )
        if previous_subspace.ndim != 2 or previous_subspace.shape[0] != vectors.shape[0]:
            raise ValueError("tracked transition-mode subspace has the wrong dimension")
        transported = np.column_stack(
            [(column.reshape((-1, 3)) @ rotation).reshape(-1) for column in previous_subspace.T]
        )
        transported = _orthonormal_cartesian_subspace(transported)
        # Select the individual eigenvector with the largest overlap with the
        # transported reaction vector.  The previous implementation selected
        # from the overlap of the whole near-degenerate subspace, which is
        # invariant under rotations but does not identify a unique vector.
        # That allowed the reported uphill mode to jump between unrelated
        # roots while the subspace overlap remained high (the TS4/TS10
        # failure mode).  Keep the subspace for degeneracy diagnostics and
        # Cartesian transport, but make the root choice auditable and
        # continuous.
        if optimizer_candidates is not None and reference.optimizer_vector is not None:
            optimizer_matrix = np.asarray(optimizer_candidates, dtype=float)
            previous_optimizer = np.asarray(reference.optimizer_vector, dtype=float).reshape(-1)
            if (
                optimizer_matrix.ndim != 2
                or optimizer_matrix.shape[1] != vectors.shape[1]
                or previous_optimizer.shape != (vectors.shape[1],)
            ):
                raise ValueError("internal transition-mode reference has the wrong shape")
            previous_optimizer /= max(float(np.linalg.norm(previous_optimizer)), 1.0e-30)
            vector_overlaps = np.abs(optimizer_matrix.T @ previous_optimizer)
        else:
            vector_overlaps = np.abs(vectors.T @ previous)
        index = int(np.argmax(vector_overlaps))
        cluster = _near_degenerate_mode_indices(values, index, settings)
        subspace = _orthonormal_cartesian_subspace(vectors[:, cluster])
        overlap = float(np.linalg.norm(subspace.T @ previous))
        if subspace.shape[1] == transported.shape[1]:
            left, _singular, right_t = np.linalg.svd(
                subspace.T @ transported,
                full_matrices=False,
            )
            subspace = subspace @ left @ right_t
        overlaps = vectors.T @ previous
        signed_overlap = float(overlaps[index])
        vector = vectors[:, index].copy()
        optimizer_vector = None
        if optimizer_candidates is not None:
            optimizer_vector = np.asarray(optimizer_candidates, dtype=float)[:, index].copy()
            if (
                float(
                    optimizer_vector
                    @ (
                        np.asarray(reference.optimizer_vector, dtype=float)
                        if reference.optimizer_vector is not None
                        else optimizer_vector
                    )
                )
                < 0.0
            ):
                optimizer_vector *= -1.0
        if signed_overlap < 0.0:
            vector *= -1.0
    return (
        index,
        overlap,
        TransitionModeReference(
            vector,
            coordinates.copy(),
            cartesian_subspace=subspace,
            optimizer_vector=optimizer_vector,
            selection_policy=(
                reference.selection_policy if selection is None else selection.policy
            ),
            reaction_overlap=(
                reference.reaction_overlap if selection is None else selection.selected_overlap
            ),
            isotropic_overlap=(
                reference.isotropic_overlap if selection is None else selection.isotropic_overlap
            ),
        ),
    )


def _select_exact_index_one_transition_mode(
    cartesian_candidates: np.ndarray,
    optimizer_candidates: np.ndarray,
    eigenvalues: np.ndarray,
    settings: OptimizerSettings,
    reference: TransitionModeReference | None,
    coordinates_angstrom: np.ndarray,
) -> tuple[int, float, TransitionModeReference]:
    """Select the unique negative exact-Hessian mode for IRC initiation.

    Mode tracking remains an overlap validation.  It must not replace the
    unique negative eigenvector with a positive-curvature mode after an exact
    index-one Hessian has been computed.
    """

    vectors = np.asarray(cartesian_candidates, dtype=float)
    optimizer = np.asarray(optimizer_candidates, dtype=float)
    values = np.asarray(eigenvalues, dtype=float).reshape(-1)
    if (
        vectors.ndim != 2
        or optimizer.ndim != 2
        or vectors.shape[1] != values.size
        or optimizer.shape[1] != values.size
    ):
        raise ValueError("exact transition-mode candidates have incompatible dimensions")
    negative = np.flatnonzero(values < -settings.min_hessian_eigenvalue)
    if negative.size != 1:
        raise ValueError(
            "exact IRC initiation requires one negative optimizer-Hessian mode; "
            f"found {negative.size}"
        )
    index = int(negative[0])
    overlap, selected = _gdv_first_mode_reference(
        vectors[:, index : index + 1],
        optimizer[:, index : index + 1],
        np.asarray(coordinates_angstrom, dtype=float),
        reference,
    )
    return (
        index,
        overlap,
        replace(selected, selection_policy="exact_unique_negative_mode"),
    )


def _near_degenerate_mode_indices(
    eigenvalues: np.ndarray | None,
    index: int,
    settings: OptimizerSettings,
) -> np.ndarray:
    """Return the numerical eigenvalue cluster containing one tracked mode."""

    if eigenvalues is None:
        return np.asarray((index,), dtype=int)
    values = np.asarray(eigenvalues, dtype=float).reshape(-1)
    scale = max(float(np.max(np.abs(values))), settings.min_hessian_eigenvalue)
    tolerance = max(
        settings.min_hessian_eigenvalue,
        math.sqrt(np.finfo(float).eps) * scale,
    )
    return np.flatnonzero(np.abs(values - values[index]) <= tolerance)


def _orthonormal_cartesian_subspace(vectors: np.ndarray) -> np.ndarray:
    """Return a deterministic orthonormal basis for Cartesian mode columns."""

    matrix = np.asarray(vectors, dtype=float)
    if matrix.ndim != 2 or matrix.shape[1] == 0:
        raise ValueError("transition-mode subspace cannot be empty")
    basis, triangular = np.linalg.qr(matrix, mode="reduced")
    diagonal = np.diag(triangular)
    if np.any(~np.isfinite(diagonal)) or np.any(np.abs(diagonal) <= 1.0e-30):
        raise ValueError("transition-mode subspace is rank deficient")
    signs = np.where(diagonal < 0.0, -1.0, 1.0)
    return basis * signs


def _cartesian_transition_mode_candidates(
    eigenvectors: np.ndarray,
    inverse_sqrt_metric: np.ndarray,
    coordinate_directions: np.ndarray,
) -> np.ndarray:
    """Map orthonormal-chart modes into normalized Cartesian tangents."""

    vectors = np.asarray(eigenvectors, dtype=float)
    inverse_sqrt = np.asarray(inverse_sqrt_metric, dtype=float)
    directions = np.asarray(coordinate_directions, dtype=float)
    if vectors.ndim != 2 or vectors.shape[0] != vectors.shape[1]:
        raise ValueError("transition-mode eigenvectors must form a square matrix")
    if inverse_sqrt.shape != vectors.shape:
        raise ValueError("transition-mode metric transform has the wrong shape")
    if directions.ndim != 2 or directions.shape[0] != vectors.shape[0]:
        raise ValueError("transition-mode Cartesian directions have the wrong shape")
    cartesian = directions.T @ (inverse_sqrt @ vectors)
    norms = np.linalg.norm(cartesian, axis=0)
    if np.any(~np.isfinite(norms)) or np.any(norms <= 1.0e-30):
        raise ValueError("transition-mode Cartesian tangent is singular")
    return cartesian / norms


def _initial_transition_mode_reference(
    hessian: np.ndarray,
    metric: np.ndarray,
    settings: OptimizerSettings,
    *,
    coordinate_unit_scales: np.ndarray,
    coordinate_directions: np.ndarray,
    coordinates_angstrom: np.ndarray,
    reaction_directions: np.ndarray | None = None,
) -> TransitionModeReference | None:
    """Record GDV's first ordered seed mode independently of final validation."""
    if settings.stationary_point != "transition_state":
        return None
    del metric
    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    unit_scales = np.asarray(coordinate_unit_scales, dtype=float).reshape(-1)
    if (
        unit_scales.shape != (matrix.shape[0],)
        or np.any(~np.isfinite(unit_scales))
        or np.any(unit_scales <= 0.0)
    ):
        raise ValueError("GDV coordinate-unit scales do not match the initial Hessian")
    inverse_unit_scales = 1.0 / unit_scales
    gdv_matrix = inverse_unit_scales[:, None] * matrix * inverse_unit_scales[None, :]
    values, vectors = np.linalg.eigh(gdv_matrix)
    optimizer_vectors = inverse_unit_scales[:, None] * vectors
    candidates = _cartesian_transition_mode_candidates(
        vectors,
        np.diag(inverse_unit_scales),
        coordinate_directions,
    )
    _overlap, reference = _gdv_first_mode_reference(
        candidates,
        optimizer_vectors,
        coordinates_angstrom,
        None,
    )
    return reference


def _transition_reaction_cartesian_directions(
    model: OptimizerCoordinateModel,
    coordinate_directions: np.ndarray,
) -> np.ndarray | None:
    """Consume SMITH's frozen TS-reaction family without chemical inference."""

    definition = model.sonic_definition
    if model.kind != "sonic" or definition is None:
        return None
    positions = {label: index for index, label in enumerate(model.labels)}
    selected: list[int] = []
    for gic in definition.gics:
        if gic.family != "TS_REACTION_DISTANCE":
            continue
        position = positions.get(gic.name, positions.get(gic.identifier))
        if position is not None:
            selected.append(position)
    if not selected:
        return None
    directions = np.asarray(coordinate_directions, dtype=float)
    if directions.ndim != 2 or directions.shape[0] != len(model.labels):
        raise ValueError("reaction-family directions do not match the SONIC chart")
    return directions[np.asarray(sorted(set(selected)), dtype=int)].T


def _cartesian_rms_displacement_angstrom(
    before: np.ndarray,
    after: np.ndarray,
) -> float:
    """Return aligned RMS displacement in Angstrom per atom.

    This is the sole norm used by LINK's Cartesian trust region.  Dividing by
    the atom count, rather than by ``3 * natom``, makes the radius identical to
    the molecular-optimization convention used for Cartesian RMS steps and
    independent of the optimizer-coordinate representation.
    """

    displacement = aligned_cartesian_displacement(before, after)
    return float(np.sqrt(np.sum(displacement * displacement) / max(displacement.shape[0], 1)))


def _safeguarded_bracket_trial(
    lower: float,
    upper: float,
    lower_value: float,
    upper_value: float,
) -> float:
    """Return a secant trial kept strictly inside a valid scalar bracket."""

    left = float(lower)
    right = float(upper)
    span = right - left
    if span <= 0.0 or not np.isfinite(span):
        raise ValueError("invalid scalar-root bracket")
    low = float(lower_value)
    high = float(upper_value)
    if np.isfinite(low) and np.isfinite(high) and high > low:
        fraction = -low / (high - low)
        fraction = float(np.clip(fraction, 0.1, 0.9))
    else:
        fraction = 0.5
    return left + fraction * span


def _restrict_step_to_cartesian_trust(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    step: np.ndarray,
    radius: float,
    settings: OptimizerSettings,
) -> tuple[np.ndarray, float, float, int]:
    """Restrict any optimizer step using its nonlinear Cartesian realization.

    The scalar search is representation agnostic: it follows the proposed ray
    in optimizer space, repeatedly performs the authoritative back-transform,
    and brackets the first boundary of the aligned Cartesian atomic-RMS trust
    region.  A safeguarded secant interpolation accelerates nearly linear
    charts while bisection bounds retain convergence for strongly curved
    coordinates or failed intermediate back-transforms.

    Returns ``(restricted_step, realized_rmsd, scale, iterations)``.  No QM
    evaluations are performed.
    """

    vector = np.asarray(step, dtype=float).reshape(-1)
    trust_radius = float(radius)
    if trust_radius <= 0.0 or not np.isfinite(trust_radius):
        raise ValueError("Cartesian trust radius must be finite and positive")
    if not np.all(np.isfinite(vector)):
        raise ValueError("optimizer step contains non-finite values")
    if vector.size == 0 or float(np.linalg.norm(vector)) <= np.finfo(float).eps:
        return vector.copy(), 0.0, 1.0, 0

    realization_by_scale: dict[float, tuple[float, bool]] = {}
    realize_for_trust = getattr(
        service,
        "_coordinates_from_q_for_trust",
        service.coordinates_from_q,
    )

    def realized_rmsd(scale: float) -> tuple[float, bool]:
        key = float(scale)
        if key not in realization_by_scale:
            coordinates = None
            rejection = "unrealized"
            try:
                coordinates = realize_for_trust(q + key * vector)
                rejection = _realized_geometry_rejection(service, coordinates, settings)
            except (FloatingPointError, RuntimeError, ValueError, np.linalg.LinAlgError):
                rejection = "fast_backtransform_failed"
            # A bounded trust probe is normally sufficient and avoids paying
            # for exhaustive chart recovery on every scalar-search sample.
            # Near a singular constrained chart it can fail before LINK's
            # production corrector has exhausted its continuation budget.
            # Retry that same trial with the authoritative realization before
            # treating the point as outside the chart and shrinking the step.
            production_realizer = getattr(service, "coordinates_from_q", None)
            if (
                (coordinates is None or rejection)
                and hasattr(service, "_coordinates_from_q_for_trust")
                and callable(production_realizer)
            ):
                try:
                    coordinates = production_realizer(q + key * vector)
                    rejection = _realized_geometry_rejection(service, coordinates, settings)
                except (FloatingPointError, RuntimeError, ValueError, np.linalg.LinAlgError):
                    coordinates = None
                    rejection = "production_backtransform_failed"
            if coordinates is not None and not rejection:
                value = (
                    _cartesian_rms_displacement_angstrom(
                        current.coordinates_angstrom,
                        coordinates,
                    )
                )
                valid = True
            else:
                value = math.inf
                valid = False
            realization_by_scale[key] = float(value), bool(valid)
        return realization_by_scale[key]

    tolerance = float(settings.cartesian_trust_tolerance)
    target = (1.0 - tolerance) * trust_radius
    lower_scale = 0.0
    lower_rmsd = 0.0
    upper_scale = 1.0
    upper_rmsd = math.inf
    upper_valid = False
    best_step = np.zeros_like(vector)
    best_scale = 0.0
    best_rmsd = 0.0
    iterations = 0

    # The Wilson metric already supplies the Cartesian tangent of the full
    # optimizer step.  Use it to seed the nonlinear scalar solve near the
    # trust boundary instead of first realizing a usually enormous full step.
    # Every accepted scale is still verified by the authoritative finite
    # back-transform; the predictor only chooses the first scalar probe.
    predictor_scale = 1.0
    coordinate_kind = getattr(getattr(service, "coordinate_model", None), "kind", None)
    cartesian_step = getattr(service, "cartesian_step_from_optimizer", None)
    if callable(cartesian_step):
        try:
            tangent = np.asarray(
                cartesian_step(vector, current.coordinates_angstrom),
                dtype=float,
            )
            tangent_coordinates = np.asarray(
                current.coordinates_angstrom, dtype=float
            ) + tangent.reshape(np.asarray(current.coordinates_angstrom).shape)
            tangent_rmsd = _cartesian_rms_displacement_angstrom(
                current.coordinates_angstrom,
                tangent_coordinates,
            )
            if np.isfinite(tangent_rmsd) and tangent_rmsd > target:
                predictor_margin = 0.8 if coordinate_kind == "sonic" else 1.0
                predictor_scale = float(
                    np.clip(
                        predictor_margin * target / tangent_rmsd,
                        8.0 * np.finfo(float).eps,
                        1.0,
                    )
                )
        except (FloatingPointError, RuntimeError, ValueError, np.linalg.LinAlgError):
            predictor_scale = 1.0

    if coordinate_kind == "sonic":
        try:
            from . import _optimizer_native
        except ImportError:  # pragma: no cover - portable pure-Python build
            _optimizer_native = None
        if _optimizer_native is not None and hasattr(_optimizer_native, "restrict_cartesian_trust"):
            try:
                native_step, native_rmsd, native_scale, native_iterations = (
                    _optimizer_native.restrict_cartesian_trust(
                        vector,
                        realized_rmsd,
                        float(predictor_scale),
                        trust_radius,
                        tolerance,
                        # A SONIC trust probe is already certified by the
                        # Wilson tangent and the authoritative nonlinear
                        # realization.  If that first probe is outside the
                        # domain, a short geometric bracket is sufficient;
                        # allowing the generic 48--step scalar search here
                        # can repeat the expensive sparse back-transform
                        # many times for one optimizer step.
                        min(
                            int(settings.cartesian_trust_max_iterations),
                            2,
                        ),
                        1,
                    )
                )
                return (
                    np.asarray(native_step, dtype=float),
                    float(native_rmsd),
                    float(native_scale),
                    int(native_iterations),
                )
            except RuntimeError as exc:
                # The compiled scalar controller can exhaust its bracket when
                # a nonlinear SONIC back-transform rejects the whole initial
                # interval.  The Python controller below has the same trust
                # contract but continues with safeguarded probes, including
                # very small scales.  Do not turn a chart-domain transient
                # into a hard optimizer failure merely because the native
                # fast path ran out of probes.
                if "unable to realize a nonzero optimizer step" not in str(exc):
                    raise

    initial_rmsd, initial_valid = realized_rmsd(predictor_scale)
    iterations += int(predictor_scale < 1.0)
    if (
        predictor_scale == 1.0
        and initial_valid
        and np.isfinite(initial_rmsd)
        and initial_rmsd <= trust_radius
    ):
        return vector.copy(), float(initial_rmsd), 1.0, 0
    if initial_valid and np.isfinite(initial_rmsd) and initial_rmsd <= target:
        lower_scale = predictor_scale
        lower_rmsd = float(initial_rmsd)
        best_step = predictor_scale * vector
        best_scale = predictor_scale
        best_rmsd = float(initial_rmsd)
        if service.coordinate_model.kind == "sonic":
            # The Wilson metric has already selected the scale and this one
            # authoritative nonlinear realization certifies the Cartesian
            # trust bound.  Chasing the last fraction of the radius with a
            # scalar root search repeats the expensive SONIC back-transform
            # without changing the trust contract.
            return best_step, best_rmsd, best_scale, max(iterations, 1)
        if target - best_rmsd <= tolerance * trust_radius:
            return best_step, best_rmsd, best_scale, max(iterations, 1)
        corrected_scale = min(
            1.0,
            predictor_scale * target / max(best_rmsd, np.finfo(float).eps),
        )
        if corrected_scale > predictor_scale * (1.0 + tolerance):
            corrected_rmsd, corrected_valid = realized_rmsd(corrected_scale)
            iterations += 1
            if corrected_valid and np.isfinite(corrected_rmsd) and corrected_rmsd <= target:
                lower_scale = corrected_scale
                lower_rmsd = float(corrected_rmsd)
                best_step = corrected_scale * vector
                best_scale = corrected_scale
                best_rmsd = float(corrected_rmsd)
                if target - best_rmsd <= tolerance * trust_radius:
                    return best_step, best_rmsd, best_scale, iterations
            else:
                upper_scale = corrected_scale
                upper_rmsd = float(corrected_rmsd)
                upper_valid = bool(corrected_valid)
    else:
        upper_scale = predictor_scale
        upper_rmsd = float(initial_rmsd)
        upper_valid = bool(initial_valid)

    remaining_iterations = max(
        int(settings.cartesian_trust_max_iterations) - iterations,
        0,
    )
    for _bracket_iteration in range(remaining_iterations):
        iterations += 1
        span = upper_scale - lower_scale
        if span <= 8.0 * np.finfo(float).eps:
            break
        trial_scale = _safeguarded_bracket_trial(
            lower_scale,
            upper_scale,
            lower_rmsd - target,
            upper_rmsd - target,
        )
        trial_step = trial_scale * vector
        trial_rmsd, trial_valid = realized_rmsd(trial_scale)

        if trial_valid and np.isfinite(trial_rmsd) and trial_rmsd <= target:
            lower_scale = trial_scale
            lower_rmsd = float(trial_rmsd)
            best_step = trial_step
            best_scale = trial_scale
            best_rmsd = float(trial_rmsd)
            if not upper_valid:
                # A chart-domain boundary is a hard constraint, not another
                # trust target.  The first bracketed valid interior point is
                # deliberately conservative; chasing the largest admissible
                # scale repeats expensive failed back-transforms without
                # adding scientific information.
                break
            if target - best_rmsd <= tolerance * trust_radius:
                break
        else:
            upper_scale = trial_scale
            upper_rmsd = float(trial_rmsd)
            upper_valid = bool(trial_valid)

    if best_scale <= 0.0:
        raise RuntimeError(
            "unable to realize a nonzero optimizer step inside the Cartesian trust region"
        )
    # ``best_rmsd`` was obtained from the exact same finite realization and is
    # cached above.  Repeating the back-transform here used to double the most
    # expensive successful boundary evaluation for no additional safeguard.
    verified_rmsd = best_rmsd
    if verified_rmsd > trust_radius * (1.0 + 8.0 * np.finfo(float).eps):
        raise RuntimeError("Cartesian trust solver returned an out-of-radius step")
    return best_step, float(verified_rmsd), float(best_scale), int(iterations)


def _enforce_proposal_cartesian_trust(
    proposal: StepProposal,
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    radius: float,
    settings: OptimizerSettings,
) -> StepProposal:
    """Apply LINK's single Cartesian trust contract to any step proposal."""

    step, rmsd, scale, iterations = _restrict_step_to_cartesian_trust(
        service,
        current,
        q,
        proposal.step,
        radius,
        settings,
    )
    policy = proposal.policy
    if scale < 1.0 and "realized_cartesian_trust_restricted" not in policy:
        policy += ":realized_cartesian_trust_restricted"
    return replace(
        proposal,
        step=step,
        policy=policy,
        cartesian_rmsd_angstrom=rmsd,
        trust_scale=proposal.trust_scale * scale,
        trust_iterations=proposal.trust_iterations + iterations,
        applied_trust_radius_angstrom=float(radius),
    )


def _recover_tiny_minimum_step_from_tangent_gradient(
    proposal: StepProposal,
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    optimizer_gradient: np.ndarray,
    convergence_gradient: np.ndarray,
    trust_radius: float,
    settings: OptimizerSettings,
) -> StepProposal:
    """Replace a collapsed minimum step by bounded descent in the active tangent.

    Near a singular internal-coordinate chart, the finite Cartesian trust
    realization can contract an RFO step almost to zero even though the
    projected Cartesian force is still large.  The ordinary trust controller
    then accepts a sequence of energy plateaus and the optimizer makes no
    useful progress.  Reconstructing a descent direction from the active
    Cartesian tangent avoids trusting that singular coordinate scaling; LINK
    still realizes and evaluates the constrained step through its normal path.
    """

    if (
        settings.stationary_point != "minimum"
        or trust_radius <= 2.0 * settings.min_trust_radius
    ):
        return proposal
    if proposal.trust_scale >= 0.05:
        return proposal
    realized_rmsd = proposal.cartesian_rmsd_angstrom
    if (
        realized_rmsd is None
        or not math.isfinite(float(realized_rmsd))
        or float(realized_rmsd) >= 0.05 * float(trust_radius)
    ):
        return proposal

    force = np.asarray(convergence_gradient, dtype=float).reshape(-1)
    if force.size != current.coordinates_angstrom.size or not np.all(np.isfinite(force)):
        return proposal
    if (
        float(np.max(np.abs(force))) <= settings.max_force_tolerance
        and _rms(force) <= settings.rms_force_tolerance
    ):
        return proposal

    gradient = np.asarray(optimizer_gradient, dtype=float).reshape(-1)
    atom_count = max(int(current.coordinates_angstrom.shape[0]), 1)
    target_rmsd = min(0.02, 0.25 * float(trust_radius))
    # Try both equivalent descriptions of a tangent descent direction.  The
    # Cartesian-force route is useful for redundant charts, while -g in the
    # actual optimizer coordinates avoids losing the direction when the
    # Cartesian-to-internal pseudoinverse is ill-conditioned near a linear
    # constrained geometry.  Each candidate is still passed through LINK's
    # authoritative finite realization and Cartesian trust check.
    directions: list[np.ndarray] = []
    try:
        directions.append(
            np.asarray(
                service.optimizer_step_from_cartesian(-force, current.coordinates_angstrom),
                dtype=float,
            ).reshape(-1)
        )
    except (FloatingPointError, RuntimeError, ValueError, np.linalg.LinAlgError):
        pass
    directions.append(-gradient)
    best: StepProposal | None = None
    for tangent_step in directions:
        if (
            tangent_step.shape != gradient.shape
            or not np.all(np.isfinite(tangent_step))
            or float(gradient @ tangent_step) >= 0.0
        ):
            continue
        try:
            tangent_cartesian = np.asarray(
                service.cartesian_step_from_optimizer(
                    tangent_step,
                    current.coordinates_angstrom,
                ),
                dtype=float,
            ).reshape(-1)
        except (FloatingPointError, RuntimeError, ValueError, np.linalg.LinAlgError):
            continue
        if tangent_cartesian.shape != force.shape or not np.all(np.isfinite(tangent_cartesian)):
            continue
        tangent_rmsd = float(np.linalg.norm(tangent_cartesian) / math.sqrt(atom_count))
        if not math.isfinite(tangent_rmsd) or tangent_rmsd <= 1.0e-14:
            continue
        rescued = replace(
            proposal,
            step=tangent_step * (target_rmsd / tangent_rmsd),
            policy=f"{proposal.policy}:projected_gradient_recovered_collapsed_chart_step",
            cartesian_rmsd_angstrom=target_rmsd,
            trust_scale=1.0,
        )
        try:
            candidate = _enforce_proposal_cartesian_trust(
                rescued,
                service,
                current,
                q,
                trust_radius,
                settings,
            )
        except (FloatingPointError, RuntimeError, ValueError, np.linalg.LinAlgError):
            continue
        realized = float(candidate.cartesian_rmsd_angstrom or 0.0)
        if best is None or realized > float(best.cartesian_rmsd_angstrom or 0.0):
            best = candidate
    return proposal if best is None else best


def _validate_quadraticized_proposal_realization(
    proposal: StepProposal,
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    radius: float,
    settings: OptimizerSettings,
) -> StepProposal:
    """Validate one local quadraticized step in its pullback metric."""

    vector = np.asarray(proposal.step, dtype=float).reshape(-1)
    coordinates = service.coordinates_from_q(np.asarray(q, dtype=float) + vector)
    rejection = _realized_geometry_rejection(service, coordinates, settings)
    if rejection:
        raise ValueError(f"unrealizable quadraticized proposal: {rejection}")
    rmsd = _cartesian_rms_displacement_angstrom(
        current.coordinates_angstrom,
        coordinates,
    )
    return replace(
        proposal,
        cartesian_rmsd_angstrom=float(rmsd),
        applied_trust_radius_angstrom=float(radius),
    )


def _enforce_minimum_convergence_displacement_trust(
    proposal: StepProposal,
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    settings: OptimizerSettings,
) -> StepProposal:
    """Restrict a terminal minimum step by both Cartesian displacement tests.

    This is applied only after energy and both force criteria are satisfied.
    The restricted geometry is still evaluated by the backend; no zero step
    or unevaluated prospective convergence is manufactured.
    """

    step = np.asarray(proposal.step, dtype=float).reshape(-1).copy()
    total_scale = 1.0
    iterations = 0
    coordinates = service.coordinates_from_q(np.asarray(q, dtype=float) + step)
    for iterations in range(9):
        displacement_bohr = (
            aligned_cartesian_displacement(
                current.coordinates_angstrom,
                coordinates,
            ).reshape(-1)
            * ANGSTROM_TO_BOHR
        )
        maximum = float(np.max(np.abs(displacement_bohr)))
        rms_value = _rms(displacement_bohr)
        if (
            maximum <= settings.max_displacement_tolerance
            and rms_value <= settings.rms_displacement_tolerance
        ):
            break
        scale = 0.98 * min(
            settings.max_displacement_tolerance / max(maximum, np.finfo(float).tiny),
            settings.rms_displacement_tolerance / max(rms_value, np.finfo(float).tiny),
        )
        if not math.isfinite(scale) or scale <= 0.0:
            raise RuntimeError("invalid terminal minimum displacement scale")
        scale = min(0.98, scale)
        step *= scale
        total_scale *= scale
        coordinates = service.coordinates_from_q(np.asarray(q, dtype=float) + step)
    else:
        raise RuntimeError("terminal minimum displacement trust did not converge")
    policy = proposal.policy
    if total_scale < 1.0 and "terminal_displacement_restricted" not in policy:
        policy += ":terminal_displacement_restricted"
    return replace(
        proposal,
        step=step,
        policy=policy,
        cartesian_rmsd_angstrom=_cartesian_rms_displacement_angstrom(
            current.coordinates_angstrom,
            coordinates,
        ),
        trust_scale=proposal.trust_scale * total_scale,
        trust_iterations=proposal.trust_iterations + iterations,
    )


def _enforce_proposal_gdv_internal_trust(
    proposal: StepProposal,
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    radius: float,
) -> StepProposal:
    """Apply GDV ``DXOpt`` with its ``OptDX``/``CrdGRo`` dispatch."""

    step = np.asarray(proposal.step, dtype=float).reshape(-1)
    unit_scales = np.asarray(service.gdv_internal_coordinate_scales(), dtype=float).reshape(-1)
    if (
        unit_scales.shape != step.shape
        or np.any(~np.isfinite(unit_scales))
        or np.any(unit_scales <= 0.0)
    ):
        raise ValueError("GDV internal coordinate units do not match the optimizer step")
    gdv_step = unit_scales * step
    if service.gdv_uses_force_constant_step_weights():
        if proposal.prediction_hessian is None:
            raise ValueError("GDV CrdGRo trust weights require the DXRFO Hessian")
        hessian = np.asarray(proposal.prediction_hessian, dtype=float)
        inverse_unit_scales = 1.0 / unit_scales
        gdv_hessian = inverse_unit_scales[:, None] * hessian * inverse_unit_scales[None, :]
        weights = _gdv_crdgro_step_weights(gdv_step, gdv_hessian)
    else:
        weights = np.asarray(service.gdv_internal_step_weights(), dtype=float).reshape(-1)
    if weights.shape != step.shape or np.any(~np.isfinite(weights)) or np.any(weights <= 0.0):
        raise ValueError("GDV internal trust weights do not match the optimizer step")
    effective_norm = float(np.linalg.norm(weights * gdv_step))
    target = float(radius)
    if not math.isfinite(target) or target <= 0.0:
        raise ValueError("GDV internal trust radius must be positive and finite")
    scale = 1.0 if effective_norm <= target else target / effective_norm
    restricted = step * scale
    coordinates = None
    realization_factor = 1.0
    last_realization_error: ValueError | FloatingPointError | RuntimeError | None = None
    for factor in GDV_REDQ2X_HARD_FAILURE_RETRY_FACTORS:
        try:
            trial_step = restricted * factor
            coordinates = service.coordinates_from_q(np.asarray(q, dtype=float) + trial_step)
            restricted = trial_step
            realization_factor = factor
            break
        except (ValueError, FloatingPointError, RuntimeError) as exc:
            last_realization_error = exc
    if coordinates is None:
        assert last_realization_error is not None
        raise last_realization_error
    rmsd = _cartesian_rms_displacement_angstrom(
        current.coordinates_angstrom,
        coordinates,
    )
    policy = proposal.policy
    if scale < 1.0 and "gdv_internal_trust_restricted" not in policy:
        policy += ":gdv_internal_trust_restricted"
    if realization_factor < 1.0:
        policy += f":gdv_internal_realization_retry_factor_{realization_factor:.9g}"
    return replace(
        proposal,
        step=restricted,
        policy=policy,
        cartesian_rmsd_angstrom=float(rmsd),
        trust_scale=proposal.trust_scale * scale * realization_factor,
        trust_iterations=proposal.trust_iterations + int(realization_factor < 1.0),
        applied_trust_radius_angstrom=target,
    )


def _gdv_crdgro_step_weights(
    gdv_step: np.ndarray,
    gdv_hessian: np.ndarray,
) -> np.ndarray:
    """Replicate ``gdv.j32+/utilam.F:CrdGRo(IOp=5)`` exactly."""

    step = np.asarray(gdv_step, dtype=float).reshape(-1)
    hessian = np.asarray(gdv_hessian, dtype=float)
    if hessian.shape != (step.size, step.size):
        raise ValueError("GDV CrdGRo Hessian does not match the optimizer step")
    if np.any(~np.isfinite(step)) or np.any(~np.isfinite(hessian)):
        raise ValueError("GDV CrdGRo inputs must be finite")
    row_norms = np.linalg.norm(hessian, axis=1)
    force_norm = float(np.linalg.norm(row_norms))
    if not math.isfinite(force_norm) or force_norm <= 0.0:
        raise ValueError("GDV CrdGRo Hessian must have a finite nonzero norm")
    base = np.clip(row_norms * math.sqrt(float(step.size)) / force_norm, 0.1, 1.0)
    displacement_blend = 0.5 * (1.0 + np.tanh(10.0 * (np.abs(step) - 0.7)))
    return base + (1.0 - base) * displacement_blend


def _accepted_optimizer_trust_update(
    damping: float,
    trust_radius: float,
    ratio: float,
    scale: float,
    realized_metric_step: float,
    settings: OptimizerSettings,
) -> tuple[float, float]:
    if settings.stationary_point == "transition_state":
        # l103.F enables UpdDXM by default only when NNeg==0.  Consequently
        # the ordinary Opt=(TS,ReadAllGIC,...) path keeps DXMaxT fixed at its
        # CalcHFFC value (0.300) instead of applying utilnz.F:UpdDXM.  The
        # ratio remains diagnostic, exactly as in the native TS transcript.
        del ratio, scale, realized_metric_step
        return 0.0, float(trust_radius)

    controller = TrustRegionController(
        ControllerSettings(
            acceptance_threshold=settings.acceptance_threshold,
            expansion_factor=settings.trust_region_expansion_factor,
            contraction_factor=settings.trust_region_contraction_factor,
            min_radius=settings.min_trust_radius,
            max_radius=settings.max_trust_radius,
            energy_noise=settings.energy_noise,
            energy_tolerance=settings.energy_tolerance,
        )
    )
    decision = controller.assess(1.0, float(ratio))
    # Expansion depends on whether the realized step reached the boundary in
    # the same metric that defined the proposal. For ordinary LINK models this
    # is Cartesian RMS; quadraticized RFO passes its exact pullback distance.
    # The optimizer-coordinate or trial-reduction scale alone is not enough.
    del scale
    step_fraction = float(realized_metric_step) / max(
        float(trust_radius), np.finfo(float).eps
    )
    if decision.accepted and float(trust_radius) <= settings.min_trust_radius * (
        1.0 + 8.0 * np.finfo(float).eps
    ):
        # An accepted step at the hard floor is evidence that the current
        # radius is usable.  Do not leave the optimizer permanently frozen
        # merely because finite-difference noise makes rho smaller than the
        # ordinary expansion threshold; escape the floor conservatively and
        # let the standard controller take over on subsequent cycles.
        new_radius = min(
            settings.max_trust_radius,
            max(
                settings.min_trust_radius * 2.0,
                settings.min_trust_radius * controller.settings.expansion_factor,
            ),
        )
    else:
        new_radius = controller.radius_after(
            trust_radius,
            decision,
            step_fraction=float(np.clip(step_fraction, 0.0, 1.0)),
        )
    new_damping = 0.0 if decision.ratio >= 0.75 else damping
    if decision.ratio < 0.10:
        new_damping = max(float(new_damping), OPTIMIZER_DAMPING_MIN)
    return new_damping, new_radius


def _rejected_optimizer_trust_update(
    damping: float,
    trust_radius: float,
    realized_metric_step: float,
    settings: OptimizerSettings,
) -> tuple[float, float]:
    controller = TrustRegionController(
        ControllerSettings(
            acceptance_threshold=settings.acceptance_threshold,
            expansion_factor=settings.trust_region_expansion_factor,
            contraction_factor=settings.trust_region_contraction_factor,
            min_radius=settings.min_trust_radius,
            max_radius=settings.max_trust_radius,
            energy_noise=settings.energy_noise,
            energy_tolerance=settings.energy_tolerance,
        )
    )
    return (
        max(float(damping), OPTIMIZER_DAMPING_MIN),
        controller.radius_after_rejection(
            trust_radius,
            realized_step=realized_metric_step,
        ),
    )


def _rejected_optimizer_cartesian_step(
    current: OptimizerEvaluation,
    trial: OptimizerEvaluation,
    proposal: StepProposal,
    message: str,
) -> float:
    """Return the Cartesian size of the geometry that was actually rejected.

    Geometry screening and backend failures occur before a trial evaluation
    can replace ``current``.  In those paths ``trial`` is deliberately the
    current evaluated state, so aligning the two states measures only floating
    point noise and can collapse the trust radius to its hard floor.  The
    proposal already carries the authoritative nonlinear Cartesian
    realization of the rejected candidate and is the correct contraction
    scale.  Energy/model rejections instead use the evaluated trial geometry.
    """

    if message in {"rejected_invalid_geometry", "rejected_evaluation"}:
        proposed = float(proposal.cartesian_rmsd_angstrom)
        if np.isfinite(proposed) and proposed > 0.0:
            return proposed
    return _cartesian_rms_displacement_angstrom(
        current.coordinates_angstrom,
        trial.coordinates_angstrom,
    )


def _evaluate_step_trials(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    gradient: np.ndarray,
    hessian: np.ndarray | None,
    step: np.ndarray,
    settings: OptimizerSettings,
    *,
    iteration: int,
    far_from_minimum: bool = False,
    prediction_function: Callable[[np.ndarray], float] | None = None,
) -> tuple[OptimizerEvaluation, np.ndarray, float, float, float, bool, str, int]:
    current_energy = current.energy_hartree
    candidate_step = np.asarray(step, dtype=float).reshape(-1)
    # Backtrack the initial minimum step while the secant model is empty.
    # Once L-BFGS has accepted curvature pairs, repeated inner energy/gradient
    # trials duplicate calculator work and suppress the quasi-Newton step;
    # ordinary trust-radius rejection is then the authoritative safeguard.
    coordinate_kind = getattr(getattr(service, "coordinate_model", None), "kind", "")
    reductions = (
        max(0, int(settings.line_search_reductions))
        if settings.stationary_point == "minimum"
        and (int(iteration) == 1 or coordinate_kind == "simple_delocalized")
        else 0
    )
    controller = TrustRegionController(
        ControllerSettings(
            acceptance_threshold=settings.acceptance_threshold,
            expansion_factor=settings.trust_region_expansion_factor,
            contraction_factor=settings.trust_region_contraction_factor,
            min_radius=settings.min_trust_radius,
            max_radius=settings.max_trust_radius,
            energy_noise=max(
                float(settings.energy_noise),
                float(settings.energy_increase_tolerance) / 5.0,
            ),
            energy_tolerance=settings.energy_tolerance,
        )
    )
    factor = 1.0
    for attempt in range(reductions + 1):
        realized_request = candidate_step * factor
        candidate_q = q + realized_request
        geometry_message = _candidate_geometry_rejection(service, candidate_q, settings)
        if geometry_message:
            factor *= 0.5
            continue
        try:
            trial = service.evaluate(
                candidate_q,
                tag=f"step-{iteration}",
                requested_properties=(
                    "energy",
                    "gradient",
                )
                if settings.prefer_analytic_gradient
                else ("energy",),
            )
        except RuntimeError:
            return (
                current,
                np.zeros_like(candidate_step),
                0.0,
                0.0,
                -math.inf,
                False,
                "rejected_evaluation",
                1,
            )
        realized_step = np.asarray(trial.q, dtype=float) - np.asarray(q, dtype=float)
        predicted = _step_predicted_reduction(
            gradient,
            hessian,
            realized_step,
            prediction_function,
        )
        actual = current_energy - trial.energy_hartree
        decision = controller.assess(
            predicted,
            actual,
            stationary_point=settings.stationary_point,
        )
        if settings.convergence_profile == "pyfock_ase":
            # ASE BFGS (the native PyFock optimization path) does not reject
            # a finite trial because its energy/model ratio is poor. Keep
            # LINK's geometry safety checks, but do not add a trust-rejection
            # iteration that has no counterpart in the native path.
            decision = TrialDecision(
                True,
                decision.ratio,
                decision.predicted_reduction,
                decision.actual_reduction,
                "accepted_pyfock_ase",
            )
        if settings.stationary_point == "transition_state":
            rho = decision.ratio
            catastrophic = False
        else:
            rho = decision.ratio
            catastrophic = actual < -max(
                0.05,
                10.0 * abs(predicted),
                100.0 * settings.energy_tolerance,
            )
        if catastrophic:
            return (
                trial,
                realized_step,
                predicted,
                actual,
                rho,
                False,
                ("rejected_catastrophic_energy" if catastrophic else f"rejected_{decision.reason}"),
                1,
            )
        if not decision.accepted:
            if attempt < reductions:
                factor *= 0.5
                continue
            return (
                trial,
                realized_step,
                predicted,
                actual,
                rho,
                False,
                f"rejected_{decision.reason}",
                attempt + 1,
            )
        # Analytic trial results already contain the accepted-point gradient;
        # reuse them.  Energy-only backends still require their ordinary
        # accepted-point refresh before LINK forms the finite-difference
        # gradient.
        if not settings.prefer_analytic_gradient:
            trial = service.evaluate(
                trial.q,
                tag=f"accepted-{iteration}",
                requested_properties=("energy",),
            )
        if settings.stationary_point == "transition_state":
            message = "accepted_transition_state_" + decision.reason
        else:
            message = "accepted" if actual >= 0.0 else "accepted_nonmonotone"
        if attempt:
            message += f"_geometry_reduction_{attempt}"
        return trial, realized_step, predicted, actual, rho, True, message, 0
    return (
        current,
        np.zeros_like(candidate_step),
        0.0,
        0.0,
        -math.inf,
        False,
        "rejected_invalid_geometry",
        0,
    )


def _candidate_geometry_rejection(
    service: GeometryEvaluationService,
    q: np.ndarray,
    settings: OptimizerSettings,
) -> str:
    try:
        coords = service.coordinates_from_q(q)
    except (FloatingPointError, RuntimeError, ValueError, np.linalg.LinAlgError) as exc:
        return f"coordinate_back_transform:{exc}"
    return _realized_geometry_rejection(service, coords, settings)


def _realized_geometry_rejection(
    service: GeometryEvaluationService,
    coords: np.ndarray,
    settings: OptimizerSettings,
) -> str:
    """Audit an already realized candidate without repeating its back-transform."""
    realization_status = service.coordinate_realization_status(coords, settings)
    if not realization_status.startswith("valid"):
        return f"coordinate_chart_invalid:{realization_status}"
    if coords.shape[0] < 2:
        return ""
    min_distance = _shortest_pair_within(coords, settings.min_interatomic_distance)
    if min_distance is not None:
        return f"short_contact:{min_distance:.6g}"
    return ""


def _predicted_reduction(
    gradient: np.ndarray, hessian: np.ndarray | None, step: np.ndarray
) -> float:
    if hessian is None:
        return float(-(np.asarray(gradient, dtype=float) @ np.asarray(step, dtype=float)))
    return float(-(gradient @ step + 0.5 * step @ (0.5 * (hessian + hessian.T)) @ step))


def _step_predicted_reduction(
    gradient: np.ndarray,
    hessian: np.ndarray | None,
    step: np.ndarray,
    prediction_function: Callable[[np.ndarray], float] | None,
) -> float:
    if prediction_function is not None:
        predicted = float(prediction_function(np.asarray(step, dtype=float)))
        if not np.isfinite(predicted):
            raise FloatingPointError("step prediction function returned a non-finite reduction")
        return predicted
    return _predicted_reduction(gradient, hessian, step)


def _transition_state_stationarity_norms(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    trial: OptimizerEvaluation,
    current_internal_gradient: np.ndarray,
    settings: OptimizerSettings,
) -> tuple[float | None, float | None]:
    """Return coordinate-invariant current/trial TS residual norms."""

    if settings.stationary_point != "transition_state":
        return None, None
    if current.gradient_hartree_per_bohr is None or trial.gradient_hartree_per_bohr is None:
        return None, None
    # The convergence profile may express TS force in SONIC variables.  A
    # trial's internal gradient is unavailable until acceptance, so compare
    # the two evaluated Cartesian force vectors in this diagnostic instead.
    current_residual = np.asarray(current.gradient_hartree_per_bohr, dtype=float)
    trial_residual = np.asarray(trial.gradient_hartree_per_bohr, dtype=float)
    if not np.all(np.isfinite(current_residual)) or not np.all(np.isfinite(trial_residual)):
        return None, None
    return float(np.linalg.norm(current_residual)), float(np.linalg.norm(trial_residual))


def _restricted_phase_model(
    gradient: np.ndarray,
    hessian: np.ndarray,
    active_mask: np.ndarray,
    settings: OptimizerSettings,
) -> tuple[np.ndarray, np.ndarray]:
    mask = np.asarray(active_mask, dtype=bool).reshape(-1)
    grad = np.where(mask, np.asarray(gradient, dtype=float), 0.0)
    matrix = np.zeros_like(np.asarray(hessian, dtype=float))
    active = np.flatnonzero(mask)
    inactive = np.flatnonzero(~mask)
    matrix[np.ix_(active, active)] = np.asarray(hessian, dtype=float)[np.ix_(active, active)]
    matrix[inactive, inactive] = max(1.0, settings.min_hessian_eigenvalue)
    return grad, 0.5 * (matrix + matrix.T)


def _inter_intra_micro_step(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    gradient: np.ndarray,
    inter_mask: np.ndarray,
    intra_mask: np.ndarray,
    radius: float,
    settings: OptimizerSettings,
) -> StepProposal:
    """Solve the coupled inter/intra quadratic model by a Schur complement."""

    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    grad = np.asarray(gradient, dtype=float).reshape(-1)
    step = np.zeros_like(grad)
    inter = np.asarray(inter_mask, dtype=bool)
    intra = np.asarray(intra_mask, dtype=bool)
    first = np.flatnonzero(inter)
    second = np.flatnonzero(intra)
    if np.intersect1d(first, second).size:
        raise ValueError("coupled inter/intra blocks must be disjoint")
    active = np.concatenate((first, second))
    if active.size == 0:
        raise ValueError("coupled inter/intra solve has no active coordinates")

    minimum = math.inf
    maximum = 0.0
    schur_positive = True

    def inverse_action(block: np.ndarray, right: np.ndarray) -> np.ndarray:
        nonlocal minimum, maximum
        eigenvalues, eigenvectors = np.linalg.eigh(block)
        block_maximum = max(
            float(np.max(np.abs(eigenvalues), initial=0.0)),
            settings.min_hessian_eigenvalue,
        )
        minimum = min(minimum, float(np.min(eigenvalues, initial=math.inf)))
        maximum = max(maximum, block_maximum)
        floor = max(
            settings.min_hessian_eigenvalue,
            block_maximum / settings.max_hessian_condition,
        )
        return eigenvectors @ ((eigenvectors.T @ right) / np.maximum(eigenvalues, floor))

    try:
        if not first.size or not second.size:
            step[active] = -inverse_action(
                matrix[np.ix_(active, active)], grad[active]
            )
        else:
            block_first = matrix[np.ix_(first, first)]
            coupling = matrix[np.ix_(first, second)]
            block_second = matrix[np.ix_(second, second)]
            first_inverse_gradient = inverse_action(block_first, grad[first])
            first_inverse_coupling = inverse_action(block_first, coupling)
            schur = block_second - coupling.T @ first_inverse_coupling
            schur = 0.5 * (schur + schur.T)
            schur_eigenvalues = np.linalg.eigvalsh(schur)
            schur_positive = bool(
                np.min(schur_eigenvalues, initial=math.inf)
                > -settings.min_hessian_eigenvalue
            )
            second_rhs = -grad[second] + coupling.T @ first_inverse_gradient
            second_step = inverse_action(schur, second_rhs)
            first_step = -first_inverse_gradient - first_inverse_coupling @ second_step
            step[first] = first_step
            step[second] = second_step
    except np.linalg.LinAlgError:
        schur_positive = False

    # An indefinite or singular Schur complement means the nominal blocks do
    # not define a stable coupled minimum model.  Route that case through the
    # full safeguarded trust-region kernel instead of hiding it with a
    # sequential block sweep.
    gradient_norm = float(np.linalg.norm(grad))
    matrix_scale = max(maximum, settings.min_hessian_eigenvalue)
    meaningful_step = 1.0e-4 * gradient_norm / matrix_scale
    if (
        not schur_positive
        or
        float(grad @ step) >= 0.0
        or not np.all(np.isfinite(step))
        or float(np.linalg.norm(step)) < meaningful_step
    ):
        fallback = _geometric_trust_region_step(
            service,
            current,
            q,
            matrix,
            grad,
            radius,
            settings,
        )
        return replace(
            fallback,
            policy=f"inter_intra_micro_fallback:{fallback.policy}",
        )
    condition = (
        maximum / max(settings.min_hessian_eigenvalue, minimum)
        if minimum > 0.0
        else settings.max_hessian_condition
    )
    proposal = StepProposal(
        step=step,
        policy="inter_intra_micro_schur_coupled",
        hessian_min_eigenvalue=0.0 if not np.isfinite(minimum) else minimum,
        hessian_condition=float(condition),
        damping_shift=0.0,
    )
    return proposal


def _safeguarded_gdiis_step(
    history: Sequence[tuple[np.ndarray, float, np.ndarray]],
    current_q: np.ndarray,
    current_gradient: np.ndarray,
    hessian: np.ndarray,
    settings: OptimizerSettings,
    *,
    metric: np.ndarray | None = None,
    damping: float = 0.0,
) -> GDIISStepResult:
    """Farkas–Schlegel selection with ONE current shifted RFO Hessian."""
    from .gdiis_farkas_schlegel import controlled_step

    effective, lift, _minimum, _condition, _floor = _minimum_effective_hessian_model(
        hessian,
        settings,
        metric=metric,
    )
    g = lift.T @ np.asarray(current_gradient)
    shifted = effective + max(float(damping), 0.0) * np.eye(len(g))
    augmented = np.zeros((len(g) + 1, len(g) + 1))
    augmented[:-1, :-1] = shifted
    augmented[:-1, -1] = g
    augmented[-1, :-1] = g
    rfo_root = float(np.linalg.eigvalsh(augmented)[0])
    effective = shifted - rfo_root * np.eye(len(g))

    def inverse_action(vector):
        return lift @ np.linalg.solve(effective, lift.T @ vector)

    def vector_map(vector):
        return np.linalg.solve(lift, vector)

    # Gaussian-style geometry DIIS treats the history size as the maximum
    # subspace dimension, not as a requirement to use the last N points.
    # Retain a larger archive and select the nearest points lying in the
    # current local quadratic neighborhood.  This also allows an older point
    # to re-enter when the optimization returns to the same region.
    pool = list(history)
    qualified = pool
    geometry_qualified = len(pool) > settings.gdiis_history
    if geometry_qualified:
        reference = -np.asarray(inverse_action(np.asarray(current_gradient)), dtype=float)
        reference_norm = float(np.linalg.norm(vector_map(reference)))
        cutoff = float(settings.gdiis_geometry_window_factor) * reference_norm
        candidates: list[tuple[float, int, tuple[np.ndarray, float, np.ndarray]]] = []
        for index, record in enumerate(pool):
            displacement = np.asarray(record[0], dtype=float) - np.asarray(current_q, dtype=float)
            distance = float(np.linalg.norm(vector_map(displacement)))
            if np.isfinite(distance) and distance <= cutoff + 1.0e-14:
                candidates.append((distance, index, record))
        candidates.sort(key=lambda item: (item[0], -item[1]))
        selected = candidates[: settings.gdiis_history]
        selected.sort(key=lambda item: item[1])
        qualified = [item[2] for item in selected]
        if len(qualified) < 2:
            return GDIISStepResult(
                None,
                (
                    "geometry_qualified_history_insufficient:"
                    f"eligible={len(qualified)}:pool={len(pool)}:cutoff={cutoff:.8g}"
                ),
                True,
                len(pool),
                len(pool),
                0,
            )

    result = controlled_step(
        qualified,
        current_q,
        current_gradient,
        inverse_action,
        max_history=len(qualified),
        vector_map=vector_map,
    )
    status = result.status
    if geometry_qualified:
        status = f"geometry_qualified:eligible={len(qualified)}:pool={len(pool)}:{status}"
    discarded = 0 if geometry_qualified else result.discarded_points
    return GDIISStepResult(
        result.step,
        status,
        True,
        len(history),
        len(history) - discarded,
        discarded,
    )


def _regularized_gdiis_coefficients(
    eigenvalues: np.ndarray,
    eigenvectors: np.ndarray,
    maximum_coefficient: float,
) -> tuple[np.ndarray | None, float]:
    """Legacy audit helper; not used by controlled Farkas–Schlegel GDIIS.

    Diagonal regularization continuously contracts an otherwise admissible
    Pulay extrapolation toward equal weights.  The smallest shift satisfying
    the coefficient bound is found by bracketing and bisection.
    """

    values = np.asarray(eigenvalues, dtype=float).reshape(-1)
    vectors = np.asarray(eigenvectors, dtype=float)
    if (
        values.size == 0
        or vectors.shape != (values.size, values.size)
        or not np.all(np.isfinite(values))
        or not np.all(np.isfinite(vectors))
        or maximum_coefficient <= 0.0
    ):
        return None, 0.0
    ones = np.ones(values.size, dtype=float)

    def coefficients_at(shift: float) -> np.ndarray | None:
        denominators = values + float(shift)
        if np.any(denominators <= 0.0) or not np.all(np.isfinite(denominators)):
            return None
        inverse_times_ones = vectors @ ((vectors.T @ ones) / denominators)
        denominator = float(ones @ inverse_times_ones)
        if not np.isfinite(denominator) or denominator <= np.finfo(float).eps:
            return None
        coefficients = inverse_times_ones / denominator
        return coefficients if np.all(np.isfinite(coefficients)) else None

    largest = max(float(np.max(np.abs(values), initial=0.0)), 1.0)
    lower = 0.0
    upper = max(np.finfo(float).eps * largest, 1.0e-14)
    candidate = coefficients_at(upper)
    for _ in range(80):
        if candidate is not None and float(np.max(np.abs(candidate))) <= maximum_coefficient:
            break
        upper *= 2.0
        candidate = coefficients_at(upper)
    else:
        return None, 0.0

    for _ in range(80):
        midpoint = 0.5 * (lower + upper)
        trial = coefficients_at(midpoint)
        if trial is not None and float(np.max(np.abs(trial))) <= maximum_coefficient:
            upper = midpoint
            candidate = trial
        else:
            lower = midpoint
    return candidate, upper


def _electronic_state_gap_hartree(
    evaluation: OptimizerEvaluation,
    backend: QMScanBackend | None,
) -> float | None:
    """Return the nearest reported excited-state gap for the active root."""

    if backend is not None and _normalized_backend_name(backend.name) == "capped_subtractive":
        # Component gaps are conservative trust controls, not an excitation
        # spectrum of the composite Hamiltonian.
        components = evaluation.result.execution.get("component_states", ())
        gaps = []
        for term, execution in zip(backend.composite_terms, components, strict=True):
            local = replace(evaluation, result=replace(evaluation.result, execution=dict(execution)))
            gap = _electronic_state_gap_hartree(local, term.backend)
            if gap is not None:
                gaps.append(gap)
        return min(gaps) if gaps else None
    if backend is None or int(backend.electronic_state) <= 0:
        return None
    execution = dict(evaluation.result.execution)
    if execution.get("state_small_gap_symmetry_protected") is True:
        # Different irreducible representations cannot mix.  Returning an
        # explicitly resolved gap releases any earlier same-symmetry
        # hysteresis without invoking conservative geometry controls.
        return float("inf")
    same_symmetry_gap = execution.get("state_same_symmetry_gap_hartree")
    if same_symmetry_gap is not None:
        gap = float(same_symmetry_gap)
        return gap if np.isfinite(gap) else None
    energies_raw = execution.get("excitation_energies_hartree")
    if energies_raw is None:
        return None
    energies = np.asarray(energies_raw, dtype=float).reshape(-1)
    if energies.size < 2 or not np.all(np.isfinite(energies)):
        return None
    state_ids_raw = execution.get("state_ids")
    state_ids = (
        np.arange(1, energies.size + 1, dtype=int)
        if state_ids_raw is None
        else np.asarray(state_ids_raw, dtype=int).reshape(-1)
    )
    if state_ids.shape != energies.shape:
        return None
    selected = int(
        execution.get(
            "selected_electronic_state",
            execution.get("requested_electronic_state", backend.electronic_state),
        )
    )
    matches = np.flatnonzero(state_ids == selected)
    if matches.size != 1:
        return None
    index = int(matches[0])
    differences = np.abs(energies - energies[index])
    differences[index] = np.inf
    gap = float(np.min(differences))
    return gap if np.isfinite(gap) else None


def _gdiis_is_active(iteration: int, settings: OptimizerSettings) -> bool:
    """Return the frozen minimum-protocol activation state for this cycle."""

    return bool(
        settings.enable_gdiis
        and settings.stationary_point == "minimum"
        and int(iteration) >= settings.gdiis_start
    )


def _small_gap_gdiis_history_ready(
    *,
    active: bool,
    history_size: int,
    settings: OptimizerSettings,
) -> bool:
    """Require a fresh local Pulay history after entering a small gap."""

    return bool(not active or int(history_size) >= settings.gdiis_start)


def _small_gap_gradient_growth_requires_trust_reduction(
    *,
    active: bool,
    previous_gradient_inf: float,
    current_gradient_inf: float,
    max_force_tolerance: float,
    trust_ratio: float,
) -> bool:
    """Contract only when gradient growth also exposes a poor local model."""

    gradient_grew = float(current_gradient_inf) > max(
        3.0 * float(max_force_tolerance),
        1.25 * float(previous_gradient_inf),
    )
    ratio = float(trust_ratio)
    poor_model = bool(not np.isfinite(ratio) or ratio < 0.25 or ratio > 2.5)
    return bool(active and gradient_grew and poor_model)


def _accepted_one_sided_plateau_needs_trust_recovery(
    *,
    stationary_point: str,
    gradient_mode: str,
    message: str,
    energy_change_hartree: float,
    trust_radius: float,
    min_trust_radius: float,
    previous_gradient_inf: float,
    current_gradient_inf: float,
    recoveries: int,
    maximum_recoveries: int,
) -> bool:
    """Reset an exhausted minimum trust model after a useful FD plateau step.

    A strictly one-sided derivative can continue decreasing while the scalar
    energy rises by an amount already accepted as an energy plateau.  Treating
    that accepted, gradient-improving step as an immediate terminal stall
    prevents convergence to the stationary point of the frozen numerical
    surface.  The recovery is backend- and molecule-independent and changes
    only optimizer state; the derivative stencil and electronic protocol stay
    untouched.
    """

    radius_at_floor = float(trust_radius) <= float(min_trust_radius) * (
        1.0 + 32.0 * np.finfo(float).eps
    )
    gradient_improved = float(current_gradient_inf) < float(previous_gradient_inf)
    return bool(
        str(stationary_point).strip().casefold() == "minimum"
        and str(gradient_mode).strip().casefold() == "one-sided"
        and str(message) == "accepted_energy_plateau"
        and float(energy_change_hartree) > 0.0
        and radius_at_floor
        and gradient_improved
        and int(recoveries) < int(maximum_recoveries)
    )


def _accepted_two_sided_plateau_needs_trust_recovery(
    *,
    stationary_point: str,
    gradient_mode: str,
    message: str,
    energy_change_hartree: float,
    trust_radius: float,
    min_trust_radius: float,
    previous_gradient_inf: float,
    current_gradient_inf: float,
    recoveries: int,
    maximum_recoveries: int,
) -> bool:
    """Continue after a useful plateau once stall recovery is central.

    The central stencil remains latched.  This only refreshes the local
    optimization model when an accepted, numerically flat step has reduced
    the gradient at the trust-radius floor.
    """

    radius_at_floor = float(trust_radius) <= float(min_trust_radius) * (
        1.0 + 32.0 * np.finfo(float).eps
    )
    gradient_improved = float(current_gradient_inf) < float(previous_gradient_inf)
    return bool(
        str(stationary_point).strip().casefold() == "minimum"
        and str(gradient_mode).strip().casefold() == "two-sided"
        and str(message) == "accepted_energy_plateau"
        and float(energy_change_hartree) > 0.0
        and radius_at_floor
        and gradient_improved
        and int(recoveries) < int(maximum_recoveries)
    )


def _accepted_plateau_needs_restart(
    *,
    stationary_point: str,
    message: str,
    plateau_count: int,
    patience: int,
    step_norm: float,
    step_tolerance: float,
    trust_radius: float,
    min_trust_radius: float,
    recoveries: int,
    maximum_recoveries: int,
) -> bool:
    """Restart a minimum after a persistent plateau and negligible step.

    This backend-independent guard covers analytic-gradient and hybrid paths
    for which the finite-difference-specific recovery predicates cannot fire.
    A trust-radius floor is sufficient, but not necessary: some analytic
    backends retain a large nominal radius while the realized step collapses.
    The realized-step guard catches that case without treating one rounded
    energy value as a restart request.
    """

    radius_at_floor = float(trust_radius) <= float(min_trust_radius) * (
        1.0 + 32.0 * np.finfo(float).eps
    )
    step_is_small = np.isfinite(float(step_norm)) and float(step_norm) <= float(step_tolerance)
    return bool(
        str(stationary_point).strip().casefold() == "minimum"
        and str(message) == "accepted_energy_plateau"
        and int(plateau_count) >= int(patience)
        and (radius_at_floor or step_is_small)
        and int(recoveries) < int(maximum_recoveries)
    )


def _plateau_restart_exhausted(
    *,
    stationary_point: str,
    message: str,
    plateau_count: int,
    patience: int,
    step_norm: float,
    step_tolerance: float,
    trust_radius: float,
    min_trust_radius: float,
    recoveries: int,
    maximum_recoveries: int,
    enabled: bool,
) -> bool:
    """Stop explicitly instead of consuming steps after failed restarts."""

    radius_at_floor = float(trust_radius) <= float(min_trust_radius) * (
        1.0 + 32.0 * np.finfo(float).eps
    )
    step_is_small = np.isfinite(float(step_norm)) and float(step_norm) <= float(step_tolerance)
    return bool(
        bool(enabled)
        and str(stationary_point).strip().casefold() == "minimum"
        and str(message) == "accepted_energy_plateau"
        and int(plateau_count) >= int(patience)
        and (radius_at_floor or step_is_small)
        and int(recoveries) >= int(maximum_recoveries)
    )


def _regularized_gdiis_step_is_preferred(
    status: str,
    gradient: np.ndarray,
    hessian: np.ndarray,
    gdiis_step: np.ndarray,
    model_step: np.ndarray,
) -> bool:
    """Use a regularized Pulay step only when it improves the local model."""

    if ":regularized=" not in str(status):
        return True
    gdiis_reduction = _predicted_reduction(gradient, hessian, gdiis_step)
    model_reduction = _predicted_reduction(gradient, hessian, model_step)
    tolerance = 64.0 * np.finfo(float).eps * max(abs(gdiis_reduction), abs(model_reduction), 1.0)
    return bool(gdiis_reduction + tolerance >= model_reduction)


def _gdiis_step_passes_cauchy_control(
    gradient: np.ndarray,
    hessian: np.ndarray,
    gdiis_step: np.ndarray,
    cauchy_step: np.ndarray,
) -> bool:
    """Require the first GDIIS proposal to beat the Cauchy model floor."""

    gdiis_reduction = _predicted_reduction(gradient, hessian, gdiis_step)
    cauchy_reduction = _predicted_reduction(gradient, hessian, cauchy_step)
    tolerance = 64.0 * np.finfo(float).eps * max(abs(gdiis_reduction), abs(cauchy_reduction), 1.0)
    return bool(
        np.isfinite(gdiis_reduction)
        and gdiis_reduction > 0.0
        and gdiis_reduction + tolerance >= cauchy_reduction
    )


def _minimum_terminal_confirmation_required(
    settings: OptimizerSettings,
    convergence: Mapping[str, bool],
    *,
    phase_is_joint: bool,
    early_force_confirmation: bool,
) -> bool:
    """Request one evaluated, displacement-limited terminal confirmation.

    The force tests characterize the current evaluated geometry, whereas the
    energy and displacement tests characterize the preceding accepted step.
    For an analytic-gradient minimum with explicit interfragment variables,
    once both force tests pass, allowing another unrestricted quasi-Newton
    step can move an already stationary soft complex back out of its terminal
    basin. Rebuild the declared chemical seed, limit the next proposal by the
    two displacement thresholds, and evaluate that geometry with the backend.
    Covalent charts and numerical-gradient protocols retain the established
    energy-plus-force trigger.

    All five convergence tests remain mandatory at the new evaluated point;
    this only makes their terminal confirmation prospective and cannot create
    convergence through a zero or unevaluated step.
    """

    all_stationary_tests = all(
        bool(convergence.get(name, False))
        for name in (
            "energy",
            "max_force",
            "rms_force",
            "max_displacement",
            "rms_displacement",
        )
    )
    if settings.stationary_point != "minimum" or not phase_is_joint:
        return False
    force_satisfied = bool(
        convergence.get("max_force", False) and convergence.get("rms_force", False)
    )
    if early_force_confirmation:
        return bool(force_satisfied and not all_stationary_tests)
    return bool(
        convergence.get("energy", False)
        and force_satisfied
        and not (
            convergence.get("max_displacement", False)
            and convergence.get("rms_displacement", False)
        )
    )


def _transported_optimizer_history(
    service: GeometryEvaluationService,
    history: Sequence[tuple[OptimizerEvaluation, np.ndarray]],
) -> list[tuple[np.ndarray, float, np.ndarray]]:
    """Express saved Cartesian points and forces in the current SONIC chart."""

    transported: list[tuple[np.ndarray, float, np.ndarray]] = []
    for evaluation, saved_gradient in history:
        # Accepted histories are cleared whenever the chart epoch changes.
        # Within one epoch, ``evaluation.q`` is already the actual realized
        # SONIC value and ``saved_gradient`` is the covector evaluated at that
        # same geometry.  Reconstructing both from Cartesian data therefore
        # repeats an identical B-matrix/pseudoinverse calculation at every
        # GDIIS iteration.  Retain the general transport only for callers that
        # deliberately supply an older epoch.
        if evaluation.chart_epoch == service.cache.chart_epoch:
            q_value = np.asarray(evaluation.q, dtype=float).reshape(-1)
            gradient = np.asarray(saved_gradient, dtype=float).reshape(-1)
            if (
                q_value.shape == gradient.shape
                and np.all(np.isfinite(q_value))
                and np.all(np.isfinite(gradient))
            ):
                transported.append((q_value.copy(), evaluation.energy_hartree, gradient.copy()))
                continue
        coordinates = np.asarray(evaluation.coordinates_angstrom, dtype=float)
        q_value = service.actual_q(coordinates)
        cartesian_gradient = evaluation.gradient_hartree_per_bohr
        if cartesian_gradient is None:
            gradient = np.asarray(saved_gradient, dtype=float).copy()
        else:
            directions_bohr = service.coordinate_directions(coordinates) * ANGSTROM_TO_BOHR
            gradient = directions_bohr @ np.asarray(cartesian_gradient, dtype=float).reshape(-1)
        transported.append((q_value, evaluation.energy_hartree, gradient))
    return transported


def _rejected_transition_state_secant_data(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    trial: OptimizerEvaluation,
    current_gradient: np.ndarray,
    settings: OptimizerSettings,
) -> tuple[np.ndarray, np.ndarray, np.ndarray] | None:
    """Return a valid same-epoch analytic secant from a rejected TS trial.

    Rejection keeps the optimizer state fixed, but a finite analytic gradient
    at the evaluated trial still carries local curvature information. This
    helper performs no update itself: the main loop consumes the secant only
    for a model-quality rejection and leaves all update-informativity checks
    to the common Hessian-update path.
    """

    if settings.stationary_point != "transition_state":
        return None
    if current.chart_epoch != trial.chart_epoch:
        return None
    cartesian_gradient = trial.gradient_hartree_per_bohr
    if current.gradient_hartree_per_bohr is None or cartesian_gradient is None:
        return None
    step = np.asarray(trial.q, dtype=float).reshape(-1) - np.asarray(
        current.q, dtype=float
    ).reshape(-1)
    current_covector = np.asarray(current_gradient, dtype=float).reshape(-1)
    if step.shape != current_covector.shape or not np.all(np.isfinite(step)):
        return None
    if float(np.linalg.norm(step)) <= np.finfo(float).eps:
        return None
    directions_bohr = (
        np.asarray(
            service.coordinate_directions(trial.coordinates_angstrom),
            dtype=float,
        )
        * ANGSTROM_TO_BOHR
    )
    trial_covector = directions_bohr @ np.asarray(cartesian_gradient, dtype=float).reshape(-1)
    y = trial_covector - current_covector
    cartesian_step_bohr = (
        aligned_cartesian_displacement(
            current.coordinates_angstrom,
            trial.coordinates_angstrom,
        ).reshape(-1)
        * ANGSTROM_TO_BOHR
    )
    if not all(np.all(np.isfinite(item)) for item in (trial_covector, y, cartesian_step_bohr)):
        return None
    return step, y, cartesian_step_bohr


def _rejected_transition_state_secant_policy(
    message: str,
    secant_available: bool,
) -> bool:
    """DXRFO has no rejected-model secant path in the GDV protocol."""

    del message, secant_available
    return False


def _hessian_secant_update_applied(status: str) -> bool:
    normalized = str(status).lower()
    return "skipped" not in normalized and not normalized.endswith("_rejected")


def _update_hessian(
    hessian: np.ndarray,
    step: np.ndarray,
    y: np.ndarray,
    settings: OptimizerSettings,
    *,
    metric: np.ndarray | None = None,
    coordinate_unit_scales: np.ndarray | None = None,
    far_from_minimum: bool = False,
    cartesian_step_bohr: np.ndarray | None = None,
    self_scale_minimum: bool = False,
) -> tuple[np.ndarray, str]:
    scheme = "bfgs" if far_from_minimum else settings.hessian_update
    if scheme == "auto":
        scheme = "bofill" if settings.stationary_point == "transition_state" else "bfgs"
    base = np.asarray(hessian, dtype=float)
    automatic = settings.hessian_update == "auto"
    status_prefix = f"{'auto_' if automatic else ''}{scheme}"
    if scheme in {"bofill", "bfgs_bofill"} and cartesian_step_bohr is not None:
        cartesian_step = np.asarray(cartesian_step_bohr, dtype=float).reshape(-1)
        if not np.all(np.isfinite(cartesian_step)):
            return 0.5 * (base + base.T), f"{status_prefix}_skipped_nonfinite_cartesian_step"
        maximum = float(np.max(np.abs(cartesian_step))) if cartesian_step.size else 0.0
        rms = _rms(cartesian_step)
        if (
            maximum <= settings.max_displacement_tolerance
            and rms <= settings.rms_displacement_tolerance
        ):
            return 0.5 * (base + base.T), f"{status_prefix}_skipped_subresolution_cartesian_step"
    if scheme == "sr1":
        updated, status = _sr1_update(base, step, y)
    elif scheme == "sella_ts_bfgs":
        updated, status = _sella_ts_bfgs_update(base, step, y)
    elif scheme in {"bofill", "bfgs_bofill"}:
        update = _bofill_update if scheme == "bofill" else _bfgs_bofill_update
        if coordinate_unit_scales is None:
            updated, status = update(base, step, y)
        else:
            unit_scales = np.asarray(coordinate_unit_scales, dtype=float).reshape(-1)
            if (
                unit_scales.shape != np.asarray(step, dtype=float).reshape(-1).shape
                or np.any(~np.isfinite(unit_scales))
                or np.any(unit_scales <= 0.0)
            ):
                raise ValueError("Bofill coordinate-unit scales do not match the secant")
            inverse_unit_scales = 1.0 / unit_scales
            gdv_hessian = inverse_unit_scales[:, None] * base * inverse_unit_scales[None, :]
            gdv_step = unit_scales * np.asarray(step, dtype=float).reshape(-1)
            gdv_y = inverse_unit_scales * np.asarray(y, dtype=float).reshape(-1)
            gdv_updated, status = update(gdv_hessian, gdv_step, gdv_y)
            updated = unit_scales[:, None] * gdv_updated * unit_scales[None, :]
            status += "_gdv_bohr_radian_units"
    else:
        update_base = base
        self_scale = 1.0
        if self_scale_minimum and settings.stationary_point == "minimum":
            secant_step = np.asarray(step, dtype=float).reshape(-1)
            secant_y = np.asarray(y, dtype=float).reshape(-1)
            model_curvature = float(secant_step @ (base @ secant_step))
            observed_curvature = float(secant_step @ secant_y)
            if model_curvature > 1.0e-12 and observed_curvature > 1.0e-12:
                self_scale = float(np.clip(observed_curvature / model_curvature, 0.25, 1.0))
                update_base = self_scale * base
        used_positive_step_base = False
        if settings.stationary_point == "minimum":
            effective, inverse_sqrt_metric, minimum, _condition, _floor = (
                _minimum_effective_hessian_model(base, settings, metric=metric)
            )
            spectral_scale = max(
                1.0,
                float(np.linalg.norm(effective, ord=2)),
            )
            positivity_tolerance = (
                100.0 * np.finfo(float).eps * max(int(base.shape[0]), 1) * spectral_scale
            )
            if minimum <= positivity_tolerance:
                sqrt_metric = np.linalg.inv(inverse_sqrt_metric)
                update_base = sqrt_metric @ effective @ sqrt_metric
                update_base = 0.5 * (update_base + update_base.T)
                used_positive_step_base = True
        updated, status = _bfgs_update(
            update_base,
            step,
            y,
            damp=settings.bfgs_damping,
        )
        if used_positive_step_base:
            if status == "bfgs_skipped_curvature":
                updated = base
            else:
                status += "_from_positive_step_model"
        if self_scale < 1.0:
            status += f"_self_scaled={self_scale:.3g}"
    if automatic:
        status = f"auto_{status}"
    if not _stored_hessian_is_numerically_usable(updated, settings):
        return 0.5 * (
            np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T
        ), f"{status}_rejected"
    return updated, status


def _gdv_d2corx_history_update(
    hessian: np.ndarray,
    *,
    current_q: np.ndarray,
    current_gradient: np.ndarray,
    history: Sequence[tuple[np.ndarray, np.ndarray]],
    settings: OptimizerSettings,
    coordinate_unit_scales: np.ndarray,
) -> tuple[np.ndarray, str]:
    """Apply GDV ``D2CorX`` method 4 to the accepted-point history.

    GDV stores the current point in slot one and up to ``NVar`` previous
    points in reverse chronological slots. ``D2CorX`` visits those slots
    from oldest to newest and applies a Bofill MSP update for every
    admissible secant. The immediately preceding point is exempt from the
    ``RMax`` distance test, exactly as in ``utilam.F``.
    """

    base = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    q_now = np.asarray(current_q, dtype=float).reshape(-1)
    gradient_now = np.asarray(current_gradient, dtype=float).reshape(-1)
    scales = np.asarray(coordinate_unit_scales, dtype=float).reshape(-1)
    if q_now.shape != gradient_now.shape or scales.shape != q_now.shape:
        raise ValueError("GDV D2CorX vectors do not match the Hessian dimension")
    if base.shape != (q_now.size, q_now.size):
        raise ValueError("GDV D2CorX Hessian dimension does not match its vectors")
    if (
        np.any(~np.isfinite(q_now))
        or np.any(~np.isfinite(gradient_now))
        or np.any(~np.isfinite(scales))
        or np.any(scales <= 0.0)
    ):
        raise ValueError("GDV D2CorX requires finite coordinates, gradients, and scales")

    inverse_scales = 1.0 / scales
    gdv_hessian = inverse_scales[:, None] * base * inverse_scales[None, :]
    gdv_q_now = scales * q_now
    gdv_gradient_now = inverse_scales * gradient_now
    retained_history = list(history)[-q_now.size :]
    minimum_distance = 4.0 * float(settings.rms_force_tolerance)
    minimum_distance2 = minimum_distance * minimum_distance
    maximum_distance2 = GDV_D2CORX_MAX_HISTORY_DISTANCE**2
    selected = 0
    selected_weights: list[str] = []
    for history_index, (history_q, history_gradient) in enumerate(retained_history):
        q_old = np.asarray(history_q, dtype=float).reshape(-1)
        gradient_old = np.asarray(history_gradient, dtype=float).reshape(-1)
        if q_old.shape != q_now.shape or gradient_old.shape != q_now.shape:
            raise ValueError("GDV D2CorX history does not match the current point")
        if np.any(~np.isfinite(q_old)) or np.any(~np.isfinite(gradient_old)):
            continue
        step = gdv_q_now - scales * q_old
        gradient_change = gdv_gradient_now - inverse_scales * gradient_old
        distance2 = float(step @ step)
        gradient_distance = float(np.linalg.norm(gradient_change))
        immediate_previous = history_index == len(retained_history) - 1
        if (
            (not immediate_previous and distance2 > maximum_distance2)
            or distance2 < minimum_distance2
            or gradient_distance < GDV_D2CORX_GRADIENT_ERROR
        ):
            continue
        gdv_hessian, status = _bofill_update(
            gdv_hessian,
            step,
            gradient_change,
        )
        selected += 1
        selected_weights.append(status.removeprefix("bofill_msp_"))

    updated = scales[:, None] * gdv_hessian * scales[None, :]
    updated = 0.5 * (updated + updated.T)
    point_count = selected + 1
    weight_status = ",".join(selected_weights) if selected_weights else "none"
    return (
        updated,
        f"auto_bofill_d2corx_points={point_count}_weights={weight_status}_gdv_bohr_radian_units",
    )


def _refresh_transition_index_subspace_from_analytic_gradients(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    q: np.ndarray,
    hessian: np.ndarray,
    settings: OptimizerSettings,
    transition_mode_reference: TransitionModeReference | None,
) -> tuple[np.ndarray, str]:
    """Refresh only the subspace needed to determine first-order inertia.

    This is not a final exact Hessian.  Central analytic-gradient probes span
    the tracked reaction direction and every negative direction of the
    approximate Hessian.  A symmetric block-secant update then replaces only
    information constrained by those probes before the stationary point is
    classified.
    """

    if current.gradient_hartree_per_bohr is None:
        raise ValueError("transition-index subspace refresh needs analytic gradients")
    coordinate_directions = service.coordinate_directions(current.coordinates_angstrom)
    matrix, directions, indices = _transition_index_refresh_basis(
        service,
        current,
        hessian,
        settings,
        transition_mode_reference,
        coordinate_directions,
    )
    cartesian_from_q = np.asarray(coordinate_directions, dtype=float).T
    natoms = max(int(current.coordinates_angstrom.shape[0]), 1)
    directional_gradients = np.zeros_like(directions)
    restart = _restart_evaluation_kwargs(current)

    for column in range(directions.shape[1]):
        directional_gradients[:, column] = _transition_index_probe_gradient(
            service,
            q,
            directions[:, column],
            cartesian_from_q,
            natoms,
            settings,
            column,
            restart,
        )

    before = _optimizer_hessian_index(matrix, settings)
    refreshed = symmetric_multisecant_hessian_refresh(
        matrix,
        directions,
        directional_gradients,
    )
    after = _optimizer_hessian_index(refreshed, settings)
    return (
        refreshed,
        f"transition_index_subspace_refresh_{before}_to_{after}_modes_{indices.size}",
    )


def _transition_index_refresh_basis(
    service: GeometryEvaluationService,
    current: OptimizerEvaluation,
    hessian: np.ndarray,
    settings: OptimizerSettings,
    transition_mode_reference: TransitionModeReference | None,
    coordinate_directions: np.ndarray,
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    matrix = 0.5 * (np.asarray(hessian, dtype=float) + np.asarray(hessian, dtype=float).T)
    orthonormal, inverse_sqrt_metric = _orthonormal_optimizer_hessian(
        matrix,
        service.optimizer_metric(current.coordinates_angstrom),
        settings,
    )
    eigenvalues, eigenvectors = np.linalg.eigh(orthonormal)
    candidates = _cartesian_transition_mode_candidates(
        eigenvectors,
        inverse_sqrt_metric,
        coordinate_directions,
    )
    transition_mode, _overlap, _reference = _select_transition_mode(
        candidates,
        settings,
        transition_mode_reference,
        current.coordinates_angstrom,
        eigenvalues=eigenvalues,
        reaction_directions=_transition_reaction_cartesian_directions(
            service.coordinate_model,
            coordinate_directions,
        ),
    )
    selected = {
        int(index) for index in np.flatnonzero(eigenvalues < -settings.min_hessian_eigenvalue)
    }
    selected.add(int(transition_mode))
    indices = np.asarray(sorted(selected), dtype=int)
    return matrix, inverse_sqrt_metric @ eigenvectors[:, indices], indices


def _transition_index_probe_gradient(
    service: GeometryEvaluationService,
    q: np.ndarray,
    direction: np.ndarray,
    cartesian_from_q: np.ndarray,
    natoms: int,
    settings: OptimizerSettings,
    column: int,
    restart: Mapping[str, object],
) -> np.ndarray:
    cartesian_tangent = cartesian_from_q @ direction
    rms_per_unit = float(np.linalg.norm(cartesian_tangent) / math.sqrt(natoms))
    if not np.isfinite(rms_per_unit) or rms_per_unit <= 1.0e-14:
        raise ValueError("transition-index probe direction has zero Cartesian norm")
    displacement = float(settings.transition_index_probe_rms_angstrom) / rms_per_unit
    evaluations = tuple(
        service.evaluate(
            np.asarray(q, dtype=float) + sign * displacement * direction,
            tag=f"transition-index-{label}-{column}",
            requested_properties=("energy", "gradient"),
            **restart,
        )
        for sign, label in ((1.0, "plus"), (-1.0, "minus"))
    )
    gradients = []
    for evaluation in evaluations:
        cartesian_gradient = evaluation.gradient_hartree_per_bohr
        if cartesian_gradient is None:
            raise RuntimeError("backend omitted a transition-index probe gradient")
        gradients.append(
            (service.coordinate_directions(evaluation.coordinates_angstrom) * ANGSTROM_TO_BOHR)
            @ cartesian_gradient
        )
    return (gradients[0] - gradients[1]) / (2.0 * displacement)


def _transition_state_index_convergence_state(
    hessian: np.ndarray,
    settings: OptimizerSettings,
    *,
    refresh_attempted: bool,
) -> tuple[bool, bool, str | None]:
    """Keep raw Hessian inertia diagnostic, not a convergence hard stop.

    LINK follows an index-one *step model* built from the transported
    ORACLE/SMITH reaction direction.  The raw approximate Hessian index may
    therefore be zero or higher than one during the search and is reported as
    diagnostics rather than used to reject a valid stationary-point search.
    """

    if settings.stationary_point != "transition_state":
        return True, refresh_attempted, None
    return True, refresh_attempted, None


def _geometry_status(reference: np.ndarray, coordinates: np.ndarray) -> str:
    coords = np.asarray(coordinates, dtype=float)
    if coords.shape[0] < 2:
        return "ok"
    min_distance = _shortest_pair_within(coords, 0.35)
    if min_distance is not None:
        return f"short_contact:{min_distance:.6g}"
    displacement = aligned_cartesian_displacement(reference, coordinates)
    max_displacement = float(np.max(np.abs(displacement))) if displacement.size else 0.0
    return f"ok:max_cartesian_displacement={max_displacement:.6g}"


def _shortest_pair_within(coordinates: np.ndarray, cutoff: float) -> float | None:
    """Return the shortest local pair without constructing an all-pairs array."""

    from matrix_chem.spatial_regions import SpatialRegions

    coords = np.asarray(coordinates, dtype=float)
    regions = SpatialRegions.build(coords, cell_size=max(float(cutoff), 0.1))
    shortest: float | None = None
    for left, right in regions.candidate_pairs(float(cutoff)):
        distance = float(np.linalg.norm(coords[left] - coords[right]))
        if shortest is None or distance < shortest:
            shortest = distance
    return shortest


